CREATE OR REPLACE FUNCTION "public"."app_issue_record"("p_kind" "text", "p_fingerprint" "text", "p_title" "text", "p_message" "text", "p_details" "jsonb", "p_path" "text", "p_build" "text", "p_user" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_id uuid;
begin
  update app_issues
     set occurrences = occurrences + 1, last_seen = now(), message = coalesce(p_message, message), updated_at = now()
   where fingerprint = p_fingerprint and status in ('new', 'working', 'needs_sam')
  returning id into v_id;
  if v_id is null then
    insert into app_issues (kind, fingerprint, title, message, details, path, build, reported_by)
    values (p_kind, left(p_fingerprint, 500), left(p_title, 300), left(p_message, 4000), coalesce(p_details, '{}'::jsonb), left(p_path, 500), left(p_build, 80), p_user)
    returning id into v_id;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."app_issue_record"("p_kind" "text", "p_fingerprint" "text", "p_title" "text", "p_message" "text", "p_details" "jsonb", "p_path" "text", "p_build" "text", "p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_mfa_policies"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  t record;
  n integer := 0;
begin
  for t in
    select c.relname
      from pg_class c
      join pg_namespace ns on ns.oid = c.relnamespace
     where ns.nspname = 'public' and c.relkind in ('r', 'p') and c.relrowsecurity
  loop
    execute format('drop policy if exists mfa_required on public.%I', t.relname);
    execute format(
      'create policy mfa_required on public.%I as restrictive for all to authenticated using ((select public.mfa_ok())) with check ((select public.mfa_ok()))',
      t.relname
    );
    n := n + 1;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."apply_mfa_policies"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_meeting_fact"("p_week" "date", "p_candidates" "text"[], "p_reassign" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare chosen text;
begin
  if not is_active() then raise exception 'not permitted'; end if;

  if p_reassign then
    -- "Not this week." The fact goes back in the pool for a later week rather
    -- than being burned, so skipping costs nothing.
    delete from meeting_fact_log where week = p_week;
  else
    select fact_id into chosen from meeting_fact_log where week = p_week;
    if chosen is not null then return chosen; end if;
  end if;

  select c into chosen
    from unnest(p_candidates) with ordinality as t(c, ord)
   where not exists (select 1 from meeting_fact_log l where l.fact_id = t.c)
   order by t.ord
   limit 1;
  if chosen is null then return null; end if;

  -- Bare `do nothing`, not a named target: this can collide on the fact OR on
  -- the week, and either means somebody else got there first.
  insert into meeting_fact_log (fact_id, week) values (chosen, p_week)
  on conflict do nothing;

  -- Whatever the week actually holds now, which may be the other caller's pick.
  select fact_id into chosen from meeting_fact_log where week = p_week;
  return chosen;
end; $$;


ALTER FUNCTION "public"."assign_meeting_fact"("p_week" "date", "p_candidates" "text"[], "p_reassign" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_meeting_fact"("p_week" "date", "p_candidates" "text"[], "p_reassign" boolean) IS 'Get or assign the Monday-meeting fact for a week. Candidates are supplied in priority order by the client; the first never-used one is recorded and returned. Null means the library is exhausted.';



