CREATE OR REPLACE FUNCTION "public"."checklist_add_job"("p_run" "uuid", "p_run_location" "uuid", "p_text" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run checklist_runs%rowtype;
  v_tl uuid;
  v_text text := left(trim(coalesce(p_text, '')), 300);
  v_item uuid;
begin
  if v_text = '' then raise exception 'Type the job first'; end if;
  select * into v_run from checklist_runs where id = p_run;
  if v_run.id is null then raise exception 'No such checklist'; end if;
  if not (is_manager() or (is_active() and checklist_run_is_map(p_run))) then raise exception 'Not allowed'; end if;
  if p_run_location is not null then
    select template_location_id into v_tl from checklist_run_locations where id = p_run_location and run_id = p_run;
    if not found then raise exception 'That place is not on this checklist'; end if;
  end if;

  insert into checklist_run_items (run_id, run_location_id, sort_order, item_text_snapshot, requires_note, checked)
  values (
    p_run, p_run_location,
    coalesce((select max(sort_order) + 1 from checklist_run_items where run_id = p_run), 0),
    v_text, false, false
  )
  returning id into v_item;

  -- Kept for every later year: on the template, under the same place.
  if v_run.template_id is not null and (p_run_location is null or v_tl is not null) then
    insert into checklist_template_items (template_id, location_id, sort_order, text, requires_note)
    values (
      v_run.template_id, v_tl,
      coalesce((select max(sort_order) + 1 from checklist_template_items where template_id = v_run.template_id), 0),
      v_text, false
    );
  end if;
  return v_item;
end;
$$;


ALTER FUNCTION "public"."checklist_add_job"("p_run" "uuid", "p_run_location" "uuid", "p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_note_to_template"("p_run_location" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  rl record;
  v_year int;
  v_who text;
begin
  if not is_active() then raise exception 'Not allowed'; end if;
  select * into rl from checklist_run_locations where id = p_run_location;
  if rl.id is null or rl.template_location_id is null then raise exception 'This place is not on the template any more'; end if;
  if not checklist_run_is_map(rl.run_id) then raise exception 'Not a map checklist'; end if;
  if coalesce(trim(rl.note), '') = '' then raise exception 'There is no note to add'; end if;
  select crop_year into v_year from checklist_runs where id = rl.run_id;
  select full_name into v_who from users where id = coalesce(rl.note_by, auth.uid());
  update checklist_template_locations
     set instructions_md = concat_ws(E'\n\n', nullif(trim(instructions_md), ''), trim(rl.note) || ' (' || v_year || coalesce(', ' || v_who, '') || ')'),
         updated_at = now()
   where id = rl.template_location_id;
end;
$$;


ALTER FUNCTION "public"."checklist_note_to_template"("p_run_location" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_photo_to_template"("p_photo" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  ph record;
  v_tl uuid;
begin
  if not is_active() then raise exception 'Not allowed'; end if;
  select p.*, rl.template_location_id as tl, rl.run_id into ph
    from checklist_photos p join checklist_run_locations rl on rl.id = p.run_location_id
   where p.id = p_photo;
  if ph.id is null then raise exception 'No such photo'; end if;
  if ph.tl is null then raise exception 'This place is not on the template any more'; end if;
  if not checklist_run_is_map(ph.run_id) then raise exception 'Not a map checklist'; end if;
  if exists (select 1 from checklist_photos where template_location_id = ph.tl and storage_path = ph.storage_path) then return; end if;
  insert into checklist_photos (template_location_id, storage_path, caption, created_by)
  values (ph.tl, ph.storage_path, ph.caption, ph.created_by);
end;
$$;


ALTER FUNCTION "public"."checklist_photo_to_template"("p_photo" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_run_is_map"("p_run" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (select 1 from checklist_runs r join checklist_templates t on t.id = r.template_id where r.id = p_run and t.map_based);
$$;


ALTER FUNCTION "public"."checklist_run_is_map"("p_run" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."checklist_snapshot_locations"("p_run" "uuid", "p_template" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  l record;
  v_rl uuid;
  v_order integer := 0;
begin
  insert into checklist_run_items (run_id, sort_order, item_text_snapshot, requires_note)
  select p_run, sort_order, text, requires_note
    from checklist_template_items where template_id = p_template and location_id is null
   order by sort_order;
  select coalesce(max(sort_order), 0) into v_order from checklist_run_items where run_id = p_run;

  for l in select * from checklist_template_locations where template_id = p_template order by sort_order, name loop
    insert into checklist_run_locations (run_id, template_location_id, name, geojson, instructions_md, sort_order, category, colour)
    values (p_run, l.id, l.name, l.geojson, l.instructions_md, l.sort_order, l.category, l.colour)
    returning id into v_rl;
    if exists (select 1 from checklist_template_items where location_id = l.id) then
      insert into checklist_run_items (run_id, run_location_id, sort_order, item_text_snapshot, requires_note)
      select p_run, v_rl, v_order + sort_order, text, requires_note
        from checklist_template_items where location_id = l.id order by sort_order;
    else
      insert into checklist_run_items (run_id, run_location_id, sort_order, item_text_snapshot, requires_note)
      values (p_run, v_rl, v_order + 1, 'Done', false);
    end if;
    v_order := v_order + 1000;
  end loop;
end;
$$;


ALTER FUNCTION "public"."checklist_snapshot_locations"("p_run" "uuid", "p_template" "uuid") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."tv_commands" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "command" "text" NOT NULL,
    "url" "text",
    "requested_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_at" timestamp with time zone,
    "handled_at" timestamp with time zone,
    CONSTRAINT "tv_commands_command_check" CHECK (("command" = ANY (ARRAY['show_app'::"text", 'show_firestick'::"text", 'tv_off'::"text"]))),
    CONSTRAINT "tv_commands_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'claimed'::"text", 'done'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."tv_commands" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_tv_commands"() RETURNS SETOF "public"."tv_commands"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- Anything left waiting while the server was down is dropped, so the TV
  -- never turns on hours after someone walked out of the room.
  update tv_commands
     set status = 'failed', error = 'expired', handled_at = now()
   where status = 'pending'
     and created_at < now() - interval '2 minutes';

  return query
  with picked as (
    select id from tv_commands
     where status = 'pending'
     order by created_at
     for update skip locked
  ), claimed as (
    update tv_commands t
       set status = 'claimed', claimed_at = now()
      from picked
     where t.id = picked.id
    returning t.*
  )
  select * from claimed order by created_at;
end;
$$;


ALTER FUNCTION "public"."claim_tv_commands"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_tv_command"("p_id" "uuid", "p_ok" boolean, "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update tv_commands
     set status     = case when p_ok then 'done' else 'failed' end,
         error      = case when p_ok then null else coalesce(nullif(p_error, ''), 'failed') end,
         handled_at = now()
   where id = p_id;
end;
$$;


ALTER FUNCTION "public"."complete_tv_command"("p_id" "uuid", "p_ok" boolean, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contract_delivered"("p_contract" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_contract is null then return; end if;
  update contracts
     set delivered_bu =
           coalesce((select sum(net_units) from scale_tickets where contract_id = p_contract), 0)
         + coalesce((select sum(load_units(l.id))
                       from bin_loads l
                      where l.contract_id = p_contract
                        and l.gross_kg is not null and l.tare_kg is not null
                        and not exists (select 1 from scale_tickets t where t.bin_load_id = l.id)), 0)
   where id = p_contract;
end $$;


ALTER FUNCTION "public"."contract_delivered"("p_contract" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_bale_check_task"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_title text := 'Monthly bale temperature & moisture check';
  v_month date := date_trunc('month', now() at time zone 'America/Edmonton')::date;
  v_who uuid[];
  v_task uuid;
begin
  select array(select jsonb_array_elements_text(value)::uuid) into v_who
    from operating_settings where key = 'bale_check_assignees';
  if coalesce(array_length(v_who, 1), 0) = 0 then return null; end if;
  -- Once a month, however often this runs.
  if exists (select 1 from tasks where title = v_title and (created_at at time zone 'America/Edmonton')::date >= v_month) then return null; end if;
  -- created_by is required and a scheduled job has no user: the first person
  -- it is for stands as its author (which also spares them a "completed"
  -- notification about their own task).
  insert into tasks (title, description_md, due_at, reminder_at, status, source, created_by)
  values (
    v_title,
    'Probe a couple of bales of each kind at each yard — core temperature and moisture — and log them: [open the bale check form](/bale-checks?new=1). Saving the check closes this task.',
    (v_month + 7)::timestamptz + interval '15 hours',
    now(),
    'open',
    'manual',
    v_who[1]
  )
  returning id into v_task;
  insert into task_assignees (task_id, user_id) select v_task, u from unnest(v_who) u on conflict do nothing;
  return v_task;
end;
$$;


ALTER FUNCTION "public"."create_bale_check_task"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_checklist_run"("p_template_id" "uuid", "p_assigned_to" "uuid"[], "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_crop_year" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run_id  uuid;
  v_task_id uuid;
  v_name    text;
  v_year    int := coalesce(p_crop_year, date_part('year', now())::int);
begin
  if not is_manager() then
    raise exception 'Only managers can start checklist runs';
  end if;
  select name into v_name from checklist_templates where id = p_template_id;
  if v_name is null then raise exception 'Template not found'; end if;

  insert into checklist_runs (template_id, crop_year, name, assigned_to, due_at, created_by)
  values (p_template_id, v_year, v_name, coalesce(p_assigned_to, '{}'), p_due_at, auth.uid())
  returning id into v_run_id;

  perform checklist_snapshot_locations(v_run_id, p_template_id);

  if coalesce(array_length(p_assigned_to, 1), 0) > 0 then
    insert into tasks (title, created_by, due_at, source, source_ref, crop_year)
    values ('Checklist: ' || v_name, auth.uid(), p_due_at, 'checklist', v_run_id, v_year)
    returning id into v_task_id;
    insert into task_assignees (task_id, user_id, assigned_by)
    select v_task_id, u, auth.uid() from unnest(p_assigned_to) u
    on conflict do nothing;
  end if;

  return v_run_id;
end;
$$;


ALTER FUNCTION "public"."create_checklist_run"("p_template_id" "uuid", "p_assigned_to" "uuid"[], "p_due_at" timestamp with time zone, "p_crop_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_n_rich_strip"("p_field" "uuid", "p_year" integer, "p_width_m" numeric DEFAULT 18.3, "p_offset_m" numeric DEFAULT 0, "p_extra_lb" numeric DEFAULT 50, "p_heading_deg" numeric DEFAULT NULL::numeric) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  g geometry;
  srid integer;
  c geometry;
  env geometry;
  az double precision;
  rot geometry;
  x0 double precision;
  s geometry;
  p1 geometry; p2 geometry; p3 geometry;
  new_id uuid;
begin
  select coalesce(b.boundary_analysis, b.geom) into g
    from field_boundaries b
   where b.field_id = p_field and b.valid_to is null
   order by b.valid_from desc nulls last limit 1;
  if g is null then raise exception 'That field has no boundary to lay a strip in.'; end if;
  srid := 32600 + floor((st_x(st_centroid(g)) + 180) / 6)::integer + 1;
  g := st_transform(g, srid);
  c := st_centroid(g);
  if p_heading_deg is not null then
    az := radians(p_heading_deg);
  else
    env := st_orientedenvelope(g);
    p1 := st_pointn(st_exteriorring(env), 1);
    p2 := st_pointn(st_exteriorring(env), 2);
    p3 := st_pointn(st_exteriorring(env), 3);
    az := case when st_distance(p1, p2) >= st_distance(p2, p3) then st_azimuth(p1, p2) else st_azimuth(p2, p3) end;
  end if;
  rot := st_rotate(g, az, c);
  x0 := st_x(c) + p_offset_m - p_width_m / 2.0;
  s := st_intersection(rot, st_makeenvelope(x0, st_ymin(rot) - 10, x0 + p_width_m, st_ymax(rot) + 10, srid));
  s := st_multi(st_collectionextract(st_transform(st_rotate(s, -az, c), 4326), 3));
  if st_isempty(s) then raise exception 'That offset puts the strip outside the field.'; end if;
  insert into n_rich_strips (field_id, crop_year, label, geom, extra_lb_n)
  values (p_field, p_year, 'N-rich strip', s, p_extra_lb)
  returning id into new_id;
  return new_id;
end $$;


ALTER FUNCTION "public"."create_n_rich_strip"("p_field" "uuid", "p_year" integer, "p_width_m" numeric, "p_offset_m" numeric, "p_extra_lb" numeric, "p_heading_deg" numeric) OWNER TO "postgres";


