CREATE OR REPLACE FUNCTION "public"."drive_backup_finished"("p_run" "uuid", "p_status" "text", "p_made" integer, "p_skipped" "jsonb", "p_errors" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.can_see_finances() then
    raise exception 'Only the owners and the farm''s accountant run the backup';
  end if;
  update drive_backup_runs
     set finished_at = now(), status = p_status, made = p_made, skipped = coalesce(p_skipped, '[]'::jsonb), errors = coalesce(p_errors, '[]'::jsonb)
   where id = p_run;
  update integration_health
     set status = case when p_status = 'done' then 'ok' else 'error' end,
         detail = format('%s files backed up%s', p_made, case when jsonb_array_length(coalesce(p_errors, '[]'::jsonb)) > 0 then format(', %s failed', jsonb_array_length(p_errors)) else '' end),
         last_checked_at = now(),
         last_success_at = case when p_status = 'done' then now() else last_success_at end,
         data_at = now(),
         consecutive_fail = case when p_status = 'done' then 0 else consecutive_fail + 1 end,
         updated_at = now()
   where source_key = 'google_drive_backup';
end;
$$;


ALTER FUNCTION "public"."drive_backup_finished"("p_run" "uuid", "p_status" "text", "p_made" integer, "p_skipped" "jsonb", "p_errors" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dry_shrink"("p_moisture" numeric, "p_dry" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case when p_moisture is null or p_dry is null or p_moisture <= p_dry then 1
              else (100 - p_moisture) / (100 - p_dry) end
$$;


ALTER FUNCTION "public"."dry_shrink"("p_moisture" numeric, "p_dry" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_checklist_year_run"("p_template" "uuid", "p_year" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_year      int := coalesce(p_year, date_part('year', now() at time zone 'America/Edmonton')::int);
  v_run       uuid;
  v_name      text;
  v_assignees uuid[];
  v_by        uuid;
  v_task      uuid;
begin
  if auth.uid() is not null and not is_active() then raise exception 'Not allowed'; end if;
  select name, default_assignees into v_name, v_assignees from checklist_templates where id = p_template and yearly and active;
  if v_name is null then raise exception 'Not a yearly checklist'; end if;
  -- One per template and year, even with two people opening it at once.
  perform pg_advisory_xact_lock(hashtext('checklist-year:' || p_template::text || ':' || v_year));
  select id into v_run from checklist_runs where template_id = p_template and crop_year = v_year order by created_at limit 1;
  if v_run is not null then return v_run; end if;

  -- Only people who can still sign in.
  select coalesce(array_agg(u.id), '{}') into v_assignees
    from users u where u.id = any(coalesce(v_assignees, '{}')) and u.active;

  insert into checklist_runs (template_id, crop_year, name, assigned_to, created_by)
  values (p_template, v_year, v_name || ' ' || v_year, v_assignees, auth.uid())
  returning id into v_run;
  perform checklist_snapshot_locations(v_run, p_template);

  if coalesce(array_length(v_assignees, 1), 0) > 0 then
    -- A task needs an author; the scheduled job has no signed-in user, so the farm's first admin.
    v_by := coalesce(auth.uid(), (select id from users where role = 'admin' and active order by created_at limit 1), v_assignees[1]);
    insert into tasks (title, created_by, source, source_ref, crop_year)
    values ('Checklist: ' || v_name || ' ' || v_year, v_by, 'checklist', v_run, v_year)
    returning id into v_task;
    insert into task_assignees (task_id, user_id, assigned_by)
    select v_task, u, v_by from unnest(v_assignees) u
    on conflict do nothing;
  end if;

  return v_run;
end;
$$;


ALTER FUNCTION "public"."ensure_checklist_year_run"("p_template" "uuid", "p_year" integer) OWNER TO "postgres";


