CREATE OR REPLACE FUNCTION "public"."farm_fixed_land_share"("p_year" integer) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  s record;
  v_rented numeric;
  v numeric;
begin
  select * into s from farm_fixed_costs where crop_year <= p_year order by crop_year desc limit 1;
  if s is null or s.mode <> 'breakdown' then
    return null;
  end if;
  v_rented := coalesce(farm_rented_out_acres(s.crop_year), 0);
  select case
           when l.basis = 'per_acre' then l.amount
           when s.spread_acres > 0 then l.amount / (s.spread_acres + v_rented)
         end
    into v
    from farm_fixed_cost_lines l
   where l.crop_year = s.crop_year and l.category = 'land';
  return round(v, 2);
end;
$$;


ALTER FUNCTION "public"."farm_fixed_land_share"("p_year" integer) OWNER TO "postgres";


