CREATE OR REPLACE FUNCTION "public"."farm_plan_acres"("p_year" integer) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with areas as (
    -- A field split on the map: each crop area, by its own crop.
    select z.field_id, z.crop_id, z.acres
      from field_crop_zones z
     where z.crop_year = p_year
    union all
    -- Any other planned field: its plan, at the plan's acres or the boundary.
    select p.field_id, p.crop_id, coalesce(p.planned_acres, b.acres)
      from crop_plans p
      left join lateral (
        select fb.acres from field_boundaries fb
         where fb.field_id = p.field_id
           and fb.valid_from <= make_date(p_year, 12, 31)
           and (fb.valid_to is null or fb.valid_to > make_date(p_year, 12, 31))
         order by fb.valid_from desc
         limit 1
      ) b on true
     where p.crop_year = p_year
       and not exists (select 1 from field_crop_zones z where z.field_id = p.field_id and z.crop_year = p_year)
  )
  select coalesce(sum(a.acres), 0)
    from areas a
    join crops c on c.id = a.crop_id
   where c.fixed_costs_apply
     and not c.land_rent_only
     -- A renter's crop is ours only on our land under the grower's deal.
     and (not c.renter_only or exists (
           select 1 from land_leases l
            where l.direction = 'out' and l.active
              and a.field_id = any (l.field_ids)
              and (l.crop_ids is null or cardinality(l.crop_ids) = 0 or a.crop_id = any (l.crop_ids))
              and (l.start_date is null or l.start_date <= make_date(p_year, 12, 31))
              and (l.end_date is null or l.end_date >= make_date(p_year, 1, 1))));
$$;


ALTER FUNCTION "public"."farm_plan_acres"("p_year" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."farm_plan_acres"("p_year" integer) IS 'Acres in a crop year that are charged the farm''s fixed $/ac: crop areas on a split field, else the plan; only crops that carry fixed costs, never a crop the land is only rented out for, and a renter''s crop only on our land under a grower''s deal.';



CREATE OR REPLACE FUNCTION "public"."farm_rented_out_acres"("p_year" integer) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with areas as (
    select z.field_id, z.crop_id, z.acres
      from field_crop_zones z
     where z.crop_year = p_year
    union all
    select p.field_id, p.crop_id, coalesce(p.planned_acres, b.acres)
      from crop_plans p
      left join lateral (
        select fb.acres from field_boundaries fb
         where fb.field_id = p.field_id
           and fb.valid_from <= make_date(p_year, 12, 31)
           and (fb.valid_to is null or fb.valid_to > make_date(p_year, 12, 31))
         order by fb.valid_from desc
         limit 1
      ) b on true
     where p.crop_year = p_year
       and not exists (select 1 from field_crop_zones z where z.field_id = p.field_id and z.crop_year = p_year)
  )
  select coalesce(sum(a.acres), 0)
    from areas a
    join crops c on c.id = a.crop_id
   where c.land_rent_only and c.fixed_costs_apply;
$$;


ALTER FUNCTION "public"."farm_rented_out_acres"("p_year" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."farm_rented_out_acres"("p_year" integer) IS 'Acres of land rented out (crops.land_rent_only) in a crop year that carry the land share of the fixed expenses.';



