CREATE OR REPLACE FUNCTION "public"."field_scale_yield"("p_field" "uuid", "p_crop" "uuid", "p_year" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_final boolean;
  v_unit  yield_unit;
  v_tw    numeric;
  v_dry   numeric;
  v_loads integer;
  v_bu    numeric;
  v_lb    numeric;
  v_wbu   numeric;
  v_wlb   numeric;
  s_loads integer;
  s_bu    numeric;
  s_lb    numeric;
  s_wbu   numeric;
  s_wlb   numeric;
  v_total numeric;
  v_wet   numeric;
  v_acres numeric;
  v_hist  crop_history%rowtype;
  v_variety text;
begin
  if p_field is null or p_crop is null or p_year is null then return; end if;
  if crop_year_locked(p_year) then return; end if;

  select * into v_hist from crop_history where field_id = p_field and crop_year = p_year;
  if v_hist.id is not null and v_hist.crop_id <> p_crop then return; end if;

  select exists (
    select 1 from bin_loads
     where field_id = p_field and crop_id = p_crop and crop_year = p_year
       and last_from_field and (bin_id is not null or delivery_site_id is not null)
       and gross_kg is not null and tare_kg is not null
  ) into v_final;

  perform set_config('rvr.scale_yield', 'on', true);

  if not v_final then
    if v_hist.id is not null and v_hist.scale_at is not null then
      update crop_history
         set scale_total = null, scale_wet_total = null, scale_acres = null, scale_loads = null, scale_at = null,
             actual_yield_total = case when yield_override then actual_yield_total end,
             yield_per_acre     = case when yield_override then yield_per_acre end
       where id = v_hist.id;
    end if;
    perform set_config('rvr.scale_yield', 'off', true);
    return;
  end if;

  select yield_unit, test_weight_lb_per_bu, moisture_dry_max into v_unit, v_tw, v_dry from crops where id = p_crop;

  select count(*),
         coalesce(sum(m.bushels * dry_shrink(load_moisture(l.id), v_dry)), 0),
         coalesce(sum(m.bushels * coalesce(l.lb_per_bu, v_tw) * dry_shrink(load_moisture(l.id), v_dry)), 0),
         coalesce(sum(m.bushels), 0),
         coalesce(sum(m.bushels * coalesce(l.lb_per_bu, v_tw)), 0)
    into v_loads, v_bu, v_lb, v_wbu, v_wlb
    from grain_movements m
    left join bin_loads l on m.ticket_number = 'load:' || l.id::text
   where m.movement_type = 'harvest_in'
     and m.field_id = p_field and m.crop_id = p_crop and m.crop_year = p_year;

  select count(*),
         coalesce(sum(bushels * dry_shrink(load_moisture(id), v_dry)), 0),
         coalesce(sum(net_kg * 2.20462262 * dry_shrink(load_moisture(id), v_dry)), 0),
         coalesce(sum(bushels), 0),
         coalesce(sum(net_kg * 2.20462262), 0)
    into s_loads, s_bu, s_lb, s_wbu, s_wlb
    from bin_loads
   where delivery_site_id is not null and gross_kg is not null and tare_kg is not null
     and field_id = p_field and crop_id = p_crop and crop_year = p_year;

  v_loads := v_loads + s_loads;
  v_bu := v_bu + s_bu;
  v_lb := v_lb + s_lb;
  v_wbu := v_wbu + s_wbu;
  v_wlb := v_wlb + s_wlb;

  v_total := case v_unit
               when 'bu'  then v_bu
               when 'lbs' then v_lb
               when 'cwt' then v_lb / 100
               when 'ton' then v_lb / 2000
               when 'MT'  then v_lb / 2204.62262
               else v_bu
             end;
  v_wet := case v_unit
             when 'bu'  then v_wbu
             when 'lbs' then v_wlb
             when 'cwt' then v_wlb / 100
             when 'ton' then v_wlb / 2000
             when 'MT'  then v_wlb / 2204.62262
             else v_wbu
           end;
  if v_total is null or v_total = 0 and v_bu > 0 then
    v_total := v_bu;
    v_wet := v_wbu;
    v_unit := 'bu';
  end if;

  select variety into v_variety from crop_plans
   where field_id = p_field and crop_id = p_crop and crop_year = p_year limit 1;
  v_acres := coalesce(
    v_hist.acres,
    field_mapped_acres(p_field),
    (select planned_acres from crop_plans where field_id = p_field and crop_id = p_crop and crop_year = p_year limit 1)
  );

  if v_hist.id is null then
    insert into crop_history (crop_year, field_id, crop_id, variety, acres, source, source_note)
    values (p_year, p_field, p_crop, v_variety, v_acres, 'scale', 'From the scale loads, last load marked')
    returning * into v_hist;
  end if;

  update crop_history
     set scale_total = round(v_total, 1),
         scale_wet_total = case when round(v_wet, 1) <> round(v_total, 1) then round(v_wet, 1) end,
         scale_acres = v_acres,
         scale_loads = v_loads,
         scale_at = now(),
         acres = coalesce(acres, v_acres),
         actual_yield_total = case when yield_override then actual_yield_total else round(v_total) end,
         yield_per_acre = case
                            when yield_override then yield_per_acre
                            when coalesce(v_acres, 0) > 0 then round(v_total / v_acres, 1)
                          end,
         yield_unit = case when yield_override then yield_unit else v_unit end,
         source = case when yield_override then source else 'scale' end
   where id = v_hist.id;

  perform set_config('rvr.scale_yield', 'off', true);
end $$;


ALTER FUNCTION "public"."field_scale_yield"("p_field" "uuid", "p_crop" "uuid", "p_year" integer) OWNER TO "postgres";


