    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not is_manager() then
    raise exception 'Only managers can apply a hail inspection';
  end if;
  perform public.fn_apply_hail_inspection_internal(p_id, auth.uid());
end;
$$;


ALTER FUNCTION "public"."fn_apply_hail_inspection"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_apply_hail_inspection_internal"("p_id" "uuid", "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  insp public.hail_inspections;
begin
  select * into insp from public.hail_inspections where id = p_id;
  if insp is null then raise exception 'No such inspection'; end if;
  if insp.field_id is null then
    raise exception 'That inspection is not matched to a field yet';
  end if;

  if not exists (
    select 1 from public.field_hail_events
     where field_id = insp.field_id
       and notes like '%' || insp.inspection_number || '%'
  ) then
    insert into public.field_hail_events (field_id, crop_year, event_date, notes, loss_pct, acres, created_by)
    values (
      insp.field_id,
      extract(year from coalesce(insp.damage_date, insp.report_date, now()))::int,
      coalesce(insp.damage_date, insp.report_date, current_date),
      format(
        'AFSC inspection %s — %s%% loss on %s acres%s',
        insp.inspection_number,
        coalesce(insp.loss_pct::text, '?'),
        coalesce(insp.acres::text, '?'),
        case when insp.adjuster is null then '' else ', adjuster ' || insp.adjuster end
      ),
      insp.loss_pct,
      insp.acres,
      p_actor
    );
  end if;

  update public.hail_inspections
     set status = 'applied', applied_at = now(), applied_by = p_actor
   where id = p_id;
end;
$$;


ALTER FUNCTION "public"."fn_apply_hail_inspection_internal"("p_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


