CREATE OR REPLACE FUNCTION "public"."fn_area_weighted_depth"("p_sectors" "jsonb", "p_zone" "public"."geometry") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  with feats as (
    select
      (f->'properties'->>'depth')::numeric as depth,
      st_setsrid(st_geomfromgeojson(f->'geometry'), 4326) as geom
    from jsonb_array_elements(coalesce(p_sectors->'features', '[]'::jsonb)) as f
    where f->'properties'->>'depth' is not null
      and f->'geometry' is not null
  ),
  weighted as (
    select
      depth,
      -- Cast to geography so area is in square metres on the spheroid rather
      -- than square degrees, which vary with latitude and would quietly weight
      -- northern sectors differently from southern ones.
      case
        when p_zone is null then st_area(geom::geography)
        else st_area(st_intersection(geom, p_zone)::geography)
      end as wt
    from feats
    where p_zone is null or st_intersects(geom, p_zone)
  )
  select case
    when coalesce(sum(wt), 0) <= 0 then 0
    else round((sum(depth * wt) / sum(wt))::numeric, 2)
  end
  from weighted;
$$;


ALTER FUNCTION "public"."fn_area_weighted_depth"("p_sectors" "jsonb", "p_zone" "public"."geometry") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_area_weighted_depth"("p_sectors" "jsonb", "p_zone" "public"."geometry") IS 'Area-weighted mean applied depth (mm) of FieldNET sector polygons, optionally clipped to a zone. p_zone null = whole ring, which must reproduce the pre-zone whole-field figure.';



CREATE OR REPLACE FUNCTION "public"."fn_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_old jsonb;
  v_new jsonb;
  v_id uuid;
  v_year int;
begin
  if tg_op <> 'INSERT' then v_old := to_jsonb(old); end if;
  if tg_op <> 'DELETE' then v_new := to_jsonb(new); end if;
  v_id   := coalesce((v_new ->> 'id')::uuid, (v_old ->> 'id')::uuid);
  v_year := coalesce((v_new ->> 'crop_year')::int, (v_old ->> 'crop_year')::int);
  insert into audit_log (table_name, record_id, action, actor_id, actor_role,
                         old_values, new_values, crop_year)
  values (tg_table_name, v_id, lower(tg_op), auth.uid(),
          (select role::text from users where id = auth.uid()),
          v_old, v_new, v_year);
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."fn_audit"() OWNER TO "postgres";


