CREATE OR REPLACE FUNCTION "public"."fn_bin_load_contract"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op <> 'INSERT' and old.contract_id is not null then
    perform contract_delivered(old.contract_id);
  end if;
  if tg_op <> 'DELETE' and new.contract_id is not null
     and (tg_op = 'INSERT' or new.contract_id is distinct from old.contract_id
          or new.gross_kg is distinct from old.gross_kg or new.tare_kg is distinct from old.tare_kg
          or new.lb_per_bu is distinct from old.lb_per_bu or new.crop_id is distinct from old.crop_id) then
    perform contract_delivered(new.contract_id);
  end if;
  return null;
end $$;


