CREATE OR REPLACE FUNCTION "public"."fn_bin_load_field_yield"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- Bin loads reach the yield through their movement; these are the cases
  -- with no movement to carry them: a plant load, or only the mark changing.
  if tg_op in ('UPDATE', 'DELETE') and (old.delivery_site_id is not null or old.last_from_field) then
    perform field_scale_yield(old.field_id, old.crop_id, old.crop_year);
  end if;
  if tg_op in ('INSERT', 'UPDATE') and (new.delivery_site_id is not null
       or (tg_op = 'UPDATE' and new.last_from_field is distinct from old.last_from_field)
       or (tg_op = 'INSERT' and new.last_from_field)) then
    perform field_scale_yield(new.field_id, new.crop_id, new.crop_year);
  end if;
  return null;
end $$;


