CREATE OR REPLACE FUNCTION "public"."fn_boundary_acres_to_plans"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.valid_to is not null or new.acres is null or new.acres <= 0 then return null; end if;
  update crop_plans p
     set planned_acres = round(new.acres, 2)
   where p.field_id = new.field_id
     and not crop_year_locked(p.crop_year)
     and p.crop_year >= date_part('year', now())::int
     and not exists (select 1 from field_crop_zones z where z.field_id = p.field_id and z.crop_year = p.crop_year)
     and p.planned_acres is distinct from round(new.acres, 2);
  return null;
end $$;


