CREATE OR REPLACE FUNCTION "public"."fn_classify_operations"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare n integer := 0; m integer;
begin
  -- Recomputed from scratch each time, so taking a renter crop or a rented
  -- year off un-marks its passes. A manager's own choice is never touched.
  update jd_field_operations set not_ours = null, not_ours_by = null, not_ours_note = null
   where not_ours_by = 'auto';

  -- Only Deere's own hand entries wait for confirmation; an app record was
  -- typed from an invoice.
  update jd_field_operations o set confirm_status = 'pending'
   where o.crop_season >= 2026 and o.operation_type = 'application' and o.machine_id is null
     and o.source = 'deere'
     and o.confirm_status is null and o.duplicate_of is null
     and coalesce(o.applied_area_ha, 0) = 0
     and not exists (
       select 1 from jsonb_array_elements(coalesce(o.as_applied, '[]')) a
        where not coalesce((a->>'carrier')::boolean, false) and coalesce((a->>'totalValue')::numeric, 0) > 0);
  get diagnostics m = row_count; n := n + m;

  update jd_field_operations o set not_ours = 'rented_out', not_ours_by = 'auto',
         not_ours_note = coalesce('Field rented to ' || t.rented_to || ' in ' || t.crop_year, 'Field rented out in ' || t.crop_year)
    from field_year_tenure t
   where t.field_id = o.field_id and t.crop_year = o.crop_season and o.crop_season >= 2026
     and o.not_ours_by is null;
  get diagnostics m = row_count; n := n + m;

  update jd_field_operations o set not_ours = 'custom_work', not_ours_by = 'auto',
         not_ours_note = 'Renter''s ' || f.rented_out_crop || ' — our sprayer, their crop'
    from fields f
   where f.id = o.field_id and f.rented_out_crop is not null and o.crop_season >= 2026
     and o.treated_crop ilike '%' || f.rented_out_crop || '%'
     and o.not_ours_by is null;
  get diagnostics m = row_count; n := n + m;
  return n;
end $$;


ALTER FUNCTION "public"."fn_classify_operations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_clay_awc"("clay" numeric) RETURNS TABLE("awc_mm_m" numeric, "wp_mm_10cm" numeric, "label" "text")
    LANGUAGE "sql" IMMUTABLE
    AS $$
  with pts(c, awc, wp) as (values (8::numeric, 112::numeric, 6::numeric), (14, 140, 8), (22, 180, 13), (31, 200, 16), (45, 192, 22)),
  x as (select greatest(8, least(45, clay)) as v),
  seg as (
    select p1.c c1, p1.awc a1, p1.wp w1, p2.c c2, p2.awc a2, p2.wp w2
    from pts p1 join pts p2 on p2.c = (select min(c) from pts where c > p1.c)
    where p1.c <= (select v from x) and p2.c >= (select v from x)
    limit 1
  )
  select round(a1 + (a2 - a1) * ((select v from x) - c1) / (c2 - c1), 0),
         round(w1 + (w2 - w1) * ((select v from x) - c1) / (c2 - c1), 1),
         case when clay < 10 then 'Loamy sand' when clay < 18 then 'Sandy loam' when clay < 27 then 'Loam'
              when clay < 35 then 'Clay loam' else 'Clay' end
  from seg;
$$;


ALTER FUNCTION "public"."fn_clay_awc"("clay" numeric) OWNER TO "postgres";


