CREATE OR REPLACE FUNCTION "public"."fn_crop_average_crop_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_s uuid;
begin
  if new.average_of is distinct from old.average_of then
    perform fn_crop_average_sync(new.id);
  end if;
  if new.default_yield_per_acre is distinct from old.default_yield_per_acre
     or new.sister_value_per_acre is distinct from old.sister_value_per_acre then
    for v_s in select s.id from crops s where new.id = any(s.average_of) and s.id <> new.id loop
      perform fn_crop_average_sync(v_s);
    end loop;
  end if;
  return null;
end;
$$;


