CREATE OR REPLACE FUNCTION "public"."fn_crop_average_member_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ids uuid[];
  v_s uuid;
begin
  if tg_op = 'DELETE' then
    v_ids := array[old.crop_id];
  elsif tg_op = 'INSERT' then
    v_ids := array[new.crop_id];
  else
    v_ids := array[old.crop_id, new.crop_id];
  end if;
  -- The fixed-expense rows are the same on every crop and move by themselves.
  if tg_table_name = 'crop_inputs' then
    if tg_op <> 'DELETE' then
      if new.farm_fixed then return null; end if;
    end if;
    if tg_op <> 'INSERT' then
      if old.farm_fixed then return null; end if;
    end if;
  end if;
  v_ids := array_remove(v_ids, null);
  for v_s in
    select s.id from crops s where s.average_of && v_ids and s.id <> all(v_ids)
  loop
    perform fn_crop_average_sync(v_s);
  end loop;
  return null;
end;
$$;


ALTER FUNCTION "public"."fn_crop_average_member_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_crop_average_sync"("p_crop" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_members uuid[];
  v_current int := date_part('year', now())::int;
  v_year int;
  v_yield numeric;
  v_sister numeric;
  v_price numeric;
  v_cost numeric;
  v_line constant text := 'Average of the company budgets';
begin
  select average_of into v_members from crops where id = p_crop;
  if v_members is null or cardinality(v_members) = 0 then
    return;
  end if;

  select round(avg(default_yield_per_acre), 2), round(avg(sister_value_per_acre), 2)
    into v_yield, v_sister
    from crops where id = any(v_members);
  update crops
     set default_yield_per_acre = v_yield, sister_value_per_acre = v_sister
   where id = p_crop
     and (default_yield_per_acre is distinct from v_yield or sister_value_per_acre is distinct from v_sister);

  -- Prices.
  for v_year in
    select distinct crop_year from crop_prices
     where (crop_id = any(v_members) or crop_id = p_crop)
       and (crop_year >= v_current or crop_year in (select crop_year from year_unlocks))
  loop
    select round(avg(p.price), 4) into v_price
      from unnest(v_members) m(id)
      cross join lateral (
        select price_per_unit as price from crop_prices
         where crop_id = m.id and crop_year <= v_year and price_per_unit is not null
         order by crop_year desc limit 1
      ) p;
    if v_price is null then
      delete from crop_prices where crop_id = p_crop and crop_year = v_year;
    else
      insert into crop_prices (crop_id, crop_year, price_per_unit) values (p_crop, v_year, v_price)
      on conflict (crop_id, crop_year) do update set price_per_unit = excluded.price_per_unit
       where crop_prices.price_per_unit is distinct from excluded.price_per_unit;
    end if;
  end loop;

  -- Input budgets: one line, the average of each member's variable lines. The
  -- fixed-expense row is the farm's and arrives on its own (add_fixed).
  for v_year in
    select distinct crop_year from crop_inputs
     where (crop_id = any(v_members) or crop_id = p_crop) and not farm_fixed
       and (crop_year >= v_current or crop_year in (select crop_year from year_unlocks))
  loop
    select round(avg(t.total), 2) into v_cost
      from unnest(v_members) m(id)
      cross join lateral (
        select sum(coalesce(i.cost_per_acre, 0)) as total from crop_inputs i
         where i.crop_id = m.id and not i.farm_fixed
           and i.crop_year = (select max(j.crop_year) from crop_inputs j
                               where j.crop_id = m.id and not j.farm_fixed and j.crop_year <= v_year)
      ) t
     where t.total is not null;
    delete from crop_inputs
     where crop_id = p_crop and crop_year = v_year and not farm_fixed and name <> v_line;
    if v_cost is null then
      delete from crop_inputs where crop_id = p_crop and crop_year = v_year;
    elsif exists (select 1 from crop_inputs where crop_id = p_crop and crop_year = v_year and not farm_fixed and name = v_line) then
      update crop_inputs set cost_per_acre = v_cost
       where crop_id = p_crop and crop_year = v_year and not farm_fixed and name = v_line
         and cost_per_acre is distinct from v_cost;
    else
      insert into crop_inputs (crop_id, crop_year, name, category, cost_per_acre)
      values (p_crop, v_year, v_line, 'other'::input_category, v_cost);
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."fn_crop_average_sync"("p_crop" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_crop_history_clean"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  t_changed boolean := tg_op = 'INSERT' or new.clean_total is distinct from old.clean_total;
  y_changed boolean := tg_op = 'INSERT' or new.clean_yield_per_acre is distinct from old.clean_yield_per_acre;
  a_changed boolean := tg_op = 'UPDATE' and new.acres is distinct from old.acres;
begin
  if coalesce(new.acres, 0) <= 0 then return new; end if;
  if t_changed and not y_changed then
    new.clean_yield_per_acre := case when new.clean_total is null then null else round(new.clean_total / new.acres, 1) end;
  elsif y_changed and not t_changed then
    new.clean_total := case when new.clean_yield_per_acre is null then null else round(new.clean_yield_per_acre * new.acres) end;
  elsif a_changed and new.clean_total is not null then
    new.clean_yield_per_acre := round(new.clean_total / new.acres, 1);
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."fn_crop_history_clean"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_crop_history_yield_after"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_new numeric := coalesce(new.clean_yield_per_acre, new.yield_per_acre);
  v_basis text := case when new.clean_yield_per_acre is not null then 'clean' else 'pre_clean' end;
  v_old numeric;
  v_old_basis text;
begin
  if crop_year_locked(new.crop_year) then return null; end if;
  if new.source not in ('scale', 'manual') then return null; end if;
  if tg_op = 'UPDATE' then
    v_old := coalesce(old.clean_yield_per_acre, old.yield_per_acre);
    v_old_basis := case when old.clean_yield_per_acre is not null then 'clean' else 'pre_clean' end;
    if v_new is not distinct from v_old and v_basis = v_old_basis then return null; end if;
  end if;

  perform set_config('rvr.plan_sync', 'on', true);
  if v_new is not null and new.plan_yield_saved then
    update crop_plans set yield_per_acre_override = v_new, yield_basis = v_basis
     where field_id = new.field_id and crop_id = new.crop_id and crop_year = new.crop_year;
  elsif v_new is null and tg_op = 'UPDATE' and old.plan_yield_saved then
    update crop_plans set yield_per_acre_override = old.plan_yield_before, yield_basis = null
     where field_id = new.field_id and crop_id = new.crop_id and crop_year = new.crop_year;
    update crop_history set plan_yield_saved = false, plan_yield_before = null where id = new.id;
  end if;
  perform set_config('rvr.plan_sync', 'off', true);
  return null;
end $$;


ALTER FUNCTION "public"."fn_crop_history_yield_after"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_crop_history_yield_before"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_scale boolean := coalesce(current_setting('rvr.scale_yield', true), '') = 'on';
  t_changed boolean;
  y_changed boolean;
  a_changed boolean;
  v_eff numeric := coalesce(new.clean_yield_per_acre, new.yield_per_acre);
begin
  if tg_op = 'UPDATE' and not v_scale then
    t_changed := new.actual_yield_total is distinct from old.actual_yield_total;
    y_changed := new.yield_per_acre is distinct from old.yield_per_acre;
    a_changed := new.acres is distinct from old.acres;
    if t_changed and not y_changed and coalesce(new.acres, 0) > 0 then
      new.yield_per_acre := case when new.actual_yield_total is null then null else round(new.actual_yield_total / new.acres, 1) end;
    elsif y_changed and not t_changed and coalesce(new.acres, 0) > 0 then
      new.actual_yield_total := case when new.yield_per_acre is null then null else round(new.yield_per_acre * new.acres) end;
    elsif a_changed and not t_changed and not y_changed and coalesce(new.acres, 0) > 0 and new.actual_yield_total is not null then
      new.yield_per_acre := round(new.actual_yield_total / new.acres, 1);
    end if;
    if old.scale_at is not null and (t_changed or y_changed) then
      new.yield_override := true;
      new.source := 'manual';
    end if;
    v_eff := coalesce(new.clean_yield_per_acre, new.yield_per_acre);
  end if;

  -- The first time a season's yield (clean or field-run) lands, remember the
  -- estimate it replaces.
  if v_eff is not null
     and (tg_op = 'INSERT' or v_eff is distinct from coalesce(old.clean_yield_per_acre, old.yield_per_acre))
     and not new.plan_yield_saved
     and not crop_year_locked(new.crop_year) then
    select yield_per_acre_override into new.plan_yield_before
      from crop_plans where field_id = new.field_id and crop_id = new.crop_id and crop_year = new.crop_year limit 1;
    new.plan_yield_saved := true;
  end if;
  return new;
end $$;


