CREATE OR REPLACE FUNCTION "public"."fn_crop_inputs_add_fixed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_prev text;
  v_per numeric;
  v_rented_out boolean;
begin
  if new.farm_fixed then
    return null;
  end if;
  select c.land_rent_only into v_rented_out from crops c where c.id = new.crop_id and c.fixed_costs_apply;
  if not found then
    return null;
  end if;
  v_per := case when v_rented_out then farm_fixed_land_share(new.crop_year) else farm_fixed_per_acre(new.crop_year) end;
  if v_per is null
     or exists (select 1 from crop_inputs f where f.crop_id = new.crop_id and f.crop_year = new.crop_year and f.farm_fixed) then
    return null;
  end if;
  v_prev := current_setting('rvr.farm_fixed_sync', true);
  perform set_config('rvr.farm_fixed_sync', 'on', true);
  insert into crop_inputs (crop_id, crop_year, name, category, cost_per_acre, farm_fixed, fixed_land_share)
  values (new.crop_id, new.crop_year, case when v_rented_out then 'Fixed expenses: land share' else 'Fixed expenses' end, 'other', v_per, true, v_rented_out);
  perform set_config('rvr.farm_fixed_sync', coalesce(v_prev, ''), true);
  return null;
end;
$$;


ALTER FUNCTION "public"."fn_crop_inputs_add_fixed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_crop_inputs_fixed_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_per numeric;
begin
  if tg_op = 'INSERT' and not new.farm_fixed
     and lower(btrim(new.name)) in ('fixed expenses', 'fixed expenses (fah)') then
    if exists (select 1 from crop_inputs f where f.crop_id = new.crop_id and f.crop_year = new.crop_year and f.farm_fixed) then
      return null;
    end if;
    v_per := farm_fixed_per_acre(new.crop_year);
    new.farm_fixed := true;
    new.name := 'Fixed expenses';
    new.cost_per_acre := coalesce(v_per, new.cost_per_acre);
    return new;
  end if;
  if coalesce(current_setting('rvr.farm_fixed_sync', true), '') = 'on' or auth.uid() is null then
    return new;
  end if;
  if (tg_op = 'INSERT' and new.farm_fixed)
     or (tg_op = 'UPDATE' and (old.farm_fixed or new.farm_fixed)
         and (new.cost_per_acre is distinct from old.cost_per_acre or new.farm_fixed is distinct from old.farm_fixed)) then
    raise exception 'Fixed expenses are set for the whole farm under Financials → Farm costs, not per crop';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."fn_crop_inputs_fixed_guard"() OWNER TO "postgres";


