CREATE OR REPLACE FUNCTION "public"."fn_events_series_key"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
begin
  -- Only when not given one: a person who has deliberately tied two
  -- differently-named events together should not have it undone on save.
  if new.series_key is null or new.series_key = '' then
    new.series_key := trim(both '-' from regexp_replace(
      lower(regexp_replace(new.name, '\s*(19|20)\d{2}\s*$', '', 'g')),
      '[^a-z0-9]+', '-', 'g'));
  end if;
  new.updated_at := now();
  return new;
end $_$;


