CREATE OR REPLACE FUNCTION "public"."fn_farm_fixed_compute"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_rented numeric;
begin
  if new.mode = 'lump' then
    new.per_acre := coalesce(new.lump_per_acre, 0);
  else
    if new.spread_acres is null then
      new.spread_acres := nullif(round(farm_plan_acres(new.crop_year), 2), 0);
    end if;
    v_rented := coalesce(farm_rented_out_acres(new.crop_year), 0);
    select coalesce(sum(case
             when l.basis = 'per_acre' then l.amount
             when new.spread_acres > 0 and l.category = 'land' then l.amount / (new.spread_acres + v_rented)
             when new.spread_acres > 0 then l.amount / new.spread_acres
             else 0
           end), 0)
      into new.per_acre
      from farm_fixed_cost_lines l
     where l.crop_year = new.crop_year;
  end if;
  new.per_acre := round(new.per_acre, 2);
  return new;
end;
$$;


ALTER FUNCTION "public"."fn_farm_fixed_compute"() OWNER TO "postgres";


