CREATE OR REPLACE FUNCTION "public"."fn_farm_fixed_line_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_year integer;
  v_id uuid;
  v_old jsonb;
  v_new jsonb;
begin
  if tg_op <> 'INSERT' then v_old := to_jsonb(old); v_year := old.crop_year; v_id := old.id; end if;
  if tg_op <> 'DELETE' then v_new := to_jsonb(new); v_year := new.crop_year; v_id := new.id; end if;
  insert into farm_fixed_cost_line_history (line_id, crop_year, action, old_values, new_values, actor_id)
  values (v_id, v_year, lower(tg_op), v_old, v_new, auth.uid());
  -- Touching the row fires its compute trigger, and the sync after it.
  update farm_fixed_costs set updated_at = now() where crop_year = v_year;
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."fn_farm_fixed_line_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_farm_fixed_sync"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_prev text := current_setting('rvr.farm_fixed_sync', true);
  v_year integer;
  v_per numeric;
  v_land numeric;
begin
  perform set_config('rvr.farm_fixed_sync', 'on', true);
  for v_year in
    select distinct crop_year from crop_inputs
     where crop_year >= date_part('year', now())::int
        or crop_year in (select crop_year from year_unlocks)
  loop
    v_per := farm_fixed_per_acre(v_year);
    continue when v_per is null;
    v_land := farm_fixed_land_share(v_year);

    -- Our own crops: the whole figure.
    update crop_inputs i set cost_per_acre = v_per, fixed_land_share = false, name = 'Fixed expenses'
      from crops c
     where c.id = i.crop_id and i.crop_year = v_year and i.farm_fixed and not c.land_rent_only
       and (i.cost_per_acre is distinct from v_per or i.fixed_land_share);
    insert into crop_inputs (crop_id, crop_year, name, category, cost_per_acre, farm_fixed)
    select distinct i.crop_id, v_year, 'Fixed expenses', 'other'::input_category, v_per, true
      from crop_inputs i
      join crops c on c.id = i.crop_id and c.fixed_costs_apply and not c.land_rent_only
     where i.crop_year = v_year
       and not i.farm_fixed
       and not exists (select 1 from crop_inputs f where f.crop_id = i.crop_id and f.crop_year = v_year and f.farm_fixed);

    -- Land rented out: the land share only, on every such crop, budget or not.
    if v_land is null then
      delete from crop_inputs i using crops c
       where c.id = i.crop_id and i.crop_year = v_year and i.farm_fixed and c.land_rent_only;
    else
      update crop_inputs i set cost_per_acre = v_land, fixed_land_share = true, name = 'Fixed expenses: land share'
        from crops c
       where c.id = i.crop_id and i.crop_year = v_year and i.farm_fixed and c.land_rent_only
         and (i.cost_per_acre is distinct from v_land or not i.fixed_land_share);
      insert into crop_inputs (crop_id, crop_year, name, category, cost_per_acre, farm_fixed, fixed_land_share)
      select c.id, v_year, 'Fixed expenses: land share', 'other'::input_category, v_land, true, true
        from crops c
       where c.land_rent_only and c.fixed_costs_apply
         and not exists (select 1 from crop_inputs f where f.crop_id = c.id and f.crop_year = v_year and f.farm_fixed);
    end if;
  end loop;
  perform set_config('rvr.farm_fixed_sync', coalesce(v_prev, ''), true);
end;
$$;


ALTER FUNCTION "public"."fn_farm_fixed_sync"() OWNER TO "postgres";


