CREATE OR REPLACE FUNCTION "public"."fn_flag_duplicate_operations"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare n integer;
begin
  with hand as (
    select o.id, o.field_id, o.started_at, lower(trim(o.products->0->>'name')) prod
    from jd_field_operations o
    where o.operation_type = 'application'
      and o.machine_id is null
      and o.duplicate_of is null
      and not o.not_duplicate
      and o.products->0->>'name' is not null
  ), pick as (
    select distinct on (h.id) h.id, m.id partner
    from hand h
    join jd_field_operations m
      on m.field_id = h.field_id
     and m.id <> h.id
     and m.operation_type = 'application'
     and m.machine_id is not null
     and m.duplicate_of is null
     and lower(trim(m.products->0->>'name')) = h.prod
     and h.started_at between m.started_at - interval '3 days' and coalesce(m.ended_at, m.started_at) + interval '3 days'
    order by h.id, abs(extract(epoch from h.started_at - m.started_at))
  )
  update jd_field_operations o
     set duplicate_of = p.partner,
         duplicate_reason = 'Hand-entered copy of a job the sprayer logged',
         duplicate_by = 'auto'
    from pick p
   where o.id = p.id;
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION "public"."fn_flag_duplicate_operations"() OWNER TO "postgres";


