CREATE OR REPLACE FUNCTION "public"."fn_pl_op_grid_sums"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  select sum((c ->> 2)::numeric * (c ->> 3)::numeric), sum((c ->> 3)::numeric), count(*)
    into new.rate_cell_sum, new.cover_cell_sum, new.cell_elements
    from jsonb_array_elements(coalesce(new.cells, '[]'::jsonb)) c;
  return new;
end;
$$;


ALTER FUNCTION "public"."fn_pl_op_grid_sums"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_products_autolink"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  -- Only fills a blank, and only for chemicals. A registration somebody chose
  -- by hand is never overwritten — that choice is the whole point of the picker.
  if coalesce(new.category, 'chemical') = 'chemical' and new.pmra_registration is null then
    new.pmra_registration := fn_registration_for(new.name);
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."fn_products_autolink"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_purchase_autocreate_fertilizer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_name text;
  v_unit text;
  v_id   uuid;
  v_fert boolean;
begin
  if new.product_id is not null or not coalesce(new.is_product, false) then
    return new;
  end if;
  v_name := regexp_replace(trim(new.description), '[.\s]+$', '');
  if v_name = '' then return new; end if;

  v_fert :=
    lower(coalesce(new.pack_unit, '')) in ('metric', 'tonne', 'tonnes', 'mt')
    or v_name ~* '^tonne\y'
    or v_name ~* '\y(uan|m\.?a\.?p\.?|blend|urea|potash|esn|sulf ?4 ?r)\y'
    or v_name ~ '^\d+(\.\d+)?-\d+(\.\d+)?-\d+';
  if not v_fert then return new; end if;

  v_unit := case
    when new.canonical_unit in ('kg', 'L') then new.canonical_unit
    when lower(coalesce(new.pack_unit, '')) in ('metric', 'tonne', 'tonnes', 'mt', 'kg', 'kgs') then 'kg'
    when lower(coalesce(new.pack_unit, '')) in ('litres', 'liters', 'litre', 'liter', 'l') then 'L'
    else null
  end;
  if v_unit is null then return new; end if;

  select id into v_id from jd_products where lower(name) = lower(v_name) limit 1;
  if v_id is null then
    insert into jd_products (name, unit, category)
    values (v_name, v_unit, 'fertilizer')
    returning id into v_id;
  end if;
  new.product_id := v_id;
  return new;
end $_$;


ALTER FUNCTION "public"."fn_purchase_autocreate_fertilizer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_purchase_reprice_product"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.product_id is null or new.price_per_canonical is null or new.invoice_date is null then
    return new;
  end if;
  update jd_products p
     set price_per_unit = new.price_per_canonical,
         price_updated_on = new.invoice_date,
         price_source = 'ICI ' || coalesce(new.invoice_no, ''),
         updated_at = now()
   where p.id = new.product_id
     and (p.price_updated_on is null or p.price_updated_on <= new.invoice_date);
  return new;
end $$;


