CREATE OR REPLACE FUNCTION "public"."fn_push_dispatch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_secret text;
  v_site   text;
begin
  select value into v_secret from app_secrets where key in ('push_hook_secret', 'PUSH_HOOK_SECRET')
   order by key = 'push_hook_secret' desc limit 1;
  select rtrim(value, '/') into v_site from app_secrets where key = 'SITE_URL';
  perform net.http_post(
    coalesce(v_site, 'https://your-farm.netlify.app') || '/api/push-send',
    jsonb_build_object('notification_id', new.id),
    '{}'::jsonb,
    jsonb_build_object('Content-Type', 'application/json', 'x-push-secret', coalesce(v_secret, ''))
  );
  return new;
end;
$$;


