CREATE OR REPLACE FUNCTION "public"."fn_raise_bin_air"("p_field" "uuid", "p_crop_year" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  t record;
  open_alert record;
  last_dismissed timestamptz;
  fname text;
begin
  if p_field is null or p_crop_year is null then return; end if;

  select max(dismissed_at) into last_dismissed
    from bin_air_alerts
   where field_id = p_field and crop_year = p_crop_year;

  -- The wettest sample taken since anyone last said this was handled. Wettest
  -- rather than latest because several samples off one field is the normal case
  -- — a wet corner and three dry ones — and the bin has to be managed for the
  -- worst of what went into it.
  select * into t
    from moisture_tests
   where field_id = p_field and crop_year = p_crop_year
     and grade is not null and grade <> 'dry'
     and (last_dismissed is null or tested_at > last_dismissed)
   order by moisture_pct desc, tested_at desc
   limit 1;
  if not found then return; end if;

  select * into open_alert
    from bin_air_alerts
   where field_id = p_field and crop_year = p_crop_year and dismissed_at is null
   limit 1;

  if found then
    -- Already up. Raise the figure if this sample is wetter, and say nothing:
    -- re-notifying for a bin somebody is already looking at is how a warning
    -- stops being read.
    if t.moisture_pct > open_alert.moisture_pct then
      update bin_air_alerts
         set moisture_pct = t.moisture_pct,
             grade = t.grade,
             moisture_test_id = t.id,
             crop_id = coalesce(t.crop_id, crop_id),
             bin_id = coalesce(t.bin_id, bin_id)
       where id = open_alert.id;
    -- A later sample naming the bin is worth keeping even when it is drier:
    -- "which bin" is usually decided after the sample is run.
    elsif open_alert.bin_id is null and t.bin_id is not null then
      update bin_air_alerts set bin_id = t.bin_id where id = open_alert.id;
    end if;
    return;
  end if;

  insert into bin_air_alerts (
    field_id, crop_year, crop_id, bin_id, moisture_test_id, moisture_pct, grade
  ) values (
    p_field, p_crop_year, t.crop_id, t.bin_id, t.id, t.moisture_pct, t.grade
  )
  on conflict do nothing;

  select name into fname from fields where id = p_field;
  perform fn_notify_managers(
    'bin_needs_air',
    coalesce(fname, 'A field') || ' went in ' || t.grade,
    'It tested ' || round(t.moisture_pct, 1) || '% moisture. Put air on the bin.',
    '/harvest'
  );
end; $$;


ALTER FUNCTION "public"."fn_raise_bin_air"("p_field" "uuid", "p_crop_year" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_raise_bin_air"("p_field" "uuid", "p_crop_year" integer) IS 'Raise, or raise the figure on, the bin-needs-air alert for a field/year, from the wettest sample taken since it was last dismissed. Notifies once per alert, never on an update.';



