CREATE OR REPLACE FUNCTION "public"."fn_refresh_soil_from_samples"("p_years" integer DEFAULT 5) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_rows int;
begin
  with tops as (
    select r.field_id, r.id as report_id, r.lab, r.report_date, s.sample_code,
           s.cec_meq * case r.lab when 'WPG' then 1 / 1.24 when 'ICI' then 1.15 else 1 end as cec_norm,
           coalesce(s.om_pct, 2) as om
    from soil_test_samples s
    join soil_test_reports r on r.id = s.report_id
    where s.depth_top_in = 0 and s.cec_meq is not null and r.field_id is not null
      and coalesce(r.report_date, make_date(r.crop_year, 1, 1)) >= (current_date - make_interval(years => p_years))
  ), per_sample as (
    select t.*, greatest(3, (t.cec_norm - 2 * t.om) / 0.55) as clay, a.awc_mm_m, a.wp_mm_10cm
    from tops t cross join lateral fn_clay_awc(greatest(3, (t.cec_norm - 2 * t.om) / 0.55)) a
  ), per_report as (
    select field_id, report_id, lab, report_date, avg(clay) clay, avg(awc_mm_m) awc, avg(wp_mm_10cm) wp, count(*) n
    from per_sample group by field_id, report_id, lab, report_date
  ), per_field as (
    select field_id, avg(clay) clay, avg(awc) awc, avg(wp) wp, count(*) reports, sum(n) samples,
           min(report_date) first_on, max(report_date) last_on,
           string_agg(distinct case lab when 'WPG' then 'Decisive (WPG)' when 'A&L' then 'Decisive (A&L)' else lab end, ', ') labs,
           string_agg(to_char(report_date, 'Mon YYYY') || ' ' || round(awc) || ' mm/m', '; ' order by report_date) by_report
    from per_report group by field_id
  )
  update field_soil_profiles p set
    layers = (select jsonb_agg(jsonb_build_object(
                'depth_cm', d,
                'soil_type', (select label from fn_clay_awc(pf.clay)),
                'aw_fc_mm', round(pf.awc * d / 100.0, 1),
                'wp_mm', round(pf.wp * d / 10.0, 1)) order by d)
              from unnest(array[15, 30, 45, 60, 100]) d),
    source = 'samples',
    sample_site_name = 'Own soil samples, ' || to_char(pf.first_on, 'YYYY') ||
      case when to_char(pf.first_on, 'YYYY') <> to_char(pf.last_on, 'YYYY') then '-' || to_char(pf.last_on, 'YYYY') else '' end,
    sample_note = round(pf.awc) || ' mm/m — average of ' || pf.reports || ' report' || case when pf.reports = 1 then '' else 's' end
      || ' (' || pf.samples || ' topsoil samples; ' || pf.labs || '): ' || pf.by_report
      || '. Estimated from CEC and organic matter — soil tests do not measure texture.',
    updated_at = now()
  from per_field pf
  where pf.field_id = p.field_id and p.source <> 'manual';
  get diagnostics v_rows = row_count;

  -- No samples in the window: the survey (a hand-set profile is never touched).
  update field_soil_profiles p set
    layers = (select jsonb_agg(jsonb_build_object('depth_cm', d, 'soil_type', 'Soil survey',
                'aw_fc_mm', round(p.survey_awc_mm_m * d / 100.0, 1), 'wp_mm', round(1.0 * d, 1)) order by d)
              from unnest(array[15, 30, 45, 60, 100]) d),
    source = 'survey', sample_site_name = 'Soil survey (no samples in ' || p_years || ' years)',
    sample_note = null, updated_at = now()
  where p.source in ('default', 'decisive', 'ici', 'aimm')
    and p.survey_awc_mm_m is not null
    and not exists (
      select 1 from soil_test_reports r join soil_test_samples s on s.report_id = r.id
      where r.field_id = p.field_id and s.depth_top_in = 0 and s.cec_meq is not null
        and coalesce(r.report_date, make_date(r.crop_year, 1, 1)) >= (current_date - make_interval(years => p_years)));
  return v_rows;
end $$;


ALTER FUNCTION "public"."fn_refresh_soil_from_samples"("p_years" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_registration_for"("p_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_reg text;
begin
  select min(registration_number) into v_reg
  from chemicals
  where fn_norm_chem_name(name) = fn_norm_chem_name(p_name)
  having count(distinct registration_number) = 1;
  if v_reg is not null then return v_reg; end if;

  select min(registration_number) into v_reg
  from chemicals
  where fn_clean_chem_name(name) = fn_clean_chem_name(p_name)
    and fn_clean_chem_name(p_name) <> ''
  having count(distinct registration_number) = 1;
  return v_reg;
end $$;


