CREATE OR REPLACE FUNCTION "public"."fn_run_item_after"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run uuid := coalesce(new.run_id, old.run_id);
  v_open int;
  v_total int;
begin
  select count(*) filter (where not checked), count(*) into v_open, v_total
  from checklist_run_items where run_id = v_run;

  if v_total > 0 and v_open = 0 then
    update checklist_runs set status = 'done', completed_at = now()
      where id = v_run and status <> 'done';
    update tasks set status = 'done'
      where source = 'checklist' and source_ref = v_run and status <> 'done';
  else
    update checklist_runs set status = 'open', completed_at = null
      where id = v_run and status <> 'open';
    update tasks set status = 'open'
      where source = 'checklist' and source_ref = v_run and status = 'done';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."fn_run_item_after"() OWNER TO "postgres";


