CREATE OR REPLACE FUNCTION "public"."fn_scale_ticket_delivered"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare cid uuid;
begin
  for cid in
    select distinct c from (
      values (case when tg_op <> 'INSERT' then old.contract_id end),
             (case when tg_op <> 'DELETE' then new.contract_id end),
             -- A ticket linked to or unlinked from a load changes that load's contract too.
             ((select contract_id from bin_loads where id = case when tg_op <> 'INSERT' then old.bin_load_id end)),
             ((select contract_id from bin_loads where id = case when tg_op <> 'DELETE' then new.bin_load_id end))
    ) as t(c) where c is not null
  loop
    perform contract_delivered(cid);
  end loop;
  return coalesce(new, old);
end; $$;


ALTER FUNCTION "public"."fn_scale_ticket_delivered"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_scale_ticket_match_load"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.bin_load_id is null and new.contract_id is not null then
    select l.id into new.bin_load_id
      from bin_loads l
     where l.contract_id = new.contract_id
       and l.gross_kg is not null and l.tare_kg is not null
       and abs(l.loaded_on - new.delivered_on) <= 3
       and not exists (select 1 from scale_tickets t where t.bin_load_id = l.id)
       and (new.net_lb is null or abs(l.net_kg * 2.20462262 - new.net_lb) <= 0.10 * new.net_lb)
     order by abs(l.loaded_on - new.delivered_on),
              abs(l.net_kg * 2.20462262 - coalesce(new.net_lb, l.net_kg * 2.20462262))
     limit 1;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."fn_scale_ticket_match_load"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_soil_inputs_hash"("p_report_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
  select md5(
    coalesce(string_agg(
      s.sample_code || ':' || coalesce(s.om_pct::text,'') || ',' || coalesce(s.no3n_lb_ac::text,'') || ',' ||
      coalesce(s.p_bicarb_ppm::text,'') || ',' || coalesce(s.k_ppm::text,'') || ',' ||
      coalesce(s.so4s_ppm::text,'') || ',' || coalesce(s.ph::text,'') || ',' ||
      coalesce(s.cec_meq::text,'') || ',' || coalesce(s.base_na_pct::text,'') || ',' ||
      coalesce(s.zn_ppm::text,'') || ',' || coalesce(s.cu_ppm::text,'') || ',' || coalesce(s.b_ppm::text,''),
      '|' order by s.sample_code), '')
    || '#' || coalesce((select r.crop_label from public.soil_test_reports r where r.id = p_report_id), '')
    || '#' || coalesce((
         select string_agg(p.crop_year::text || '=' || coalesce(p.crop_id::text,''), ',' order by p.crop_year)
         from public.crop_plans p
         join public.soil_test_reports r on r.id = p_report_id
         where p.field_id = r.field_id and p.crop_year between r.crop_year - 2 and r.crop_year
       ), '')
    || '#' || coalesce((
         select string_agg(h.crop_year::text || '=' || coalesce(h.crop_id::text,''), ',' order by h.crop_year)
         from public.crop_history h
         join public.soil_test_reports r on r.id = p_report_id
         where h.field_id = r.field_id and h.crop_year between r.crop_year - 6 and r.crop_year - 1
       ), '')
    || '#' || coalesce((
         select string_agg(
           m.id::text || ':' || m.crop_year::text || '=' || coalesce(m.source,'') || ','
           || coalesce(m.rate_tons_per_acre::text,'') || ',' || coalesce(m.acres::text,'')
           || ',' || coalesce(m.incorporated::text,'')
           || ',' || coalesce(m.incorporated_days::text,'') || ',' || coalesce(m.manure_type,''),
           '|' order by m.id)
         from public.manure_applications m
         join public.soil_test_reports r on r.id = p_report_id
         where m.field_id = r.field_id and m.crop_year between r.crop_year - 3 and r.crop_year
       ), '')
    -- Irrigated or dryland decides which Alberta table applies.
    || '#irr=' || (select exists (
         select 1 from public.field_pivots fp join public.soil_test_reports r on r.id = p_report_id
          where fp.field_id = r.field_id))::text
    -- Zone and water source settings.
    || '#set=' || coalesce((
         select string_agg(f.key || '=' || f.value::text, ',' order by f.key)
           from public.fert_settings f
          where f.key in ('soil_zone', 'irrigation_water', 'irrigation_inches')), '')
    -- The instructions are an input like any other.
    || '#v' || public.fn_soil_prompt_version()::text
  )
  from public.soil_test_samples s where s.report_id = p_report_id;
$$;


ALTER FUNCTION "public"."fn_soil_inputs_hash"("p_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_soil_prompt_version"() RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  -- 1: first generated write-ups.
  -- 2: reads crop_history as well as crop_plans; action-only narrative; told
  --    not to claim the rotation is unavailable when it is right there.
  -- 3: told about manure spread on the field in the last three years, and what
  --    the crop gets from it.
  -- 4: Alberta baseline computed in code (N curves, P/K/S tables, seed-row
  --    cap, zinc, AOPA); irrigated or dryland per field; manure by Alberta's
  --    feedlot method; measured irrigation-water sulphur.
  select 4;
$$;


ALTER FUNCTION "public"."fn_soil_prompt_version"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_soil_prompt_version"() IS 'Bump when the assessment prompt changes. Folded into fn_soil_inputs_hash, so a bump marks every assessment stale and the sweep rewrites them.';



