CREATE OR REPLACE FUNCTION "public"."fn_sync_pastures_from_map"("p_features" "jsonb", "p_ranch_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  f jsonb;
  g geometry;
  v_name text;
  v_ranch record;
  v_pasture record;
  v_id uuid;
  v_added text[] := '{}';
  v_moved text[] := '{}';
  v_same int := 0;
  v_skipped text[] := '{}';
begin
  for f in select * from jsonb_array_elements(coalesce(p_features, '[]'::jsonb)) loop
    v_name := btrim(f->>'name');
    begin
      g := st_multi(st_collectionextract(st_makevalid(st_setsrid(st_geomfromgeojson(f->'geometry'), 4326)), 3));
    exception when others then
      v_skipped := v_skipped || v_name;
      continue;
    end;
    if v_name is null or v_name = '' or g is null or st_isempty(g) then
      v_skipped := v_skipped || coalesce(v_name, '(no name)');
      continue;
    end if;

    -- The ranch: the map's own, else the one whose yard is nearest.
    if p_ranch_id is not null then
      select r.* into v_ranch from ranches r where r.id = p_ranch_id;
    else
      select r.* into v_ranch from ranches r
      where r.latitude is not null and r.longitude is not null
      order by st_distance(st_setsrid(st_point(r.longitude, r.latitude), 4326)::geography, st_centroid(g)::geography)
      limit 1;
    end if;

    -- The same name on the same ranch is the same pasture (two ranches may
    -- both have a "Pasture A").
    select p.* into v_pasture from pastures p
    where lower(p.name) = lower(v_name) and coalesce(p.legal_description, '') = coalesce(v_ranch.name, '')
    limit 1;
    if found then
      if st_equals(st_snaptogrid(v_pasture.boundary, 0.000001), st_snaptogrid(g, 0.000001)) then
        v_same := v_same + 1;
      else
        update pastures set boundary = g, area_acres = round((st_area(g::geography) / 4046.8564224)::numeric, 1)
        where id = v_pasture.id;
        update grazing_pastures set km2 = round((st_area(g::geography) / 1e6)::numeric, 3) where pasture_id = v_pasture.id;
        v_moved := v_moved || v_name;
      end if;
      continue;
    end if;

    insert into pastures (name, legal_description, boundary, area_acres, pasture_type, satellite_enabled)
    values (v_name, v_ranch.name, g, round((st_area(g::geography) / 4046.8564224)::numeric, 1), 'native', true)
    returning id into v_id;

    insert into grazing_pastures (name, ranch_id, pasture_id, km2, sort_order)
    values (
      btrim(regexp_replace(v_name, '^(pasture|paddock)\s*-?\s*', '', 'i')),
      v_ranch.id,
      v_id,
      round((st_area(g::geography) / 1e6)::numeric, 3),
      coalesce((select max(sort_order) + 1 from grazing_pastures where ranch_id = v_ranch.id), 0)
    );
    v_added := v_added || (v_name || ' (' || v_ranch.name || ')');
  end loop;

  return jsonb_build_object('added', to_jsonb(v_added), 'moved', to_jsonb(v_moved), 'unchanged', v_same, 'skipped', to_jsonb(v_skipped));
end;
$$;


ALTER FUNCTION "public"."fn_sync_pastures_from_map"("p_features" "jsonb", "p_ranch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_task_assignee_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_name text;
  v_title text;
begin
  if new.user_id = auth.uid() then return new; end if;
  select full_name into v_actor_name from users where id = auth.uid();
  select title into v_title from tasks where id = new.task_id;
  perform fn_notify(new.user_id, 'task_assigned',
    'Task assigned to you: ' || coalesce(v_title, 'untitled'),
    coalesce('by ' || v_actor_name, null),
    '/tasks/' || new.task_id);
  return new;
end;
$$;


ALTER FUNCTION "public"."fn_task_assignee_notify"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_task_before"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.status = 'done' and old.status = 'open' then
      new.completed_at := now();
      new.completed_by := coalesce(auth.uid(), new.completed_by);
    elsif new.status = 'open' and old.status = 'done' then
      new.completed_at := null;
      new.completed_by := null;
    end if;
    if new.reminder_at is distinct from old.reminder_at then
      new.reminder_sent := false;
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."fn_task_before"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_task_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_name text;
begin
  if tg_op = 'UPDATE' and new.status = 'done' and old.status = 'open'
     and new.created_by is distinct from coalesce(new.completed_by, auth.uid()) then
    select full_name into v_actor_name from users where id = auth.uid();
    perform fn_notify(new.created_by, 'task_completed',
      'Task completed: ' || new.title,
      coalesce('by ' || v_actor_name, null),
      '/tasks/' || new.id);
  end if;
  return new;
end;
$$;


