    ('CL', 200, 16, 'Clay loam'), ('SICL', 220, 19, 'Silty clay loam'), ('SC', 172, 22, 'Sandy clay'),
    ('SIC', 212, 22, 'Silty clay'), ('C', 192, 22, 'Clay'), ('HC', 192, 22, 'Heavy clay')
