CREATE OR REPLACE FUNCTION "public"."fn_tv_commands_check_url"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_site text;
  v_rest text;
begin
  if new.url is null then
    return new;
  end if;
  select rtrim(value, '/') into v_site from app_secrets where key = 'SITE_URL';
  v_site := coalesce(nullif(v_site, ''), 'https://your-farm.netlify.app');
  if lower(left(new.url, length(v_site))) <> lower(v_site) then
    raise exception 'TV can only show pages from %', v_site using errcode = '22023';
  end if;
  v_rest := substr(new.url, length(v_site) + 1);
  if v_rest <> '' and left(v_rest, 1) not in ('/', '?', '#') then
    raise exception 'TV can only show pages from %', v_site using errcode = '22023';
  end if;
  if new.url ~ '[[:space:][:cntrl:]]' or length(new.url) > 2048 then
    raise exception 'TV page address is not valid' using errcode = '22023';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."fn_tv_commands_check_url"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_users_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.id = auth.uid()
     and (new.role is distinct from old.role
          or new.active is distinct from old.active
          or new.denied_views is distinct from old.denied_views) then
    raise exception 'You cannot change your own role, active status, or view access';
  end if;

  if new.denied_views is distinct from old.denied_views and not is_admin() then
    raise exception 'Only admins can change view access';
  end if;

  if is_admin() then
    return new;
  end if;

  if is_manager() then
    if new.id <> auth.uid()
       and (new.role is distinct from old.role or new.active is distinct from old.active) then
      if old.role <> 'user' then
        raise exception 'Only admins can change access for managers and admins';
      end if;
      if new.role <> 'user' then
        raise exception 'Only admins can grant manager or admin access';
      end if;
    end if;
    return new;
  end if;

  if new.role is distinct from old.role
     or new.active is distinct from old.active
     or new.email is distinct from old.email then
    raise exception 'Only managers can change role, active status, or email';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."fn_users_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_users_owner_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_was boolean := false;
  v_fin boolean := false;
begin
  if tg_op = 'UPDATE' then
    v_was := old.is_owner;
    v_fin := old.finance_access;
  end if;
  if new.is_owner is distinct from v_was and auth.uid() is not null and not is_owner() then
    raise exception 'Only an owner can change who is an owner';
  end if;
  if new.finance_access is distinct from v_fin and auth.uid() is not null and not is_owner() then
    raise exception 'Only an owner can give someone access to the financials';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."fn_users_owner_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_wedge_soil_ratio"("p_lon" double precision, "p_lat" double precision, "p_radius_m" double precision) RETURNS real[]
    LANGUAGE "sql" STABLE
    AS $$
  with wedges as (
    select w, st_makepolygon(st_makeline(array[st_setsrid(st_point(p_lon, p_lat), 4326)] || array(
             select st_project(st_setsrid(st_point(p_lon, p_lat), 4326)::geography, p_radius_m, radians(w * 10 + k))::geometry
             from generate_series(0, 10, 2) k) || array[st_setsrid(st_point(p_lon, p_lat), 4326)])) g
    from generate_series(0, 35) w
  ), per as (
    select w.w, sum(t.awc_mm_m * st_area(st_intersection(w.g, s.geom)::geography)) / nullif(sum(st_area(st_intersection(w.g, s.geom)::geography)), 0) awc
    from wedges w
    join public.soil_landscape_polygons s on st_intersects(w.g, s.geom)
    cross join lateral public.fn_texture_awc(s.texture_top) t
    group by w.w
  ), m as (select avg(awc) mean from per)
  select case when (select mean from m) is null then '{}'::real[] else
    array(select coalesce(p.awc / (select mean from m), 1)::real from generate_series(0, 35) g left join per p on p.w = g order by g) end;
$$;


ALTER FUNCTION "public"."fn_wedge_soil_ratio"("p_lon" double precision, "p_lat" double precision, "p_radius_m" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_year_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_current int := date_part('year', now())::int;
begin
  if tg_op <> 'DELETE'
     and new.crop_year < v_current
     and not exists (select 1 from year_unlocks where crop_year = new.crop_year) then
    raise exception 'Crop year % is locked (read-only). A manager can unlock it.', new.crop_year;
  end if;
  if tg_op <> 'INSERT'
     and old.crop_year < v_current
     and not exists (select 1 from year_unlocks where crop_year = old.crop_year) then
    raise exception 'Crop year % is locked (read-only). A manager can unlock it.', old.crop_year;
  end if;
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."fn_year_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_zone_applied_depths"("p_field_id" "uuid", "p_crop_year" integer, "p_sectors" "jsonb") RETURNS TABLE("zone_id" "uuid", "zone_name" "text", "depth_mm" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  select
    z.id,
    coalesce(c.name, 'zone'),
    public.fn_area_weighted_depth(p_sectors, st_setsrid(st_geomfromgeojson(z.geojson), 4326))
  from public.field_crop_zones z
  left join public.crops c on c.id = z.crop_id
  where z.field_id = p_field_id
    and z.crop_year = p_crop_year
    -- An acres-only zone has no shape to intersect. It cannot receive
    -- area-weighted water, and guessing a share from its acreage would invent
    -- a number the geometry does not support.
    and z.geojson is not null;
$$;


ALTER FUNCTION "public"."fn_zone_applied_depths"("p_field_id" "uuid", "p_crop_year" integer, "p_sectors" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_zone_applied_depths"("p_field_id" "uuid", "p_crop_year" integer, "p_sectors" "jsonb") IS 'Applied depth per drawn crop zone for a field/year. Empty result = no drawn zones; caller falls back to the whole-field figure.';



CREATE OR REPLACE FUNCTION "public"."fn_zone_day_depths"("p_field_id" "uuid", "p_crop_year" integer, "p_sectors" "jsonb", "p_lon" double precision, "p_lat" double precision, "p_radius_m" double precision) RETURNS TABLE("zone_id" "uuid", "depth_mm" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  with circle as (
    select st_buffer(st_setsrid(st_point(p_lon, p_lat), 4326)::geography, p_radius_m)::geometry as g
  ),
  zones as (
    select z.id, st_intersection(st_setsrid(st_geomfromgeojson(z.geojson), 4326), (select g from circle)) as g
    from public.field_crop_zones z
    where z.field_id = p_field_id and z.crop_year = p_crop_year and z.geojson is not null
  ),
  feats as (
    select (f->'properties'->>'depth')::numeric as depth, st_setsrid(st_geomfromgeojson(f->'geometry'), 4326) as g
    from jsonb_array_elements(coalesce(p_sectors->'features', '[]'::jsonb)) f
    where f->'properties'->>'depth' is not null and f->'geometry' is not null
  )
  select z.id,
    case when st_area(z.g::geography) <= 0 then 0 else round((
      coalesce((select sum(f.depth * st_area(st_intersection(f.g, z.g)::geography)) from feats f where st_intersects(f.g, z.g)), 0)
      / st_area(z.g::geography))::numeric, 2) end
  from zones z;
$$;


ALTER FUNCTION "public"."fn_zone_day_depths"("p_field_id" "uuid", "p_crop_year" integer, "p_sectors" "jsonb", "p_lon" double precision, "p_lat" double precision, "p_radius_m" double precision) OWNER TO "postgres";


