CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_first   boolean;
  v_role    user_role;
  v_invited boolean;
begin
  select not exists (select 1 from users) into v_first;

  v_role := case
    when v_first then 'admin'::user_role
    when new.raw_user_meta_data ->> 'role' = 'admin' then 'admin'::user_role
    when new.raw_user_meta_data ->> 'role' = 'manager' then 'manager'::user_role
    else 'user'::user_role
  end;

  v_invited := coalesce((new.raw_user_meta_data ->> 'invite') = 'true', false)
               or new.invited_at is not null;

  insert into public.users (id, email, full_name, role, active, is_owner)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'full_name', split_part(new.email, '@', 1)),
    v_role,
    v_first or v_invited,
    v_first
  )
  on conflict (id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_map_layer"("p_name" "text", "p_source" "text", "p_features" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_layer uuid;
  f jsonb;
  n integer := 0;
begin
  if not is_manager() then raise exception 'Only managers can import map layers'; end if;
  select id into v_layer from map_layers where source = p_source;
  if v_layer is not null and exists (select 1 from map_features where layer_id = v_layer) then
    raise exception 'That layer is already in the app — edit it there';
  end if;
  if v_layer is null then
    insert into map_layers (name, layer_type, style, visible_default, sort_order, source)
    values (p_name, 'custom', '{}', true, 0, p_source)
    returning id into v_layer;
  end if;
  for f in select * from jsonb_array_elements(p_features) loop
    if f -> 'geometry' ->> 'type' not in ('Point', 'LineString', 'Polygon') then continue; end if;
    insert into map_features (layer_id, label, properties, geom)
    values (
      v_layer,
      nullif(trim(f -> 'properties' ->> 'name'), ''),
      coalesce(f -> 'properties', '{}') - '_layer',
      st_force2d(st_setsrid(st_geomfromgeojson((f -> 'geometry')::text), 4326))
    );
    n := n + 1;
  end loop;
  return v_layer;
end;
$$;


ALTER FUNCTION "public"."import_map_layer"("p_name" "text", "p_source" "text", "p_features" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_pasture_water"("p_points" "jsonb") RETURNS TABLE("pastures_updated" integer, "points_matched" integer, "points_outside" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_updated integer := 0;
  v_matched integer := 0;
  v_outside integer := 0;
begin
  create temp table _pts on commit drop as
  select
    (pt->>'lat')::double precision as lat,
    (pt->>'lon')::double precision as lon,
    st_setsrid(st_point((pt->>'lon')::double precision, (pt->>'lat')::double precision), 4326) as geom
  from jsonb_array_elements(p_points) as pt;

  -- Matched against the DRAWN boundary, not the 15 m inward analysis polygon:
  -- a dugout commonly sits right on a fence line, and the buffer would push it
  -- outside its own paddock.
  create temp table _hits on commit drop as
  select p.id as pasture_id, t.geom
  from _pts t
  join pastures p on st_contains(p.boundary, t.geom);

  select count(*) into v_matched from _hits;
  select count(*) into v_outside from _pts t
    where not exists (select 1 from pastures p where st_contains(p.boundary, t.geom));

  -- Replaces rather than merges. The map is the source of truth, so a pin
  -- deleted there must disappear here too; merging would make removals
  -- impossible without hunting them down by hand.
  update pastures p
  set water_source_geom = agg.geom
  from (
    select pasture_id, st_multi(st_collect(geom)) as geom
    from _hits group by pasture_id
  ) agg
  where agg.pasture_id = p.id
    and p.water_source_geom is distinct from agg.geom;
  get diagnostics v_updated = row_count;

  -- Paddocks that had water and no longer do, for the same reason.
  update pastures p
  set water_source_geom = null
  where p.water_source_geom is not null
    and not exists (select 1 from _hits h where h.pasture_id = p.id);

  perform rebuild_pasture_zones();

  pastures_updated := v_updated;
  points_matched := v_matched;
  points_outside := v_outside;
  return next;
end;
$$;


ALTER FUNCTION "public"."import_pasture_water"("p_points" "jsonb") OWNER TO "postgres";


