CREATE OR REPLACE FUNCTION "public"."jd_confirm_operation"("p_id" "uuid", "p_applied" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare r jd_field_operations;
begin
  if not is_manager() then raise exception 'Managers only'; end if;
  select * into r from jd_field_operations where id = p_id;
  if not found then return; end if;
  if p_applied then
    update jd_field_operations set confirm_status = 'confirmed' where id = p_id;
  else
    insert into jd_dismissed_operations (jd_id, field_id, summary, reason, dismissed_by)
    values (r.jd_id, r.field_id,
            'application ' || to_char(r.started_at, 'YYYY-MM-DD') || coalesce(' · ' || (r.products->0->>'name'), ''),
            'Not applied — hand-entered plan with nothing logged (confirmed on the app)', auth.uid())
    on conflict (jd_id) do update set reason = excluded.reason;
    delete from jd_field_operations where id = p_id;
  end if;
end $$;


