    "operator_jd_id" "text",
    "machine_id" "text",
    "machine_vin" "text",
    "products" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "raw" "jsonb",
    "synced_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "conditions" "jsonb",
    "wind_speed_kmh" numeric(6,2),
    "air_temp_c" numeric(5,2),
    "humidity_pct" numeric(5,2),
    "app_speed_kmh" numeric(6,2),
    "conditions_at" timestamp with time zone,
    "wind_gust_kmh" numeric(6,2),
    "wind_dir_deg" integer,
    "conditions_source" "text",
    "weather_at" timestamp with time zone,
    "applied_area_ha" numeric(10,2),
    "as_applied" "jsonb",
    "sessions" "jsonb",
    "work_minutes" numeric,
    "sessions_at" timestamp with time zone,
    "sessions_note" "text",
    "duplicate_of" "uuid",
    "duplicate_reason" "text",
    "duplicate_by" "text",
    "not_duplicate" boolean DEFAULT false NOT NULL,
    "cost_acres_override" numeric,
    "not_ours" "text",
    "not_ours_by" "text",
    "not_ours_note" "text",
    "confirm_status" "text",
    "products_corrected" "jsonb",
    "correction_note" "text",
    "source" "text" DEFAULT 'deere'::"text" NOT NULL,
    "source_ref" "text",
    "rotation_checked_at" timestamp with time zone,
    "fuel_l" numeric,
    "fuel_read_at" timestamp with time zone,
    CONSTRAINT "jd_field_operations_conditions_source_check" CHECK (("conditions_source" = ANY (ARRAY['deere'::"text", 'ecmwf'::"text", 'none'::"text"]))),
    CONSTRAINT "jd_field_operations_confirm_status_check" CHECK (("confirm_status" = ANY (ARRAY['pending'::"text", 'confirmed'::"text"]))),
    CONSTRAINT "jd_field_operations_cost_acres_override_check" CHECK ((("cost_acres_override" IS NULL) OR ("cost_acres_override" >= (0)::numeric))),
    CONSTRAINT "jd_field_operations_duplicate_by_check" CHECK (("duplicate_by" = ANY (ARRAY['auto'::"text", 'user'::"text"]))),
    CONSTRAINT "jd_field_operations_not_ours_by_check" CHECK (("not_ours_by" = ANY (ARRAY['auto'::"text", 'user'::"text"]))),
    CONSTRAINT "jd_field_operations_not_ours_check" CHECK (("not_ours" = ANY (ARRAY['custom_work'::"text", 'rented_out'::"text"]))),
    CONSTRAINT "jd_field_operations_source_check" CHECK (("source" = ANY (ARRAY['deere'::"text", 'app'::"text"])))
);


ALTER TABLE "public"."jd_field_operations" OWNER TO "postgres";


COMMENT ON COLUMN "public"."jd_field_operations"."sessions" IS 'From the per-point export: [{start, end, minutes, points}] per sitting, split at 30-minute gaps. [] when Deere has no logged points.';



COMMENT ON COLUMN "public"."jd_field_operations"."work_minutes" IS 'Minutes the machine was moving, summed over the sessions. Null until the export has been read.';



COMMENT ON COLUMN "public"."jd_field_operations"."sessions_at" IS 'When the export was last read; re-read when Deere modifies the operation after this.';



COMMENT ON COLUMN "public"."jd_field_operations"."duplicate_of" IS 'Set when this pass is another record of a job already counted (a hand-entered copy of a sprayer-logged pass). Hidden from app reads by RLS; list them with jd_duplicate_operations().';



COMMENT ON COLUMN "public"."jd_field_operations"."source" IS '''deere'' = synced from Operations Center; ''app'' = added in the app (jd_id starts app:), e.g. ICI''s floated Edge.';



COMMENT ON COLUMN "public"."jd_field_operations"."rotation_checked_at" IS 'When the spray was checked against the planned rotation (herbicide carryover); null = not yet.';



CREATE OR REPLACE FUNCTION "public"."jd_duplicate_operations"("p_field" "uuid") RETURNS SETOF "public"."jd_field_operations"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select * from jd_field_operations
   where field_id = p_field and duplicate_of is not null and is_active()
   order by started_at desc
$$;


