CREATE OR REPLACE FUNCTION "public"."jd_set_duplicate"("p_id" "uuid", "p_of" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not is_manager() then raise exception 'Managers only'; end if;
  if p_of is null then
    update jd_field_operations
       set duplicate_of = null, duplicate_reason = null, duplicate_by = null, not_duplicate = true
     where id = p_id;
  else
    update jd_field_operations
       set duplicate_of = p_of, duplicate_reason = 'Marked as the same job by hand', duplicate_by = 'user', not_duplicate = false
     where id = p_id;
  end if;
end $$;


ALTER FUNCTION "public"."jd_set_duplicate"("p_id" "uuid", "p_of" "uuid") OWNER TO "postgres";


