    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select o.id, o.field_id, f.name, o.started_at, o.products->0->>'name', o.jd_id
    from jd_field_operations o join fields f on f.id = o.field_id
   where o.confirm_status = 'pending' and (p_field is null or o.field_id = p_field) and is_active()
