CREATE OR REPLACE FUNCTION "public"."load_moisture"("p_load" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    l.moisture_pct,
    (select round(avg(t.moisture_pct), 1) from moisture_tests t
      where t.field_id = l.field_id and t.crop_id = l.crop_id and t.crop_year = l.crop_year
        and (t.tested_at at time zone 'America/Edmonton')::date = l.loaded_on
        and t.moisture_pct is not null)
  )
  from bin_loads l where l.id = p_load
$$;


ALTER FUNCTION "public"."load_moisture"("p_load" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."load_units"("p_load" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select case c.yield_unit
           when 'bu'  then l.bushels
           when 'lbs' then l.net_kg * 2.20462262
           when 'cwt' then l.net_kg * 2.20462262 / 100
           when 'ton' then l.net_kg * 2.20462262 / 2000
           when 'MT'  then l.net_kg / 1000
           else l.bushels
         end
    from bin_loads l join crops c on c.id = l.crop_id
   where l.id = p_load
$$;


ALTER FUNCTION "public"."load_units"("p_load" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."meeting_alerts"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_kinds" "text"[]) RETURNS TABLE("kind" "text", "title" "text", "body" "text", "link" "text", "last_at" timestamp with time zone, "times" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with w as (
    select n.kind, n.title, n.body, n.link, n.created_at,
           -- integration alerts name their feed before the colon, after any symbol
           case when n.kind = 'integration_alert'
                then trim(regexp_replace(split_part(n.title, ':', 1), '^[^[:alnum:]]+', '')) end as feed
      from notifications n
     where is_active()
       and n.kind = any(p_kinds)
       and n.created_at >= p_from and n.created_at < p_to
  ),
  recovered as (
    select feed, max(created_at) at from w where feed is not null and title like '✓%' group by feed
  ),
  live as (
    select w.* from w
     where w.title not like '✓%'
       and not exists (select 1 from recovered r where r.feed = w.feed and r.at > w.created_at)
  )
  -- times = separate sends, not copies: one alert reaches every manager at the same moment.
  select distinct on (l.kind, l.title)
         l.kind, l.title, l.body, l.link,
         max(l.created_at) over (partition by l.kind, l.title) as last_at,
         c.times
    from live l
    join (select kind, title, count(distinct date_trunc('minute', created_at))::int as times
            from live group by kind, title) c using (kind, title)
   order by l.kind, l.title, l.created_at desc;
$$;


ALTER FUNCTION "public"."meeting_alerts"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_kinds" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_jd_products"("p_keep" "uuid", "p_drop" "uuid", "p_force" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  k jd_products%rowtype;
  d jd_products%rowtype;
  l product_latest_price%rowtype;
  v_note text;
begin
  if not is_manager() then
    raise exception 'Only a manager can merge products';
  end if;
  if p_keep = p_drop then
    raise exception 'That is the same product';
  end if;
  select * into k from jd_products where id = p_keep;
  if not found then raise exception 'Product to keep not found'; end if;
  select * into d from jd_products where id = p_drop;
  if not found then raise exception 'Product to fold in not found'; end if;

  if k.unit <> d.unit then
    raise exception 'Units differ: % is per % and % is per %', k.name, k.unit, d.name, d.unit;
  end if;
  if coalesce(k.category, 'chemical') <> coalesce(d.category, 'chemical') then
    raise exception 'One is % and the other is %', coalesce(k.category, 'chemical'), coalesce(d.category, 'chemical');
  end if;

  v_note := 'Folded in "' || d.name || '" on ' || to_char(now(), 'YYYY-MM-DD');
  if k.pmra_registration is not null and d.pmra_registration is not null
     and k.pmra_registration <> d.pmra_registration then
    if not p_force then
      raise exception 'Different registrations (% and %): these are two registered products',
        k.pmra_registration, d.pmra_registration;
    end if;
    v_note := v_note || '; its registration ' || d.pmra_registration || ' dropped in favour of ' || k.pmra_registration;
  end if;

  update jd_product_aliases set product_id = p_keep where product_id = p_drop;
  insert into jd_product_aliases (deere_name, product_id, ignored)
  values (d.name, p_keep, false)
  on conflict (deere_name) do update set product_id = excluded.product_id, ignored = false;

  update product_purchases set product_id = p_keep where product_id = p_drop;

  update jd_products
     set pmra_registration = coalesce(k.pmra_registration, d.pmra_registration),
         notes = nullif(concat_ws(chr(10), k.notes, d.notes, v_note), ''),
         updated_at = now()
   where id = p_keep;

  -- The price: newest invoice line across both, else whichever had one.
  select * into l from product_latest_price where product_id = p_keep;
  if found then
    update jd_products
       set price_per_unit = l.price_per_canonical,
           price_updated_on = l.invoice_date,
           price_source = 'ICI ' || coalesce(l.invoice_no, '')
     where id = p_keep;
  elsif k.price_per_unit is null and d.price_per_unit is not null then
    update jd_products
       set price_per_unit = d.price_per_unit,
           price_updated_on = d.price_updated_on,
           price_source = d.price_source
     where id = p_keep;
  end if;

  delete from jd_products where id = p_drop;
end;
$$;


ALTER FUNCTION "public"."merge_jd_products"("p_keep" "uuid", "p_drop" "uuid", "p_force" boolean) OWNER TO "postgres";


