CREATE OR REPLACE FUNCTION "public"."n_trial_strips"("p_trial" "uuid") RETURNS TABLE("strip" integer, "rep" integer, "rate" numeric, "geojson" "jsonb", "acres" numeric, "heading" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  t n_trials%rowtype;
  g geometry;
  srid integer;
  c geometry;
  env geometry;
  az double precision;
  rot geometry;
  n integer;
  w double precision;
  x0 double precision;
  ymin double precision;
  ymax double precision;
  i integer;
  s geometry;
  p1 geometry; p2 geometry; p3 geometry;
begin
  select * into t from n_trials where id = p_trial;
  if t.id is null then return; end if;
  select coalesce(b.boundary_analysis, b.geom) into g
    from field_boundaries b
   where b.field_id = t.field_id and b.valid_to is null
   order by b.valid_from desc nulls last limit 1;
  if g is null then return; end if;
  srid := 32600 + floor((st_x(st_centroid(g)) + 180) / 6)::integer + 1;
  g := st_transform(g, srid);
  c := st_centroid(g);

  if t.heading_deg is not null then
    az := radians(t.heading_deg);
  else
    env := st_orientedenvelope(g);
    p1 := st_pointn(st_exteriorring(env), 1);
    p2 := st_pointn(st_exteriorring(env), 2);
    p3 := st_pointn(st_exteriorring(env), 3);
    az := case when st_distance(p1, p2) >= st_distance(p2, p3) then st_azimuth(p1, p2) else st_azimuth(p2, p3) end;
  end if;

  -- Travel direction to north: rotate counter-clockwise by the azimuth.
  rot := st_rotate(g, az, c);
  n := coalesce(array_length(t.layout, 1), 0);
  w := t.strip_width_m;
  x0 := st_x(c) - (n * w) / 2.0;
  ymin := st_ymin(rot) - 10;
  ymax := st_ymax(rot) + 10;

  for i in 1..n loop
    s := st_intersection(rot, st_makeenvelope(x0 + (i - 1) * w, ymin, x0 + i * w, ymax, srid));
    s := st_transform(st_rotate(s, -az, c), 4326);
    strip := i;
    rep := ((i - 1) / greatest(1, coalesce(array_length(t.rates, 1), 1))) + 1;
    rate := t.layout[i];
    geojson := st_asgeojson(st_multi(st_collectionextract(s, 3)))::jsonb;
    acres := round((st_area(s::geography) / 4046.8564224)::numeric, 2);
    heading := round(degrees(az)::numeric, 1);
    return next;
  end loop;
end $$;


ALTER FUNCTION "public"."n_trial_strips"("p_trial" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pasture_water_radius_m"() RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$ select 800::numeric $$;


ALTER FUNCTION "public"."pasture_water_radius_m"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pasture_water_reach"("p_id" "uuid") RETURNS "public"."geometry"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  p      pastures%rowtype;
  radius numeric := pasture_water_radius_m();
  reach  geometry;
  riv    geometry;
  refy   double precision;
begin
  select * into p from pastures where id = p_id;
  if p.boundary is null then return null; end if;

  -- Points within or on the fence of this pasture, and any the pasture is
  -- named on however far away they sit.
  select st_union(st_buffer(w.geom::geography, radius)::geometry) into reach
    from cattle_water w
   where w.drinkable
     and (st_dwithin(w.geom::geography, p.boundary::geography, 30) or p.id = any(w.serves));

  if p.river_access <> 'none' then
    select st_intersection(river_geom(), st_buffer(p.boundary::geography, radius + 50)::geometry) into riv;
    if riv is not null and not st_isempty(riv) then
      riv := st_buffer(riv::geography, radius)::geometry;
      if p.river_access = 'north_of' and p.river_access_ref is not null then
        select st_ymax(boundary) into refy from pastures where id = p.river_access_ref;
        if refy is not null then
          riv := st_intersection(riv, st_makeenvelope(st_xmin(p.boundary) - 1, refy, st_xmax(p.boundary) + 1, 89, 4326));
        end if;
      end if;
      reach := case when reach is null then riv else st_union(reach, riv) end;
    end if;
  end if;

  if reach is null then return null; end if;
  reach := st_intersection(p.boundary, reach);
  if reach is null or st_isempty(reach) then return null; end if;
  return st_multi(st_collectionextract(st_makevalid(reach), 3));
end;
$$;


ALTER FUNCTION "public"."pasture_water_reach"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pl_layer_totals"("p_year" integer) RETURNS TABLE("operation_id" "uuid", "field_id" "uuid", "operation_type" "text", "kind" "text", "product_name" "text", "rate_unit" "text", "rate_acres" numeric, "covered_acres" numeric, "cell_count" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select g.operation_id, g.field_id, g.operation_type, g.kind, g.product_name, g.rate_unit,
    g.rate_cell_sum * g.cell_m * g.cell_m / 4046.8564224,
    g.cover_cell_sum * g.cell_m * g.cell_m / 4046.8564224,
    g.cell_count
  from public.pl_op_grids g
  where g.crop_year = p_year
    and g.cell_elements > 0;
$$;


ALTER FUNCTION "public"."pl_layer_totals"("p_year" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pl_layer_totals"("p_year" integer) IS 'Profit/Loss Map: each gridded layer of a season summed (rate × acres, acres logged), so the farm view need not load every cell.';



