CREATE OR REPLACE FUNCTION "public"."qb_ask_names"("p_realm" "text", "p_kind" "text", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 40) RETURNS TABLE("name" "text", "lines" bigint, "raw_total" numeric, "first_date" "date", "last_date" "date")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with n as (
    select case p_kind
             when 'party' then coalesce(party_name, customer_name)
             when 'account' then account_name
             when 'item' then item_name
             when 'class' then class_name
           end as name,
           amount, txn_date
      from qb_lines
     where realm_id = p_realm
  )
  select name, count(*), round(sum(amount), 2), min(txn_date), max(txn_date)
    from n
   where name is not null
     and (p_search is null or name ilike '%' || p_search || '%')
   group by name
   order by count(*) desc, name
   limit greatest(1, least(coalesce(p_limit, 40), 200));
$$;


ALTER FUNCTION "public"."qb_ask_names"("p_realm" "text", "p_kind" "text", "p_search" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qb_ask_sum"("p_realm" "text", "p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_party" "text" DEFAULT NULL::"text", "p_account" "text" DEFAULT NULL::"text", "p_item" "text" DEFAULT NULL::"text", "p_class" "text" DEFAULT NULL::"text", "p_text" "text" DEFAULT NULL::"text", "p_entities" "text"[] DEFAULT NULL::"text"[], "p_group" "text" DEFAULT 'none'::"text", "p_side" "text" DEFAULT 'out'::"text", "p_limit" integer DEFAULT 100) RETURNS TABLE("label" "text", "amount" numeric, "lines" bigint, "transactions" bigint, "first_date" "date", "last_date" "date")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with l as (
    select l.*, e.doc_number, e.memo,
           case
             when p_side = 'raw' then l.amount
             when p_side = 'out' and l.entity in ('Bill', 'Purchase') then l.amount
             when p_side = 'out' and l.entity = 'VendorCredit' then -l.amount
             when p_side = 'in' and l.entity in ('Invoice', 'SalesReceipt') then l.amount
             when p_side = 'in' and l.entity = 'CreditMemo' then -l.amount
           end as signed
      from qb_lines l
      left join qb_entities e on e.id = l.entity_row_id
     where l.realm_id = p_realm
       and (p_from is null or l.txn_date >= p_from)
       and (p_to is null or l.txn_date <= p_to)
       and (p_party is null or l.party_name ilike '%' || p_party || '%' or l.customer_name ilike '%' || p_party || '%')
       and (p_account is null or l.account_name ilike '%' || p_account || '%')
       and (p_item is null or l.item_name ilike '%' || p_item || '%')
       and (p_class is null or l.class_name ilike '%' || p_class || '%')
       and (p_text is null or l.description ilike '%' || p_text || '%' or e.memo ilike '%' || p_text || '%')
       and (p_entities is null or l.entity = any (p_entities))
  )
  select coalesce(
           case p_group
             when 'none' then 'Total'
             when 'party' then coalesce(party_name, customer_name)
             when 'account' then coalesce(account_name, item_name)
             when 'item' then item_name
             when 'class' then class_name
             when 'customer' then customer_name
             when 'month' then to_char(txn_date, 'YYYY-MM')
             when 'year' then to_char(txn_date, 'YYYY')
             when 'entity' then entity
             when 'description' then description
             when 'transaction' then concat_ws(' | ', txn_date::text, entity || ' ' || qb_id, 'doc ' || doc_number, party_name)
           end, '(none)') as label,
         round(sum(signed), 2) as amount,
         count(*) as lines,
         count(distinct entity || ':' || qb_id) as transactions,
         min(txn_date) as first_date,
         max(txn_date) as last_date
    from l
   where signed is not null
   group by 1
   order by case when p_group in ('month', 'year') then null else abs(sum(signed)) end desc nulls last, 1
   limit greatest(1, least(coalesce(p_limit, 100), 500));
$$;


ALTER FUNCTION "public"."qb_ask_sum"("p_realm" "text", "p_from" "date", "p_to" "date", "p_party" "text", "p_account" "text", "p_item" "text", "p_class" "text", "p_text" "text", "p_entities" "text"[], "p_group" "text", "p_side" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qb_totals"("p_realm" "text", "p_from" "date", "p_to" "date", "p_by" "text", "p_side" "text" DEFAULT 'out'::"text") RETURNS TABLE("label" "text", "amount" numeric, "lines" bigint, "transactions" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with l as (
    select l.*,
           case
             when p_side = 'out' and l.entity in ('Bill', 'Purchase') then l.amount
             when p_side = 'out' and l.entity = 'VendorCredit' then -l.amount
             when p_side = 'in' and l.entity in ('Invoice', 'SalesReceipt') then l.amount
             when p_side = 'in' and l.entity = 'CreditMemo' then -l.amount
           end as signed
      from qb_lines l
     where l.realm_id = p_realm
       and (p_from is null or l.txn_date >= p_from)
       and (p_to is null or l.txn_date <= p_to)
  )
  select coalesce(
           case p_by
             when 'party' then party_name
             when 'account' then coalesce(account_name, item_name)
             when 'month' then to_char(txn_date, 'YYYY-MM')
             when 'class' then class_name
             when 'item' then item_name
           end, '(none)') as label,
         round(sum(signed), 2) as amount,
         count(*) as lines,
         count(distinct entity || ':' || qb_id) as transactions
    from l
   where signed is not null
   group by 1
   order by case when p_by = 'month' then null else abs(sum(signed)) end desc nulls last, 1;
$$;


ALTER FUNCTION "public"."qb_totals"("p_realm" "text", "p_from" "date", "p_to" "date", "p_by" "text", "p_side" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quickbooks_company"() RETURNS TABLE("realm_id" "text", "company_name" "text", "environment" "text", "status" "text", "last_sync_at" timestamp with time zone, "last_error" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select a.external_org_id, a.external_org_name, coalesce(a.meta ->> 'environment', 'sandbox'),
         a.status, a.last_sync_at, a.last_error
    from integration_accounts a
   where a.provider = 'quickbooks' and can_see_finances();
$$;


