CREATE OR REPLACE FUNCTION "public"."rebuild_pasture_zones"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  built integer := 0;
begin
  delete from pasture_zones where kind = 'water_distance';

  insert into pasture_zones (pasture_id, kind, label, band_order, boundary, boundary_analysis, acres)
  select
    z.pasture_id, 'water_distance', z.label, z.band_order,
    st_multi(z.geom),
    case
      when st_isempty(st_buffer(z.geom::geography, -15)::geometry) then null
      else st_multi(st_buffer(z.geom::geography, -15)::geometry)
    end,
    round((st_area(z.geom::geography) / 4046.8564224)::numeric, 1)
  from (
    select p.id as pasture_id, 'Within 800 m of water' as label, 1 as band_order,
           st_intersection(coalesce(p.boundary_analysis, p.boundary), r.reach) as geom
    from pastures p cross join lateral (select pasture_water_reach(p.id) as reach) r
    where r.reach is not null
    union all
    select p.id, 'Beyond 800 m of water', 2,
           st_difference(coalesce(p.boundary_analysis, p.boundary), r.reach)
    from pastures p cross join lateral (select pasture_water_reach(p.id) as reach) r
    where r.reach is not null
  ) z
  where not st_isempty(z.geom)
    and st_area(z.geom::geography) / 4046.8564224 >= 5;

  get diagnostics built = row_count;
  return built;
end;
$$;


ALTER FUNCTION "public"."rebuild_pasture_zones"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_integration_heartbeat"("p_key" "text", "p_detail" "text", "p_data_at" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_provider text;
begin
  insert into integration_health (source_key, label, category, check_kind, stale_after_min)
  values (p_key, initcap(replace(p_key, '_', ' ')), 'job', 'heartbeat', 2 * 1440)
  on conflict (source_key) do nothing;

  update integration_health
     set last_success_at = now(),
         last_checked_at = now(),
         data_at = coalesce(p_data_at, now()),
         status = 'ok',
         detail = p_detail,
         consecutive_fail = 0,
         alerted = false,
         enabled = true,
         updated_at = now()
   where source_key = p_key;

  -- Which connected account, if any, this job proves is alive.
  v_provider := case
    when p_key in ('jd_field_ops', 'jd_equipment', 'jd_planting_dates', 'jd_boundaries')
      then 'john_deere'
    when p_key = 'fieldnet' then 'fieldnet'
    else null
  end;

  if v_provider is not null then
    update integration_accounts
       set last_sync_at = now(),
           last_error = null,
           updated_at = now()
     where provider = v_provider::integration_provider
       and status::text = 'connected';

    update integration_health
       set last_success_at = now(),
           last_checked_at = now(),
           status = 'ok',
           detail = 'Reported by ' || p_key,
           consecutive_fail = 0,
           alerted = false,
           enabled = true,
           updated_at = now()
     where source_key = v_provider;
  end if;
end; $$;


ALTER FUNCTION "public"."record_integration_heartbeat"("p_key" "text", "p_detail" "text", "p_data_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_irrigation_assignments"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  s record;
begin
  update fields f set centroid = st_centroid(b.geom)::geography
  from field_boundaries b
  where b.field_id = f.id and b.valid_to is null;

  for r in select id, centroid from fields where assignment_mode = 'auto' and centroid is not null loop
    select st.id as sid, st_distance(r.centroid, st.geom) as dist into s
    from weather_stations st
    where st.active and st.decommissioned_on is null
      and (st.data_available_till is null or st.data_available_till >= current_date - 7)
    order by st_distance(r.centroid, st.geom) asc
    limit 1;
    if found then
      update fields set assigned_station_id = s.sid, assigned_station_distance_m = s.dist
      where id = r.id;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."refresh_irrigation_assignments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_boundary"("p_field_id" "uuid", "p_geojson" "jsonb", "p_source" "public"."boundary_source") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_new_id uuid;
begin
  update field_boundaries
  set valid_to = current_date
  where field_id = p_field_id and valid_to is null and valid_from < current_date;

  -- A boundary created today never really applied, so it is replaced rather
  -- than closed — this also satisfies the valid_to > valid_from check.
  delete from field_boundaries
  where field_id = p_field_id and valid_to is null and valid_from = current_date;

  insert into field_boundaries (field_id, geom, source)
  values (
    p_field_id,
    st_multi(st_collectionextract(
      st_makevalid(st_setsrid(st_geomfromgeojson(p_geojson::text), 4326)), 3)),
    p_source
  )
  returning id into v_new_id;

  return v_new_id;
end;
$$;


ALTER FUNCTION "public"."replace_boundary"("p_field_id" "uuid", "p_geojson" "jsonb", "p_source" "public"."boundary_source") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_boundary_if_changed"("p_field_id" "uuid", "p_geojson" "jsonb", "p_source" "public"."boundary_source", "p_tolerance" numeric DEFAULT 0.001) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_new geometry;
  v_cur geometry;
  v_locked boolean;
  v_diff numeric;
  v_area numeric;
begin
  select boundary_locked into v_locked from fields where id = p_field_id;
  if coalesce(v_locked, false) then
    return 'locked';
  end if;

  v_new := st_multi(st_collectionextract(
    st_makevalid(st_setsrid(st_geomfromgeojson(p_geojson::text), 4326)), 3));
  if v_new is null or st_isempty(v_new) then
    return 'empty';
  end if;

  select geom into v_cur
  from field_boundaries
  where field_id = p_field_id and valid_to is null;

  if v_cur is null then
    perform replace_boundary(p_field_id, p_geojson, p_source);
    return 'created';
  end if;

  -- Areas in square metres, so the ratio is dimensionless and the tolerance
  -- means the same thing on a 20 acre field and a 640 acre one.
  v_area := st_area(v_cur::geography) + st_area(v_new::geography);
  if v_area = 0 then
    return 'empty';
  end if;
  v_diff := st_area(st_symdifference(v_cur, v_new)::geography) * 2 / v_area;

  if v_diff <= p_tolerance then
    return 'unchanged';
  end if;

  perform replace_boundary(p_field_id, p_geojson, p_source);
  return 'replaced';
end;
$$;


ALTER FUNCTION "public"."replace_boundary_if_changed"("p_field_id" "uuid", "p_geojson" "jsonb", "p_source" "public"."boundary_source", "p_tolerance" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."replace_boundary_if_changed"("p_field_id" "uuid", "p_geojson" "jsonb", "p_source" "public"."boundary_source", "p_tolerance" numeric) IS 'Replaces a field boundary only when the new shape differs by more than the tolerance (default 0.1% of area). Returns created/replaced/unchanged/locked/empty.';



CREATE OR REPLACE FUNCTION "public"."report_app_issue"("p_kind" "text", "p_fingerprint" "text", "p_title" "text", "p_message" "text", "p_details" "jsonb", "p_path" "text", "p_build" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_active() then
    raise exception 'Sign in first';
  end if;
  if p_kind not in ('app_crash', 'app_error') then
    raise exception 'Unknown kind';
  end if;
  return public.app_issue_record(p_kind, p_fingerprint, p_title, p_message, p_details, p_path, p_build, auth.uid());
end;
$$;


ALTER FUNCTION "public"."report_app_issue"("p_kind" "text", "p_fingerprint" "text", "p_title" "text", "p_message" "text", "p_details" "jsonb", "p_path" "text", "p_build" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retire_meeting_fact"("p_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not is_active() then raise exception 'not permitted'; end if;

  update meeting_facts
     set retired_at = now(), retired_by = auth.uid()
   where id = p_id and retired_at is null;

  if not found then return; end if;

  -- Free whatever week is holding it. The log row is what pins a fact to a
  -- week, so deleting it lets that week choose again -- and the fact itself is
  -- now out of the candidate list, so it cannot be the one chosen.
  delete from meeting_fact_log where fact_id = p_id;
end; $$;


ALTER FUNCTION "public"."retire_meeting_fact"("p_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."retire_meeting_fact"("p_id" "text") IS 'Permanently drop a written meeting fact and free the week that was holding it.';



