CREATE OR REPLACE FUNCTION "public"."sat_apply_harmonization"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  touched integer;
begin
  with updated as (
    update sat_observations o
    set ndvi_harmonized = round(h.slope * o.ndvi_mean + h.intercept, 6),
        harmonization_source = h.source,
        harmonized = true
    from sat_scenes s
    join sat_harmonization h on h.collection = s.collection
    where s.id = o.scene_id
      and o.ndvi_mean is not null
      and (o.ndvi_harmonized is distinct from round(h.slope * o.ndvi_mean + h.intercept, 6)
        or o.harmonization_source is distinct from h.source
        or o.harmonized is distinct from true)
    returning 1
  )
  select count(*) into touched from updated;
  return touched;
end;
$$;


ALTER FUNCTION "public"."sat_apply_harmonization"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sat_field_geometries"("p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("field_id" "uuid", "name" "text", "geojson" "jsonb", "geojson_utm" "jsonb", "geojson_display" "jsonb", "utm_srid" integer, "acres" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  with current_boundary as (
    select distinct on (f.id)
      f.id as field_id,
      f.name,
      b.boundary_analysis as geom,
      -- The fence line as drawn. Falls back to the analysis polygon only if a
      -- field somehow has no raw boundary, so a picture is still produced.
      coalesce(b.geom, b.boundary_analysis) as display_geom
    from fields f
    join field_boundaries b on b.field_id = f.id
    where f.active
      and f.satellite_enabled
      and b.boundary_analysis is not null
      and not st_isempty(b.boundary_analysis)
    order by f.id, (b.valid_to is null) desc, b.valid_from desc nulls last
  )
  select
    field_id,
    name,
    st_asgeojson(geom)::jsonb,
    st_asgeojson(st_transform(geom, srid))::jsonb,
    st_asgeojson(display_geom)::jsonb,
    srid,
    round((st_area(geom::geography) / 4046.8564224)::numeric, 2)
  from (
    select
      cb.*,
      -- Northern-hemisphere UTM: 326xx, zone = floor((lon + 180) / 6) + 1.
      (32600 + floor((st_x(st_centroid(cb.geom)) + 180) / 6)::integer + 1) as srid,
      (select max(i.sensed_on)
         from sat_images i
        where i.subject_type = 'field'
          and i.subject_id = cb.field_id
          and i.kind = 'truecolour') as newest_image
    from current_boundary cb
  ) z
  -- Nulls first: a field with no picture at all is the most urgent of the lot.
  order by newest_image asc nulls first, name
  limit p_limit;
$$;


ALTER FUNCTION "public"."sat_field_geometries"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sat_field_geometries"("p_limit" integer) IS 'Fields for satellite work, the longest un-photographed first so a limited run does not keep re-doing the head of an alphabetical list.';



CREATE OR REPLACE FUNCTION "public"."sat_n_strip_geometries"("p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("field_id" "uuid", "name" "text", "geojson" "jsonb", "geojson_utm" "jsonb", "geojson_display" "jsonb", "utm_srid" integer, "acres" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select s.id,
         f.name || ' — N-rich strip',
         st_asgeojson(st_transform(inner_utm, 4326))::jsonb,
         st_asgeojson(inner_utm)::jsonb,
         st_asgeojson(s.geom)::jsonb,
         u.srid,
         round((st_area(s.geom::geography) / 4046.8564224)::numeric, 2)
    from n_rich_strips s
    join fields f on f.id = s.field_id
    cross join lateral (select (32600 + floor((st_x(st_centroid(s.geom)) + 180) / 6)::integer + 1) as srid) u
    cross join lateral (select st_buffer(st_transform(s.geom, u.srid), -5) as inner_utm) b
   where f.active and f.satellite_enabled
     and s.crop_year = extract(year from now())::int
     and not st_isempty(inner_utm)
   order by f.name
   limit p_limit
$$;


ALTER FUNCTION "public"."sat_n_strip_geometries"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sat_pasture_geometries"("p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("field_id" "uuid", "name" "text", "geojson" "jsonb", "geojson_utm" "jsonb", "geojson_display" "jsonb", "utm_srid" integer, "acres" numeric)
    LANGUAGE "sql" SECURITY DEFINER
