  from pastures p
  cross join lateral (
    select (32600 + floor((st_x(st_centroid(p.boundary)) + 180) / 6)::integer + 1) as srid
  ) z
  where p.satellite_enabled
    and p.boundary is not null
    and not st_isempty(p.boundary)
  order by p.name
  limit p_limit;
$$;


