CREATE OR REPLACE FUNCTION "public"."sat_pasture_zone_geometries"("p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("field_id" "uuid", "name" "text", "geojson" "jsonb", "geojson_utm" "jsonb", "geojson_display" "jsonb", "utm_srid" integer, "acres" numeric)
    LANGUAGE "sql" SECURITY DEFINER
