CREATE OR REPLACE FUNCTION "public"."sat_rescore_observations"("p_full" numeric, "p_partial" numeric) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  changed integer;
begin
  with obs as (
    select o.id, o.subject_type, o.subject_id, o.zone_id,
           o.sample_count, o.nodata_count, o.resolution_m,
           s.collection
    from sat_observations o
    join sat_scenes s on s.id = o.scene_id
    where o.sample_count is not null and o.nodata_count is not null
  ), area_m2 as materialized (
    select b.field_id as subject_id, 'field'::text as subject_type,
           st_area(b.boundary_analysis::geography) as m2
    from field_boundaries b
    where b.valid_to is null and b.boundary_analysis is not null
    union all
    select p.id, 'pasture', st_area(p.boundary::geography)
    from pastures p
    where p.boundary is not null
  ), floors as materialized (
    select subject_type, subject_id, zone_id, collection, resolution_m,
           max(sample_count) as sample_px,
           min(nodata_count) as discovered_floor
    from obs
    group by 1, 2, 3, 4, 5
  ), denom as (
    select f.*,
           -- What the boundary itself guarantees is inside, at this sensor's
           -- resolution. Sentinel Hub keeps edge pixels whose centre falls
           -- inside, so the raster count runs a few percent above this.
           a.m2 / (f.resolution_m * f.resolution_m) as area_px
    from floors f
    left join area_m2 a
      on a.subject_id = f.subject_id and a.subject_type = f.subject_type
  ), resolved as materialized (
    select d.*,
           greatest(1, case
             -- Zones are a slice of the field and have no area of their own
             -- here, so the discovered floor is all there is to go on.
             when d.zone_id is not null then d.sample_px - d.discovered_floor
             when d.area_px is null then d.sample_px - d.discovered_floor
             -- Discovered count short of what the geometry guarantees means
             -- the "floor" contains weather, not just shape. Geometry wins.
             when (d.sample_px - d.discovered_floor) < d.area_px * 0.90
               then round(d.area_px)::int
             else d.sample_px - d.discovered_floor
           end) as in_polygon_px
    from denom d
  ), graded as (
    select o.id,
           round(least(1.0, greatest(0.0,
             (o.sample_count - o.nodata_count)::numeric / r.in_polygon_px)), 4) as vf
    from obs o
    join resolved r
      on r.subject_type = o.subject_type
     and r.subject_id = o.subject_id
     and r.collection = o.collection
     and r.resolution_m = o.resolution_m
     and r.zone_id is not distinct from o.zone_id
  ), scored as (
    select id, vf,
           case when vf >= p_full then 'full'
                when vf >= p_partial then 'partial'
                else 'rejected' end as q
    from graded
  ), updated as (
    update sat_observations o
    set valid_fraction = s.vf, quality = s.q
    from scored s
    where s.id = o.id
      and (o.valid_fraction is distinct from s.vf or o.quality is distinct from s.q)
    returning 1
  )
  select count(*) into changed from updated;
  return changed;
end;
$$;


ALTER FUNCTION "public"."sat_rescore_observations"("p_full" numeric, "p_partial" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_feed_record"("p_record" "jsonb", "p_lines" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  insert into public.feed_records (ranch_id, herd_group, herd_count_id, period_start, period_end, head_count, notes, updated_by)
  values (
    (p_record->>'ranch_id')::uuid,
    p_record->>'herd_group',
    nullif(p_record->>'herd_count_id', '')::uuid,
    (p_record->>'period_start')::date,
    (p_record->>'period_end')::date,
    nullif(p_record->>'head_count', '')::int,
    nullif(p_record->>'notes', ''),
    auth.uid()
  )
  returning id into v_id;

  insert into public.feed_record_lines (record_id, feed_type_id, feed_type_name, quantity, unit, lb_per_bale, purpose, sort_order)
  select v_id,
         (l->>'feed_type_id')::uuid,
         l->>'feed_type_name',
         (l->>'quantity')::numeric,
         l->>'unit',
         nullif(l->>'lb_per_bale', '')::numeric,
         l->>'purpose',
         (l->>'sort_order')::int
  from jsonb_array_elements(p_lines) as l;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."save_feed_record"("p_record" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_map_feature"("p_id" "uuid", "p_layer" "uuid", "p_label" "text", "p_properties" "jsonb", "p_geojson" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_geom geometry := st_force2d(st_setsrid(st_geomfromgeojson(p_geojson::text), 4326));
  v_id uuid;
begin
  if p_id is null then
    insert into map_features (layer_id, label, properties, geom)
    values (p_layer, p_label, coalesce(p_properties, '{}'), v_geom)
    returning id into v_id;
  else
    update map_features
       set label = p_label, properties = coalesce(p_properties, properties), geom = v_geom, updated_at = now()
     where id = p_id
    returning id into v_id;
    if v_id is null then raise exception 'No such map feature (or not yours to change)'; end if;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."save_map_feature"("p_id" "uuid", "p_layer" "uuid", "p_label" "text", "p_properties" "jsonb", "p_geojson" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_push_subscription"("p_endpoint" "text", "p_p256dh" "text", "p_auth" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if coalesce(p_endpoint, '') = '' then return; end if;
  insert into push_subscriptions (user_id, endpoint, p256dh, auth, last_seen_at)
  values (auth.uid(), p_endpoint, coalesce(p_p256dh, ''), coalesce(p_auth, ''), now())
  on conflict (endpoint) do update
    set user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth, last_seen_at = now();
end $$;


ALTER FUNCTION "public"."save_push_subscription"("p_endpoint" "text", "p_p256dh" "text", "p_auth" "text") OWNER TO "postgres";


