CREATE OR REPLACE FUNCTION "public"."set_bin_location"("p_bin_id" "uuid", "p_lng" double precision, "p_lat" double precision) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not is_active() then
    raise exception 'not permitted';
  end if;
  update public.bins
     set geom = case
                  when p_lng is null or p_lat is null then null
                  else st_setsrid(st_point(p_lng, p_lat), 4326)
                end
   where id = p_bin_id;
end;
$$;


