CREATE OR REPLACE FUNCTION "public"."set_boundary_analysis"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  buffered geometry;
begin
  if new.geom is null then
    new.boundary_analysis := null;
    return new;
  end if;
  -- Only derive it when it was not supplied and the source actually changed,
  -- so an explicitly-set analysis polygon is never overwritten.
  if new.boundary_analysis is null
     or (tg_op = 'UPDATE' and new.geom is distinct from old.geom
         and new.boundary_analysis is not distinct from old.boundary_analysis) then
    buffered := st_multi(st_buffer(new.geom::geography, -15)::geometry);
    new.boundary_analysis := case when st_isempty(buffered) then null else buffered end;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."set_boundary_analysis"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_boundary_analysis"() IS 'Derives the 15 m inward analysis polygon (spec §4.4) whenever a boundary is drawn or moved. Without it a new boundary is invisible to the satellite module and nothing says so.';



CREATE OR REPLACE FUNCTION "public"."topo_cells"("p_surface" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_array(
        round(st_x(geom)::numeric, 6),
        round(st_y(geom)::numeric, 6),
        round(elev_ft, 2),
        round(rem_ft, 2),
        n_points
      )
    ),
    '[]'::jsonb
  )
  from public.field_topo_cells
  where surface_id = p_surface;
$$;


ALTER FUNCTION "public"."topo_cells"("p_surface" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."topo_cells"("p_surface" "uuid") IS 'Every cell of one surface as [lon, lat, elev_ft, rem_ft, n_points]. One row, so PostgREST''s 1000-row cap cannot cut it short.';



CREATE OR REPLACE FUNCTION "public"."use_scale_yield"("p_history" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  r crop_history%rowtype;
begin
  -- Runs as the caller so crop_history's manager-only write policy applies.
  update crop_history set yield_override = false where id = p_history returning * into r;
  if r.id is null then raise exception 'No such history row, or not allowed to change it'; end if;
  perform field_scale_yield(r.field_id, r.crop_id, r.crop_year);
end $$;


ALTER FUNCTION "public"."use_scale_yield"("p_history" "uuid") OWNER TO "postgres";


