    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "reentry_hours" numeric,
    "reentry_note" "text",
    "extraction_attempts" integer DEFAULT 0 NOT NULL,
    "reentry_field_hours" numeric,
    "extraction_force" boolean DEFAULT false NOT NULL,
    "recrop_status" "text",
    "recrop_extracted_at" timestamp with time zone,
    "recrop_note" "text",
    "grazing_rules_status" "text",
    "grazing_rules_extracted_at" timestamp with time zone,
    "grazing_rules_note" "text",
    CONSTRAINT "chemical_labels_application_method_check" CHECK (("application_method" = ANY (ARRAY['ground'::"text", 'aerial'::"text", 'both'::"text"]))),
    CONSTRAINT "chemical_labels_extraction_status_check" CHECK (("extraction_status" = ANY (ARRAY['queued'::"text", 'reading'::"text", 'ok'::"text", 'error'::"text"]))),
    CONSTRAINT "chemical_labels_irrigation_hours_check" CHECK (("irrigation_hours" >= (0)::numeric)),
    CONSTRAINT "chemical_labels_rainfast_hours_check" CHECK (("rainfast_hours" >= (0)::numeric)),
    CONSTRAINT "chemical_labels_reentry_hours_check" CHECK (("reentry_hours" >= (0)::numeric))
);


ALTER TABLE "public"."chemical_labels" OWNER TO "postgres";


COMMENT ON COLUMN "public"."chemical_labels"."label_text" IS 'Full text of the PMRA approved label, extracted from the official PDF. Source of every value in this row.';



COMMENT ON COLUMN "public"."chemical_labels"."reentry_hours" IS 'The longest restricted entry interval stated anywhere on the label, whatever activity it applies to. Kept as the conservative figure; reentry_field_hours is what warnings use.';



COMMENT ON COLUMN "public"."chemical_labels"."extraction_attempts" IS 'Consecutive failed or abandoned reads. Incremented by the worker on a caught error AND by the stale-claim sweep, so a read that dies with the function still counts. Reset to zero on a successful read.';



COMMENT ON COLUMN "public"."chemical_labels"."reentry_field_hours" IS 'Restricted entry interval in hours for ordinary field activities — scouting, irrigation, equipment work. Excludes crop-specific hand labour (hand harvesting, hand detasseling, hand-line irrigation) and non-field settings (greenhouse, turf, sod). This is what re-entry warnings use. May be LONGER than reentry_hours is low, e.g. where a label sets a longer interval for scouting specifically.';



COMMENT ON COLUMN "public"."chemical_labels"."extraction_force" IS 'Read this label again even if its PMRA document is unchanged. Set when the extraction contract changes rather than the document. Cleared by the worker once the read succeeds, so it cannot leave a label re-reading on every pass.';



COMMENT ON COLUMN "public"."chemical_labels"."grazing_rules_status" IS 'read | none_on_label | failed — the grazing-rules extraction. Re-read when the label row changes after grazing_rules_extracted_at.';



