CREATE OR REPLACE VIEW "public"."crop_basis" WITH ("security_invoker"='true') AS
 SELECT "b"."id",
    "b"."crop_id",
    "c"."name" AS "crop_name",
    "b"."buyer",
    "b"."bid_on",
    "b"."price_per_unit",
    "b"."unit",
    "b"."delivery_month",
    "b"."location",
    "b"."series_id",
    "b"."contract_month",
    "f"."value" AS "futures_value",
        CASE
            WHEN ("f"."value" IS NULL) THEN NULL::numeric
            ELSE ("b"."price_per_unit" - "f"."value")
        END AS "basis"
   FROM (("public"."cash_bids" "b"
     JOIN "public"."crops" "c" ON (("c"."id" = "b"."crop_id")))
     LEFT JOIN LATERAL ( SELECT "mf"."value"
           FROM "public"."market_futures" "mf"
          WHERE (("mf"."series_id" = "b"."series_id") AND ("mf"."contract_month" = "b"."contract_month") AND ("mf"."quote_on" <= "b"."bid_on"))
          ORDER BY "mf"."quote_on" DESC
         LIMIT 1) "f" ON (true));


ALTER VIEW "public"."crop_basis" OWNER TO "postgres";


