CREATE OR REPLACE VIEW "public"."crop_position" WITH ("security_invoker"='true') AS
 WITH "plan_rows" AS (
         SELECT "p"."crop_year",
            "p"."crop_id",
            "p"."planned_acres" AS "acres",
            "p"."yield_per_acre_override" AS "yield_override",
            "p"."yield_basis"
           FROM "public"."crop_plans" "p"
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM "public"."field_crop_zones" "z"
                  WHERE (("z"."field_id" = "p"."field_id") AND ("z"."crop_year" = "p"."crop_year")))))
        UNION ALL
         SELECT "z"."crop_year",
            "z"."crop_id",
            "z"."acres",
                CASE
                    WHEN ("p"."crop_id" = "z"."crop_id") THEN "p"."yield_per_acre_override"
                    ELSE NULL::numeric
                END AS "case",
                CASE
                    WHEN ("p"."crop_id" = "z"."crop_id") THEN "p"."yield_basis"
                    ELSE NULL::"text"
                END AS "case"
           FROM ("public"."field_crop_zones" "z"
             LEFT JOIN "public"."crop_plans" "p" ON ((("p"."field_id" = "z"."field_id") AND ("p"."crop_year" = "z"."crop_year"))))
        ), "planned" AS (
         SELECT "r"."crop_year",
            "r"."crop_id",
            "sum"(COALESCE("r"."acres", (0)::numeric)) AS "acres",
            "sum"((COALESCE("r"."acres", (0)::numeric) * COALESCE("r"."yield_override", "c_1"."default_yield_per_acre", (0)::numeric))) AS "expected",
            "sum"(
                CASE
                    WHEN ("r"."yield_basis" = 'clean'::"text") THEN COALESCE("r"."acres", (0)::numeric)
                    ELSE (0)::numeric
                END) AS "clean_acres",
            "sum"(
                CASE
                    WHEN ("r"."yield_basis" = 'pre_clean'::"text") THEN COALESCE("r"."acres", (0)::numeric)
                    ELSE (0)::numeric
                END) AS "pre_clean_acres"
           FROM ("plan_rows" "r"
             JOIN "public"."crops" "c_1" ON (("c_1"."id" = "r"."crop_id")))
          GROUP BY "r"."crop_year", "r"."crop_id"
        ), "sold" AS (
         SELECT "contracts"."crop_year",
            "contracts"."crop_id",
            "sum"(COALESCE("contracts"."bushels", (0)::numeric)) AS "contracted",
            "sum"((COALESCE("contracts"."bushels", (0)::numeric) * COALESCE("contracts"."price_per_unit", (0)::numeric))) AS "contracted_value",
            "sum"(COALESCE("contracts"."delivered_bu", (0)::numeric)) AS "delivered",
            "count"(*) AS "contract_count"
           FROM "public"."contracts"
          WHERE (("contracts"."status" <> 'cancelled'::"public"."contract_status") AND ("contracts"."crop_id" IS NOT NULL))
          GROUP BY "contracts"."crop_year", "contracts"."crop_id"
        ), "stored" AS (
         SELECT "bin_grain_onhand"."crop_id",
            "sum"(COALESCE("bin_grain_onhand"."onhand_bu", (0)::numeric)) AS "onhand"
           FROM "public"."bin_grain_onhand"
          WHERE ("bin_grain_onhand"."crop_id" IS NOT NULL)
          GROUP BY "bin_grain_onhand"."crop_id"
        )
 SELECT COALESCE("pl"."crop_year", "s"."crop_year") AS "crop_year",
    COALESCE("pl"."crop_id", "s"."crop_id") AS "crop_id",
    "c"."name" AS "crop_name",
    "c"."yield_unit",
    "c"."category" AS "crop_category",
    COALESCE("pl"."acres", (0)::numeric) AS "acres",
    COALESCE("pl"."expected", (0)::numeric) AS "expected",
    COALESCE("s"."contracted", (0)::numeric) AS "contracted",
    COALESCE("s"."contracted_value", (0)::numeric) AS "contracted_value",
    COALESCE("s"."delivered", (0)::numeric) AS "delivered",
    COALESCE("s"."contract_count", (0)::bigint) AS "contract_count",
    COALESCE("st"."onhand", (0)::numeric) AS "onhand",
    GREATEST((COALESCE("pl"."expected", (0)::numeric) - COALESCE("s"."contracted", (0)::numeric)), (0)::numeric) AS "open_quantity",
        CASE
            WHEN (COALESCE("s"."contracted", (0)::numeric) > COALESCE("pl"."expected", (0)::numeric)) THEN (COALESCE("s"."contracted", (0)::numeric) - COALESCE("pl"."expected", (0)::numeric))
            ELSE NULL::numeric
        END AS "oversold",
        CASE
            WHEN (COALESCE("s"."contracted", (0)::numeric) > (0)::numeric) THEN (COALESCE("s"."contracted_value", (0)::numeric) / NULLIF("s"."contracted", (0)::numeric))
            ELSE NULL::numeric
        END AS "avg_contract_price",
    COALESCE("pl"."clean_acres", (0)::numeric) AS "clean_acres",
    COALESCE("pl"."pre_clean_acres", (0)::numeric) AS "pre_clean_acres"
   FROM ((("planned" "pl"
     FULL JOIN "sold" "s" ON ((("s"."crop_year" = "pl"."crop_year") AND ("s"."crop_id" = "pl"."crop_id"))))
     LEFT JOIN "public"."crops" "c" ON (("c"."id" = COALESCE("pl"."crop_id", "s"."crop_id"))))
     LEFT JOIN "stored" "st" ON (("st"."crop_id" = COALESCE("pl"."crop_id", "s"."crop_id"))))
  WHERE (COALESCE("pl"."crop_id", "s"."crop_id") IS NOT NULL);


