COMMENT ON COLUMN "public"."feed_types"."dm_pct" IS 'Dry matter %, as fed. Book value until a feed_tests row replaces it.';



COMMENT ON COLUMN "public"."feed_types"."tdn_pct" IS 'TDN %, dry-matter basis.';



COMMENT ON COLUMN "public"."feed_types"."storage_loss_pct" IS 'Dry matter still to be lost in storage before it is fed (weathering, spoilage), %; counted off what is left when working out days of feed.';



COMMENT ON COLUMN "public"."feed_types"."price_per_tonne" IS 'What a tonne of this feed costs, as fed, $/t. Blank until known; the cost-of-gain worksheet asks for it.';



COMMENT ON COLUMN "public"."feed_types"."price_source" IS 'afsc: kept current from AFSC''s AgriStability price list (afsc-feed-prices-cron); manual: typed by hand, never overwritten; estimate: a starting figure to replace.';



COMMENT ON COLUMN "public"."feed_types"."afsc_item" IS 'The AFSC price-list line this feed is priced from, e.g. "Alfalfa Hay - 1st Cut" or "Feed Barley"; null = not on the list.';



CREATE OR REPLACE VIEW "public"."feed_on_hand" WITH ("security_invoker"='true') AS
 WITH "put_up" AS (
         SELECT "i"."ranch_id",
            "i"."feed_type_id",
            "sum"(
                CASE
                    WHEN ("i"."unit" = 'lb'::"text") THEN "i"."quantity"
                    ELSE ("i"."quantity" * COALESCE("i"."lb_per_bale", "ft_1"."default_lb_per_bale"))
                END) AS "lb",
            "count"(*) FILTER (WHERE (("i"."unit" <> 'lb'::"text") AND (COALESCE("i"."lb_per_bale", "ft_1"."default_lb_per_bale") IS NULL))) AS "unweighed"
           FROM ("public"."feed_inventory" "i"
             JOIN "public"."feed_types" "ft_1" ON (("ft_1"."id" = "i"."feed_type_id")))
          GROUP BY "i"."ranch_id", "i"."feed_type_id"
        ), "fed" AS (
         SELECT "r"."ranch_id",
            "l"."feed_type_id",
            "sum"(
                CASE
                    WHEN ("l"."unit" = 'lb'::"text") THEN "l"."quantity"
                    ELSE ("l"."quantity" * COALESCE("l"."lb_per_bale", "ft_1"."default_lb_per_bale"))
                END) AS "lb",
            "count"(*) FILTER (WHERE (("l"."unit" <> 'lb'::"text") AND (COALESCE("l"."lb_per_bale", "ft_1"."default_lb_per_bale") IS NULL))) AS "unweighed"
           FROM (("public"."feed_record_lines" "l"
             JOIN "public"."feed_records" "r" ON (("r"."id" = "l"."record_id")))
             LEFT JOIN "public"."feed_types" "ft_1" ON (("ft_1"."id" = "l"."feed_type_id")))
          WHERE ("l"."feed_type_id" IS NOT NULL)
          GROUP BY "r"."ranch_id", "l"."feed_type_id"
        )
 SELECT COALESCE("p"."ranch_id", "f"."ranch_id") AS "ranch_id",
    COALESCE("p"."feed_type_id", "f"."feed_type_id") AS "feed_type_id",
    "ft"."name" AS "feed_name",
    "ft"."default_unit",
    "ft"."default_lb_per_bale",
    "ft"."is_bedding",
    COALESCE("p"."lb", (0)::numeric) AS "put_up_lb",
    COALESCE("f"."lb", (0)::numeric) AS "fed_lb",
    (COALESCE("p"."lb", (0)::numeric) - COALESCE("f"."lb", (0)::numeric)) AS "remaining_lb",
    (COALESCE("p"."unweighed", (0)::bigint) + COALESCE("f"."unweighed", (0)::bigint)) AS "unweighed_lines"
   FROM (("put_up" "p"
     FULL JOIN "fed" "f" ON ((("f"."ranch_id" = "p"."ranch_id") AND ("f"."feed_type_id" = "p"."feed_type_id"))))
     JOIN "public"."feed_types" "ft" ON (("ft"."id" = COALESCE("p"."feed_type_id", "f"."feed_type_id"))));


ALTER VIEW "public"."feed_on_hand" OWNER TO "postgres";


COMMENT ON VIEW "public"."feed_on_hand" IS 'Per ranch per feed type: pounds put up, pounds fed off the feed sheets, and what is left. A bale with no weight recorded is counted in unweighed_lines rather than as zero pounds.';



