    "years_from" integer,
    "years_to" integer,
    "chu_median" numeric,
    "chu_p20" numeric,
    "chu_p80" numeric,
    "ffd_median" numeric,
    "spring_frost_median" "date",
    "fall_frost_median" "date",
    "season_precip_mm_median" numeric,
    "outlook" "jsonb",
