);


ALTER TABLE "public"."field_climate" OWNER TO "postgres";


COMMENT ON TABLE "public"."field_climate" IS 'Heat units, frost-free days and the seasonal outlook per 0.25° cell; season-outlook-background.';



COMMENT ON COLUMN "public"."field_climate"."chu_p20" IS 'Corn heat units in a cool year (the 20th percentile of the years on record).';



COMMENT ON COLUMN "public"."field_climate"."outlook" IS '{ plan_year, cansips: { temp_above, temp_below, precip_above, precip_below, months }, seas5: [{ month, temp_anom_c, precip_anom_mm }], chu_shift }';



