CREATE TABLE IF NOT EXISTS "public"."moisture_tests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "crop_year" integer NOT NULL,
    "field_id" "uuid",
    "crop_id" "uuid",
    "bin_id" "uuid",
    "temperature_c" numeric,
    "meter_reading" numeric,
    "chart_key" "text",
    "sample_weight_g" integer,
    "moisture_pct" numeric NOT NULL,
    "grade" "text",
    "entered_by_hand" boolean DEFAULT false NOT NULL,
    "note" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sample_condition" "text",
    CONSTRAINT "moisture_tests_grade_check" CHECK (("grade" = ANY (ARRAY['too_dry'::"text", 'dry'::"text", 'tough'::"text", 'damp'::"text", 'moist'::"text", 'wet'::"text"]))),
    CONSTRAINT "moisture_tests_meter_reading_check" CHECK ((("meter_reading" IS NULL) OR (("meter_reading" >= (0)::numeric) AND ("meter_reading" <= (100)::numeric)))),
    CONSTRAINT "moisture_tests_moisture_pct_check" CHECK ((("moisture_pct" >= (0)::numeric) AND ("moisture_pct" < (100)::numeric))),
    CONSTRAINT "moisture_tests_sample_condition_check" CHECK (("sample_condition" = ANY (ARRAY['screened'::"text", 'dirty'::"text"]))),
    CONSTRAINT "moisture_tests_temperature_c_check" CHECK ((("temperature_c" IS NULL) OR (("temperature_c" >= ('-50'::integer)::numeric) AND ("temperature_c" <= (60)::numeric))))
);


ALTER TABLE "public"."moisture_tests" OWNER TO "postgres";


COMMENT ON COLUMN "public"."moisture_tests"."sample_condition" IS 'screened = cleaned before testing; dirty = tested as it came off, dockage and all. Null when not recorded.';



CREATE OR REPLACE VIEW "public"."field_harvest_moisture" WITH ("security_invoker"='true') AS
 SELECT "field_id",
    "crop_year",
    "crop_id",
    "count"(*) AS "tests",
    "round"("avg"("moisture_pct"), 1) AS "avg_pct",
    "max"("moisture_pct") AS "max_pct",
    "min"("moisture_pct") AS "min_pct",
    "max"("tested_at") AS "last_tested_at",
    "bool_or"((("grade" IS NOT NULL) AND ("grade" <> 'dry'::"text"))) AS "any_above_dry",
    (EXISTS ( SELECT 1
           FROM "public"."jd_field_operations" "o"
          WHERE (("o"."field_id" = "t"."field_id") AND ("o"."crop_season" = "t"."crop_year") AND ("o"."operation_type" = 'harvest'::"text")))) AS "harvest_recorded"
   FROM "public"."moisture_tests" "t"
  WHERE ("field_id" IS NOT NULL)
  GROUP BY "field_id", "crop_year", "crop_id";


ALTER VIEW "public"."field_harvest_moisture" OWNER TO "postgres";


COMMENT ON VIEW "public"."field_harvest_moisture" IS 'Per field per crop year: how many moisture tests, the average and the wettest, and whether harvest is recorded. The average is the number for a buyer; the maximum is the number that decides whether the bin needs air.';



