CREATE TABLE IF NOT EXISTS "public"."sat_observations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "scene_id" "uuid" NOT NULL,
    "subject_type" "text" NOT NULL,
    "subject_id" "uuid" NOT NULL,
    "zone_id" "uuid" DEFAULT '00000000-0000-0000-0000-000000000000'::"uuid" NOT NULL,
    "sensed_on" "date" NOT NULL,
    "valid_fraction" numeric NOT NULL,
    "quality" "text" NOT NULL,
    "harmonized" boolean DEFAULT false NOT NULL,
    "ndvi_mean" numeric,
    "ndvi_stddev" numeric,
    "ndvi_p10" numeric,
    "ndvi_p90" numeric,
    "ndre_mean" numeric,
    "evi2_mean" numeric,
    "ndmi_mean" numeric,
    "fcover" numeric,
    "s1_vv_mean" numeric,
    "s1_vh_mean" numeric,
    "raw_stats" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sample_count" integer,
    "nodata_count" integer,
    "resolution_m" numeric DEFAULT 10 NOT NULL,
    "ndvi_harmonized" numeric,
    "harmonization_source" "text",
    CONSTRAINT "sat_observations_quality_check" CHECK (("quality" = ANY (ARRAY['full'::"text", 'partial'::"text", 'rejected'::"text"]))),
    CONSTRAINT "sat_observations_subject_type_check" CHECK (("subject_type" = ANY (ARRAY['field'::"text", 'pasture'::"text", 'pasture_zone'::"text", 'n_strip'::"text"])))
);


ALTER TABLE "public"."sat_observations" OWNER TO "postgres";


COMMENT ON COLUMN "public"."sat_observations"."harmonized" IS 'Whether this observation sits on the Sentinel-2 NDVI scale. Sentinel-2 is true by definition. Landsat is false until coefficients are regressed from 15+ same-day pairs (spec §4.5). Unharmonized rows are excluded from sat_daily.';



COMMENT ON COLUMN "public"."sat_observations"."ndvi_mean" IS 'Exactly what the sensor reported. Never rewritten by a harmonization coefficient.';



COMMENT ON COLUMN "public"."sat_observations"."sample_count" IS 'Pixels in the rasterised bounding box, from Sentinel Hub. Includes pixels outside the polygon.';



COMMENT ON COLUMN "public"."sat_observations"."nodata_count" IS 'Pixels excluded: those outside the polygon PLUS those the cloud mask rejected.';



COMMENT ON COLUMN "public"."sat_observations"."resolution_m" IS 'Ground resolution the statistics were requested at. Needed to turn a polygon area into an expected pixel count.';



COMMENT ON COLUMN "public"."sat_observations"."ndvi_harmonized" IS 'ndvi_mean placed on the Sentinel-2 scale. Recomputed whenever coefficients change; this is what the daily curve reads.';



CREATE OR REPLACE VIEW "public"."field_ndre" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON ("subject_id") "subject_id" AS "field_id",
    "ndre_mean",
    "sensed_on",
    (CURRENT_DATE - "sensed_on") AS "days_since"
   FROM "public"."sat_observations" "o"
  WHERE (("subject_type" = 'field'::"text") AND ("zone_id" = '00000000-0000-0000-0000-000000000000'::"uuid") AND ("quality" = 'full'::"text") AND ("ndre_mean" IS NOT NULL))
  ORDER BY "subject_id", "sensed_on" DESC;


ALTER VIEW "public"."field_ndre" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."field_pasture_overlap" WITH ("security_invoker"='true') AS
 SELECT "b"."field_id",
    "p"."id" AS "pasture_id",
    "p"."name" AS "pasture_name",
    "round"((("public"."st_area"(("public"."st_intersection"("p"."boundary", "b"."geom"))::"public"."geography") / (4046.86)::double precision))::numeric, 1) AS "overlap_acres",
    "round"((("public"."st_area"(("b"."geom")::"public"."geography") / (4046.86)::double precision))::numeric, 1) AS "field_acres"
   FROM ("public"."field_boundaries" "b"
     JOIN "public"."pastures" "p" ON ((("p"."boundary" IS NOT NULL) AND "public"."st_intersects"("p"."boundary", "b"."geom"))))
  WHERE (("b"."valid_to" IS NULL) AND ("public"."st_area"(("public"."st_intersection"("p"."boundary", "b"."geom"))::"public"."geography") >= (4046.86)::double precision));


ALTER VIEW "public"."field_pasture_overlap" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."field_pivots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "field_id" "uuid" NOT NULL,
    "pump_id" "uuid",
    "water_licence_id" "uuid",
    "acres_irrigated" numeric,
