    "tire_type" "text",
    "gpm" numeric,
    "meter_name" "text",
    "contact" "text",
    "phone" "text",
    "pivot_year" integer,
    "system_type" "text",
    "system_capacity_ls" numeric,
    "time_to_full_circle_h" numeric,
    "end_gun_degrees" numeric,
    "application_efficiency" numeric,
    "acre_feet_allotment" numeric,
