    "on_river" boolean DEFAULT false NOT NULL,
    "smrid_area" integer,
    "water_source" "text",
    "licence_note" "text",
    "end_gun" boolean,
    "end_treatment" "text",
    "drop_height_ft" numeric,
    "pressure_regulators" boolean,
