    "pivot_pressure_psi" numeric,
    "efficiency_basis" "text",
    "gpm_source" "text",
    "model" "text",
    "serial_number" "text",
    "pivot_type" "text",
    "voltage" numeric,
    "running_amps" numeric,
    "max_fuse_amps" numeric,
    "plate_amps" numeric,
    "phase" integer,
    "hz" integer,
    "nameplate_note" "text",
    "equipment_flags" "text",
