    "not_used_note" "text",
    "operated_by" "text",
    CONSTRAINT "field_pivots_phase_check" CHECK (("phase" = ANY (ARRAY[1, 3]))),
    CONSTRAINT "field_pivots_water_source_check" CHECK (("water_source" = ANY (ARRAY['oldman_river'::"text", 'south_saskatchewan_river'::"text", 'smrid'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."field_pivots" OWNER TO "postgres";


COMMENT ON COLUMN "public"."field_pivots"."contact" IS 'The GROWER contact for this field. The water coordinator is derived from smrid_area, not stored here.';



COMMENT ON COLUMN "public"."field_pivots"."acre_feet_allotment" IS 'This field''s share of its licence, acre-feet a year (equal depth over the licensed pivot acres unless set by hand).';



COMMENT ON COLUMN "public"."field_pivots"."alloted_inches" IS 'An override, inches per acre. Blank = the pivot takes SMRID''s current allotment from smrid.com (water_allotments). Set only when this pivot is genuinely allowed a different depth.';



COMMENT ON COLUMN "public"."field_pivots"."water_source" IS 'Where the water comes from: the Oldman or South Saskatchewan under a licence, or the SMRID canal.';



COMMENT ON COLUMN "public"."field_pivots"."end_treatment" IS 'What the pipe ends in when there is no end gun: none, end_spray, boom_back, corner_arm, swing_arm, drop_extension, other.';



COMMENT ON COLUMN "public"."field_pivots"."efficiency_basis" IS 'Where application_efficiency came from: default (85% everywhere until 2026), suggested (from the equipment), measured (catch cans / soil readings).';



COMMENT ON COLUMN "public"."field_pivots"."gpm_source" IS 'fieldnet = copied from the FieldNET panel''s configured flow (raw.reporting_flow); blank = entered.';



COMMENT ON COLUMN "public"."field_pivots"."model" IS 'Pivot model, from the nameplate.';



COMMENT ON COLUMN "public"."field_pivots"."serial_number" IS 'Pivot serial number, from the nameplate.';



COMMENT ON COLUMN "public"."field_pivots"."pivot_type" IS 'Type, as stamped on the nameplate (a maker''s code, not the sprinkler package).';



COMMENT ON COLUMN "public"."field_pivots"."voltage" IS 'Pivot supply volts, from the nameplate.';



COMMENT ON COLUMN "public"."field_pivots"."running_amps" IS 'Running amps, from the nameplate.';



COMMENT ON COLUMN "public"."field_pivots"."max_fuse_amps" IS 'Largest fuse or breaker the nameplate allows on the pivot''s supply, amps.';



COMMENT ON COLUMN "public"."field_pivots"."plate_amps" IS 'An amps figure on the nameplate whose label is worn or not one of the above. Say what it is in nameplate_note.';



COMMENT ON COLUMN "public"."field_pivots"."nameplate_note" IS 'Anything else on the plate: worn labels, values whose label cannot be read.';



COMMENT ON COLUMN "public"."field_pivots"."equipment_flags" IS 'Things on this pivot''s record that disagree and need checking, one per line. Clear a line once it is sorted.';



COMMENT ON COLUMN "public"."field_pivots"."not_used" IS 'The pivot stands on the field but is never run: the field counts as dryland everywhere (AFSC, fertilizer, water budgets, the irrigation model).';



COMMENT ON COLUMN "public"."field_pivots"."operated_by" IS 'Somebody else runs this pivot and its pump for us (the landowner): no pump or equipment details are kept, and none are asked for.';



CREATE TABLE IF NOT EXISTS "public"."fields" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "farm_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "legal_land_description" "text",
    "fah_field_id" integer,
    "active" boolean DEFAULT true NOT NULL,
    "notes_md" "text",
    "pivot_start_instructions_md" "text",
    "soil_notes_md" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "jd_field_id" "text",
    "centroid" "public"."geography"(Point,4326),
    "assigned_station_id" "uuid",
    "assigned_station_distance_m" double precision,
    "assignment_mode" "text" DEFAULT 'auto'::"text" NOT NULL,
    "soil_texture" "text",
    "soil_fc" double precision,
    "soil_wp" double precision,
    "satellite_enabled" boolean DEFAULT true NOT NULL,
    "satellite_kc_enabled" boolean DEFAULT false NOT NULL,
    "soil_source" "text",
    "rented_out_acres" numeric(10,2),
    "rented_out_to" "text",
    "tenure_notes" "text",
    "boundary_locked" boolean DEFAULT false NOT NULL,
    "rented_out_crop" "text",
    "rain_gauge_id" "uuid",
    "grazed_after_harvest" boolean DEFAULT false NOT NULL,
    "open_to_pasture" boolean DEFAULT false NOT NULL,
    "grazing_note" "text",
    "route_via" "text" DEFAULT 'auto'::"text" NOT NULL,
    "route_through" "jsonb",
    CONSTRAINT "fields_rented_out_acres_check" CHECK ((("rented_out_acres" IS NULL) OR ("rented_out_acres" >= (0)::numeric))),
    CONSTRAINT "fields_route_via_check" CHECK (("route_via" = ANY (ARRAY['auto'::"text", 'trails'::"text"]))),
    CONSTRAINT "fields_soil_source_check" CHECK ((("soil_source" IS NULL) OR ("soil_source" = ANY (ARRAY['survey'::"text", 'manual'::"text"]))))
);


ALTER TABLE "public"."fields" OWNER TO "postgres";


COMMENT ON COLUMN "public"."fields"."satellite_kc_enabled" IS 'Whether the water balance may use satellite-measured Kc instead of the crop table. Off until satellite and table Kc have been compared for a full season on this field (spec §12 phase 4).';



COMMENT ON COLUMN "public"."fields"."soil_source" IS 'Origin of soil_fc/soil_wp: survey = AGRASID lookup, manual = set by a person. Never overwrite a manual row from an import.';



COMMENT ON COLUMN "public"."fields"."rented_out_acres" IS 'Acres of this field farmed by someone else. The drawn boundary covers OUR part only, so the whole field is mapped acres plus this.';



COMMENT ON COLUMN "public"."fields"."rented_out_to" IS 'Who farms the rented-out part.';



COMMENT ON COLUMN "public"."fields"."boundary_locked" IS 'Keep the current boundary; the Deere sync will not replace it.';



COMMENT ON COLUMN "public"."fields"."grazed_after_harvest" IS 'Cattle may graze whatever crop this field had once it is harvested; a spray restricting grazing or feeding here is alerted.';



COMMENT ON COLUMN "public"."fields"."open_to_pasture" IS 'Not fenced off from the pasture around it: cattle in that pasture are on this field.';



COMMENT ON COLUMN "public"."fields"."grazing_note" IS 'Anything about grazing this field (e.g. a grazing trial planned).';



COMMENT ON COLUMN "public"."fields"."route_via" IS 'auto: the road where it reaches the field, else a farm trail; trails: the farm''s trails wherever they reach the field, even when the road is shorter.';



COMMENT ON COLUMN "public"."fields"."route_through" IS 'Points the route from the yard must pass through, in order: [{lat, lng}]. Null for none.';



CREATE OR REPLACE VIEW "public"."field_points" WITH ("security_invoker"='true') AS
 SELECT "id",
    "name",
    "public"."st_y"(("centroid")::"public"."geometry") AS "lat",
    "public"."st_x"(("centroid")::"public"."geometry") AS "lng"
   FROM "public"."fields"
  WHERE ("centroid" IS NOT NULL);


ALTER VIEW "public"."field_points" OWNER TO "postgres";


