    "hrdpa_mm" numeric,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."field_rain_daily" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sat_daily" (
    "subject_type" "text" NOT NULL,
    "subject_id" "uuid" NOT NULL,
    "zone_id" "uuid",
    "day" "date" NOT NULL,
    "ndvi" numeric,
    "fcover" numeric,
    "kc" numeric,
    "biomass_kg_dm_ha" numeric,
    "days_since_observation" integer NOT NULL,
    "confidence" "text" NOT NULL,
    "zone_key" "uuid" GENERATED ALWAYS AS (COALESCE("zone_id", '00000000-0000-0000-0000-000000000000'::"uuid")) STORED NOT NULL,
    CONSTRAINT "sat_daily_confidence_check" CHECK (("confidence" = ANY (ARRAY['high'::"text", 'medium'::"text", 'low'::"text"])))
);


ALTER TABLE "public"."sat_daily" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."field_satellite" WITH ("security_invoker"='true') AS
 SELECT "f"."id" AS "field_id",
    "f"."name",
    "f"."satellite_enabled",
    "d"."ndvi",
    "d"."fcover",
    (CURRENT_DATE - "o"."sensed_on") AS "days_since_observation",
        CASE
            WHEN ("o"."sensed_on" IS NULL) THEN NULL::"text"
            WHEN ((CURRENT_DATE - "o"."sensed_on") > 8) THEN 'low'::"text"
            WHEN ((CURRENT_DATE - "o"."sensed_on") > 3) THEN
            CASE
                WHEN ("d"."confidence" = 'low'::"text") THEN 'low'::"text"
                ELSE 'medium'::"text"
            END
            ELSE "d"."confidence"
        END AS "confidence",
    "d"."day" AS "ndvi_day",
    "o"."sensed_on" AS "last_observed_on"
   FROM (("public"."fields" "f"
     LEFT JOIN LATERAL ( SELECT "s"."subject_type",
            "s"."subject_id",
            "s"."zone_id",
            "s"."day",
            "s"."ndvi",
            "s"."fcover",
            "s"."kc",
            "s"."biomass_kg_dm_ha",
            "s"."days_since_observation",
            "s"."confidence",
            "s"."zone_key"
           FROM "public"."sat_daily" "s"
          WHERE (("s"."subject_type" = 'field'::"text") AND ("s"."subject_id" = "f"."id") AND ("s"."zone_id" IS NULL))
          ORDER BY "s"."day" DESC
         LIMIT 1) "d" ON (true))
     LEFT JOIN LATERAL ( SELECT "max"("ob"."sensed_on") AS "sensed_on"
           FROM "public"."sat_observations" "ob"
          WHERE (("ob"."subject_type" = 'field'::"text") AND ("ob"."subject_id" = "f"."id") AND ("ob"."quality" <> 'rejected'::"text") AND ("ob"."ndvi_mean" IS NOT NULL))) "o" ON (true));


ALTER VIEW "public"."field_satellite" OWNER TO "postgres";


