CREATE OR REPLACE VIEW "public"."field_season_progress" WITH ("security_invoker"='true') AS
 SELECT "f"."id" AS "field_id",
    "f"."name" AS "field_name",
    "p"."crop_year",
    "b"."acres",
    "c"."name" AS "crop_name",
    COALESCE("c"."counts_for_seeding", true) AS "counts_for_seeding",
    COALESCE("c"."counts_for_harvest", true) AS "counts_for_harvest",
    "c"."progress_note",
    (EXISTS ( SELECT 1
           FROM "public"."jd_field_operations" "o"
          WHERE (("o"."field_id" = "f"."id") AND ("o"."crop_season" = "p"."crop_year") AND ("o"."operation_type" = 'seeding'::"text")))) AS "has_seeding",
    (EXISTS ( SELECT 1
           FROM "public"."jd_field_operations" "o"
          WHERE (("o"."field_id" = "f"."id") AND ("o"."crop_season" = "p"."crop_year") AND ("o"."operation_type" = 'harvest'::"text")))) AS "has_harvest",
    (EXISTS ( SELECT 1
           FROM "public"."jd_field_operations" "o"
          WHERE (("o"."field_id" = "f"."id") AND ("o"."crop_season" = "p"."crop_year")))) AS "has_any_operation"
   FROM ((("public"."fields" "f"
     JOIN "public"."field_boundaries" "b" ON ((("b"."field_id" = "f"."id") AND ("b"."valid_to" IS NULL))))
     JOIN "public"."crop_plans" "p" ON (("p"."field_id" = "f"."id")))
     LEFT JOIN "public"."crops" "c" ON (("c"."id" = "p"."crop_id")))
  WHERE "f"."active";


ALTER VIEW "public"."field_season_progress" OWNER TO "postgres";


COMMENT ON VIEW "public"."field_season_progress" IS 'Per field per crop year: mapped acres, the planned crop, whether that crop is ours to seed and harvest, and whether Deere recorded each operation.';



