    "raw_mm" numeric,
    "zr_m" numeric,
    "kc" numeric,
    "status" "text",
    "rec_net_mm" numeric,
    "rec_gross_mm" numeric,
    "days_to_irrigate" integer,
    "ke" numeric,
    "de_mm" numeric,
    "is_forecast" boolean DEFAULT false NOT NULL,
    "avail_100_mm" numeric,
    "avail_50_mm" numeric,
    "over_irrigation_mm" numeric,
    "lost_precip_mm" numeric,
    "rainfall_mm" numeric,
    "effective_irrigation_mm" numeric,
    "zone_id" "uuid",
    "rain_source" "text",
    "runoff_mm" numeric,
    "ks" numeric,
    CONSTRAINT "water_balance_daily_status_check" CHECK (("status" = ANY (ARRAY['ok'::"text", 'soon'::"text", 'now'::"text", 'stress'::"text"])))
);


ALTER TABLE "public"."water_balance_daily" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."field_season_water" WITH ("security_invoker"='true') AS
 SELECT "field_id",
    (EXTRACT("year" FROM "date"))::integer AS "year",
    ("count"(*))::integer AS "days",
    "sum"("etc_mm") AS "etc_mm",
    "sum"(
        CASE
            WHEN ("ks" > 0.05) THEN ("etc_mm" / "ks")
            ELSE "etc_mm"
        END) AS "potential_etc_mm",
    "sum"("rainfall_mm") AS "rain_mm",
    "sum"((COALESCE("lost_precip_mm", (0)::numeric) + COALESCE("runoff_mm", (0)::numeric))) AS "rain_lost_mm",
    "sum"(COALESCE("effective_irrigation_mm", (0)::numeric)) AS "effective_irrigation_mm",
    "sum"(COALESCE("over_irrigation_mm", (0)::numeric)) AS "over_irrigation_mm",
    ("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['now'::"text", 'stress'::"text"]))))::integer AS "stress_days"
   FROM "public"."water_balance_daily" "b"
  WHERE (("zone_id" IS NULL) AND (NOT COALESCE("is_forecast", false)) AND ((EXTRACT("month" FROM "date") >= (5)::numeric) AND (EXTRACT("month" FROM "date") <= (9)::numeric)))
  GROUP BY "field_id", (EXTRACT("year" FROM "date"));


