    "texture_top" "text",
    "fc_pct" numeric,
    "wp_pct" numeric,
    "detail" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "geom" "public"."geometry"(MultiPolygon,4326) NOT NULL,
    "acres" numeric GENERATED ALWAYS AS ("round"((("public"."st_area"(("geom")::"public"."geography") / (4046.8564224)::double precision))::numeric, 2)) STORED,
    "imported_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


