CREATE OR REPLACE VIEW "public"."field_soil_units" WITH ("security_invoker"='true') AS
 WITH "current_boundary" AS (
         SELECT DISTINCT ON ("field_boundaries"."field_id") "field_boundaries"."field_id",
            "field_boundaries"."geom"
           FROM "public"."field_boundaries"
          WHERE ("field_boundaries"."valid_to" IS NULL)
          ORDER BY "field_boundaries"."field_id", "field_boundaries"."id"
        )
 SELECT "b"."field_id",
    "s"."poly_id",
    "s"."munit",
    "s"."soil_name",
    "s"."subgroup",
    "s"."drainage",
    "s"."salinity",
    "s"."texture_top",
    "s"."fc_pct",
    "s"."wp_pct",
    "s"."detail",
    "round"((("public"."st_area"(("public"."st_intersection"("s"."geom", "b"."geom"))::"public"."geography") / (4046.8564224)::double precision))::numeric, 1) AS "overlap_acres",
    "round"(((("public"."st_area"("public"."st_intersection"("s"."geom", "b"."geom")) / NULLIF("public"."st_area"("b"."geom"), (0)::double precision)) * (100)::double precision))::numeric, 0) AS "pct_of_field"
   FROM ("current_boundary" "b"
     JOIN "public"."soil_landscape_polygons" "s" ON ("public"."st_intersects"("s"."geom", "b"."geom")))
  WHERE (("public"."st_area"("public"."st_intersection"("s"."geom", "b"."geom")) / NULLIF("public"."st_area"("b"."geom"), (0)::double precision)) > (0.005)::double precision)
  ORDER BY "b"."field_id", ("public"."st_area"("public"."st_intersection"("s"."geom", "b"."geom"))) DESC;


