CREATE OR REPLACE VIEW "public"."pasture_forage_index" WITH ("security_invoker"='true') AS
 SELECT "o"."subject_id" AS "pasture_id",
    "p"."name",
    "p"."area_acres",
    "o"."sensed_on",
    "o"."ndvi_mean",
    "o"."evi2_mean",
    "o"."ndre_mean",
    "o"."quality",
    "round"(COALESCE(((0.5 * GREATEST((0)::numeric, LEAST((1)::numeric, (("o"."ndre_mean" - 0.10) / 0.45)))) + (0.5 * GREATEST((0)::numeric, LEAST((1)::numeric, (("o"."evi2_mean" - 0.05) / 0.65))))), GREATEST((0)::numeric, LEAST((1)::numeric, (("o"."evi2_mean" - 0.05) / 0.65))), GREATEST((0)::numeric, LEAST((1)::numeric, (("o"."ndvi_mean" - 0.15) / 0.60)))), 4) AS "forage_index"
   FROM ("public"."sat_observations" "o"
     JOIN "public"."pastures" "p" ON (("p"."id" = "o"."subject_id")))
  WHERE (("o"."subject_type" = 'pasture'::"text") AND ("o"."quality" <> 'rejected'::"text") AND "o"."harmonized" AND ("o"."ndvi_mean" IS NOT NULL));


ALTER VIEW "public"."pasture_forage_index" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."pasture_standing_forage" WITH ("security_invoker"='true') AS
 WITH "latest" AS (
         SELECT DISTINCT ON ("f"."pasture_id") "f"."pasture_id",
            "f"."name",
            "f"."area_acres",
            "f"."sensed_on",
            "f"."forage_index",
            "f"."quality"
           FROM "public"."pasture_forage_index" "f"
          ORDER BY "f"."pasture_id", "f"."sensed_on" DESC
        ), "recent" AS (
         SELECT "f"."pasture_id",
            "regr_slope"(("f"."forage_index")::double precision, ((EXTRACT("epoch" FROM "f"."sensed_on") / 86400.0))::double precision) AS "slope_per_day",
            "count"(*) AS "points"
           FROM ("public"."pasture_forage_index" "f"
             JOIN "latest" "l_1" ON (("l_1"."pasture_id" = "f"."pasture_id")))
          WHERE ("f"."sensed_on" > ("l_1"."sensed_on" - 14))
          GROUP BY "f"."pasture_id"
        ), "rested" AS (
         SELECT "p_1"."id" AS "pasture_id",
            "max"("g"."moved_out_on") AS "last_moved_out",
            "bool_or"((("g"."id" IS NOT NULL) AND ("g"."moved_out_on" IS NULL))) AS "cattle_on_now"
           FROM ("public"."pastures" "p_1"
             LEFT JOIN "public"."grazing_events" "g" ON (("g"."pasture_id" = "p_1"."id")))
          GROUP BY "p_1"."id"
        )
 SELECT "l"."pasture_id",
    "l"."name",
    "l"."area_acres",
    "l"."sensed_on" AS "last_look",
    (CURRENT_DATE - "l"."sensed_on") AS "days_since_look",
    "l"."forage_index",
    "round"(((100.0 * "l"."forage_index") / NULLIF("max"("l"."forage_index") OVER (), (0)::numeric)), 0) AS "percent_of_best",
    "round"(("r"."slope_per_day")::numeric, 5) AS "regrowth_per_day",
    "r"."points" AS "regrowth_points",
    "rs"."cattle_on_now",
    "rs"."last_moved_out",
        CASE
            WHEN ("rs"."last_moved_out" IS NULL) THEN NULL::integer
            ELSE (CURRENT_DATE - "rs"."last_moved_out")
        END AS "days_rested",
    "p"."min_rest_days",
    "p"."harvest_efficiency",
    "p"."grazing_system"
   FROM ((("latest" "l"
     JOIN "public"."pastures" "p" ON (("p"."id" = "l"."pasture_id")))
     LEFT JOIN "recent" "r" ON (("r"."pasture_id" = "l"."pasture_id")))
     LEFT JOIN "rested" "rs" ON (("rs"."pasture_id" = "l"."pasture_id")));


ALTER VIEW "public"."pasture_standing_forage" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."pasture_readiness_now" WITH ("security_invoker"='true') AS
 WITH "ndre_trend" AS (
         SELECT "f"."pasture_id",
            "regr_slope"(("f"."ndre_mean")::double precision, ((EXTRACT("epoch" FROM "f"."sensed_on") / 86400.0))::double precision) AS "ndre_slope"
           FROM "public"."pasture_forage_index" "f"
          WHERE (("f"."ndre_mean" IS NOT NULL) AND ("f"."sensed_on" > (CURRENT_DATE - 21)))
          GROUP BY "f"."pasture_id"
        )
 SELECT "s"."pasture_id",
    "s"."name",
    "s"."area_acres",
    "s"."last_look",
    "s"."days_since_look",
    "s"."forage_index",
    "s"."percent_of_best",
    "s"."regrowth_per_day",
    "s"."regrowth_points",
    "s"."cattle_on_now",
    "s"."last_moved_out",
    "s"."days_rested",
    "s"."min_rest_days",
    "s"."harvest_efficiency",
    "s"."grazing_system",
    "n"."ndre_slope",
        CASE
            WHEN ("s"."forage_index" < 0.20) THEN 'overgrazed'::"text"
            WHEN (("s"."days_rested" IS NOT NULL) AND ("s"."days_rested" < "s"."min_rest_days")) THEN 'not_ready'::"text"
            WHEN ("s"."forage_index" < 0.35) THEN 'not_ready'::"text"
            WHEN (("s"."forage_index" >= 0.70) AND (COALESCE("n"."ndre_slope", (0)::double precision) < ('-0.002'::numeric)::double precision)) THEN 'overmature'::"text"
            WHEN (("s"."forage_index" >= 0.50) AND (COALESCE("s"."regrowth_per_day", (0)::numeric) > (0)::numeric)) THEN 'optimal'::"text"
            ELSE 'ready'::"text"
        END AS "readiness",
        CASE
            WHEN ("s"."forage_index" < 0.20) THEN 'Standing forage is below the residual floor.'::"text"
            WHEN (("s"."days_rested" IS NOT NULL) AND ("s"."days_rested" < "s"."min_rest_days")) THEN (((('Only '::"text" || "s"."days_rested") || ' days rested of '::"text") || "s"."min_rest_days") || ' needed.'::"text")
            WHEN ("s"."forage_index" < 0.35) THEN 'Not enough standing forage yet.'::"text"
            WHEN (("s"."forage_index" >= 0.70) AND (COALESCE("n"."ndre_slope", (0)::double precision) < ('-0.002'::numeric)::double precision)) THEN 'Plenty of bulk, but quality is falling — red-edge response is dropping while forage holds.'::"text"
            WHEN (("s"."forage_index" >= 0.50) AND (COALESCE("s"."regrowth_per_day", (0)::numeric) > (0)::numeric)) THEN 'Well fed and still growing.'::"text"
            ELSE 'Enough forage and adequately rested.'::"text"
        END AS "readiness_reason"
   FROM ("public"."pasture_standing_forage" "s"
     LEFT JOIN "ndre_trend" "n" ON (("n"."pasture_id" = "s"."pasture_id")));


ALTER VIEW "public"."pasture_readiness_now" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."grazing_pasture_status" WITH ("security_invoker"='true') AS
 SELECT "g"."id" AS "grazing_pasture_id",
    "g"."ranch_id",
    "g"."name",
    "g"."active",
    "g"."grass_quality",
    "g"."km2",
    "g"."non_grazeable_ac",
    "g"."irrigated_ac",
    "g"."pasture_id",
    ("g"."pasture_id" IS NOT NULL) AS "mapped",
    "r"."forage_index",
    "r"."percent_of_best",
    "r"."regrowth_per_day",
    "r"."readiness",
    "r"."readiness_reason",
    "r"."days_rested",
    "r"."cattle_on_now",
    "r"."last_look",
    "r"."days_since_look"
   FROM ("public"."grazing_pastures" "g"
     LEFT JOIN "public"."pasture_readiness_now" "r" ON (("r"."pasture_id" = "g"."pasture_id")));


