CREATE OR REPLACE VIEW "public"."herd_forage_runway" WITH ("security_invoker"='true') AS
 WITH "standing" AS (
         SELECT "sum"((("r"."forage_index" * COALESCE("r"."area_acres", (0)::numeric)) * "p"."harvest_efficiency")) AS "index_acres",
            "sum"(COALESCE("r"."area_acres", (0)::numeric)) AS "total_acres",
            "count"(*) AS "paddocks",
            "min"("r"."last_look") AS "oldest_look"
           FROM ("public"."pasture_readiness_now" "r"
             JOIN "public"."pastures" "p" ON (("p"."id" = "r"."pasture_id")))
          WHERE (NOT COALESCE("r"."cattle_on_now", false))
        ), "herd" AS (
         SELECT COALESCE("sum"("h_1"."head_count"), (0)::bigint) AS "head",
            COALESCE("sum"((("h_1"."head_count")::numeric * COALESCE("h_1"."au_equivalent", (1)::numeric))), (0)::numeric) AS "animal_units"
           FROM "public"."grazing_herd" "h_1"
          WHERE (("h_1"."end_date" IS NULL) OR ("h_1"."end_date" >= CURRENT_DATE))
        )
 SELECT "s"."index_acres",
    "s"."total_acres",
    "s"."paddocks",
    "s"."oldest_look",
    "h"."head",
    "h"."animal_units",
        CASE
            WHEN ("h"."animal_units" > (0)::numeric) THEN "round"(("s"."index_acres" / "h"."animal_units"), 2)
            ELSE NULL::numeric
        END AS "index_acres_per_au"
   FROM ("standing" "s"
     CROSS JOIN "herd" "h");


ALTER VIEW "public"."herd_forage_runway" OWNER TO "postgres";


COMMENT ON VIEW "public"."herd_forage_runway" IS 'Standing forage across ungrazed paddocks against current herd size. Relative units until clip-and-weigh calibration exists (spec §14.3) — the trend is real, the absolute day count would not be.';



