CREATE OR REPLACE VIEW "public"."input_onhand" WITH ("security_invoker"='true') AS
 SELECT "input_item_id",
    "sum"(
        CASE "movement_type"
            WHEN 'purchase'::"public"."input_movement_type" THEN "quantity"
            WHEN 'adjustment'::"public"."input_movement_type" THEN "quantity"
            ELSE (- "quantity")
        END) AS "onhand",
    "sum"(
        CASE
            WHEN ("movement_type" = 'purchase'::"public"."input_movement_type") THEN ("quantity" * COALESCE("unit_cost", (0)::numeric))
            ELSE (0)::numeric
        END) AS "total_purchased_cost"
   FROM "public"."input_movements"
  GROUP BY "input_item_id";


