    "serial_number" "text",
    "vin" "text",
    "engine_hours" numeric,
    "engine_hours_at" timestamp with time zone,
    "archived" boolean DEFAULT false NOT NULL,
    "is_manual" boolean DEFAULT false NOT NULL,
    "notes" "text",
    "raw" "jsonb",
    "synced_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "platform_machine_id" "text",
    "receiver_height_in" numeric,
    "receiver_height_source" "text",
    "receiver_height_note" "text",
    "warranty_provider" "text",
    "warranty_starts_on" "date",
    "warranty_expires_on" "date",
    "warranty_hours" integer,
    "warranty_note" "text",
    CONSTRAINT "jd_equipment_engine_hours_check" CHECK (("engine_hours" >= (0)::numeric)),
    CONSTRAINT "jd_equipment_receiver_height_in_check" CHECK ((("receiver_height_in" IS NULL) OR (("receiver_height_in" > (0)::numeric) AND ("receiver_height_in" < (400)::numeric)))),
    CONSTRAINT "jd_equipment_receiver_height_source_check" CHECK ((("receiver_height_source" IS NULL) OR ("receiver_height_source" = ANY (ARRAY['measured'::"text", 'deere'::"text", 'estimated'::"text"])))),
    CONSTRAINT "jd_equipment_warranty_hours_check" CHECK ((("warranty_hours" IS NULL) OR ("warranty_hours" > 0)))
);


ALTER TABLE "public"."jd_equipment" OWNER TO "postgres";


COMMENT ON COLUMN "public"."jd_equipment"."receiver_height_in" IS 'Height of the GNSS receiver above ground, inches. Subtracted from logged elevation before a surface is built.';



COMMENT ON COLUMN "public"."jd_equipment"."receiver_height_source" IS 'measured = someone put a tape on it; deere = came from the API; estimated = a guess, and the surface should say so.';



COMMENT ON COLUMN "public"."jd_equipment"."warranty_provider" IS 'Who carries it — the dealer, John Deere, an extended plan. Free text; a warranty is a contract with somebody, and whose it is decides who to phone.';



COMMENT ON COLUMN "public"."jd_equipment"."warranty_starts_on" IS 'Delivery or in-service date. Only used to say how much of the term is gone.';



COMMENT ON COLUMN "public"."jd_equipment"."warranty_expires_on" IS 'The date it runs out. Null means nobody has recorded one, which is NOT the same as "no warranty" — the countdown says so rather than implying cover that may not exist.';



COMMENT ON COLUMN "public"."jd_equipment"."warranty_hours" IS 'Engine-hour limit, where the term is "5 years or 3,000 hours". Compared against engine_hours, which Deere does sync.';



COMMENT ON COLUMN "public"."jd_equipment"."warranty_note" IS 'What is actually covered. "Powertrain only" is the difference between a phone call and a bill.';



