    "label" "text",
    "geom" "public"."geometry"(MultiPolygon,4326) NOT NULL,
    "extra_lb_n" numeric,
    "notes" "text",
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."n_rich_strips" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."n_rich_strip_list" WITH ("security_invoker"='true') AS
 SELECT "id",
    "field_id",
    "crop_year",
    "label",
    "extra_lb_n",
    "notes",
    "created_at",
    ("public"."st_asgeojson"("geom"))::"jsonb" AS "geojson",
    "round"((("public"."st_area"(("geom")::"public"."geography") / (4046.8564224)::double precision))::numeric, 2) AS "acres"
   FROM "public"."n_rich_strips" "s";


ALTER VIEW "public"."n_rich_strip_list" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."n_strip_sufficiency" WITH ("security_invoker"='true') AS
 SELECT "s"."id" AS "strip_id",
    "s"."field_id",
    "s"."crop_year",
    "so"."sensed_on",
    "so"."ndre_mean" AS "strip_ndre",
    "fo"."ndre_mean" AS "field_ndre",
        CASE
            WHEN ("so"."ndre_mean" > (0)::numeric) THEN "round"(("fo"."ndre_mean" / "so"."ndre_mean"), 3)
            ELSE NULL::numeric
        END AS "si"
   FROM (("public"."n_rich_strips" "s"
     JOIN "public"."sat_observations" "so" ON ((("so"."subject_type" = 'n_strip'::"text") AND ("so"."subject_id" = "s"."id") AND ("so"."quality" <> 'rejected'::"text"))))
     JOIN "public"."sat_observations" "fo" ON ((("fo"."subject_type" = 'field'::"text") AND ("fo"."subject_id" = "s"."field_id") AND ("fo"."scene_id" = "so"."scene_id") AND ("fo"."quality" <> 'rejected'::"text"))))
  WHERE (("so"."ndre_mean" IS NOT NULL) AND ("fo"."ndre_mean" IS NOT NULL));


ALTER VIEW "public"."n_strip_sufficiency" OWNER TO "postgres";


