CREATE OR REPLACE VIEW "public"."pasture_calibration_readiness" WITH ("security_invoker"='true') AS
 SELECT "count"(*) AS "samples",
    "count"(*) FILTER (WHERE ("measured_kg_dm_ha" < (800)::numeric)) AS "low_samples",
    "count"(*) FILTER (WHERE (("measured_kg_dm_ha" >= (800)::numeric) AND ("measured_kg_dm_ha" <= (1800)::numeric))) AS "mid_samples",
    "count"(*) FILTER (WHERE ("measured_kg_dm_ha" > (1800)::numeric)) AS "high_samples",
    "count"(DISTINCT "pasture_id") AS "pastures_sampled",
    "count"(DISTINCT EXTRACT("year" FROM "sampled_on")) AS "seasons",
    (("count"(*) >= 12) AND ("count"(*) FILTER (WHERE ("measured_kg_dm_ha" < (800)::numeric)) >= 3) AND ("count"(*) FILTER (WHERE (("measured_kg_dm_ha" >= (800)::numeric) AND ("measured_kg_dm_ha" <= (1800)::numeric))) >= 3) AND ("count"(*) FILTER (WHERE ("measured_kg_dm_ha" > (1800)::numeric)) >= 3)) AS "may_report_absolute"
   FROM "public"."pasture_biomass_calibration"
  WHERE ("ndvi_at_sample" IS NOT NULL);


ALTER VIEW "public"."pasture_calibration_readiness" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."pasture_map" WITH ("security_invoker"='true') AS
 SELECT "p"."id",
    "p"."name",
    "p"."legal_description" AS "ranch",
    "p"."pasture_type",
    "p"."area_acres",
    "p"."satellite_enabled",
    ("public"."st_asgeojson"("p"."boundary"))::"jsonb" AS "geojson",
    "d"."ndvi",
    "d"."biomass_kg_dm_ha",
    (CURRENT_DATE - "o"."sensed_on") AS "days_since_observation",
        CASE
            WHEN ("o"."sensed_on" IS NULL) THEN NULL::"text"
            WHEN ((CURRENT_DATE - "o"."sensed_on") > 8) THEN 'low'::"text"
            WHEN ((CURRENT_DATE - "o"."sensed_on") > 3) THEN
            CASE
                WHEN ("d"."confidence" = 'low'::"text") THEN 'low'::"text"
                ELSE 'medium'::"text"
            END
            ELSE "d"."confidence"
        END AS "confidence",
    "d"."day" AS "ndvi_day"
   FROM (("public"."pastures" "p"
     LEFT JOIN LATERAL ( SELECT "s"."subject_type",
            "s"."subject_id",
            "s"."zone_id",
            "s"."day",
            "s"."ndvi",
            "s"."fcover",
            "s"."kc",
            "s"."biomass_kg_dm_ha",
            "s"."days_since_observation",
            "s"."confidence",
            "s"."zone_key"
           FROM "public"."sat_daily" "s"
          WHERE (("s"."subject_type" = 'pasture'::"text") AND ("s"."subject_id" = "p"."id") AND ("s"."zone_id" IS NULL))
          ORDER BY "s"."day" DESC
         LIMIT 1) "d" ON (true))
     LEFT JOIN LATERAL ( SELECT "max"("ob"."sensed_on") AS "sensed_on"
           FROM "public"."sat_observations" "ob"
          WHERE (("ob"."subject_type" = 'pasture'::"text") AND ("ob"."subject_id" = "p"."id") AND ("ob"."quality" <> 'rejected'::"text") AND ("ob"."ndvi_mean" IS NOT NULL))) "o" ON (true));


ALTER VIEW "public"."pasture_map" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."pasture_rotation_order" WITH ("security_invoker"='true') AS
 SELECT "pasture_id",
    "name",
    "area_acres",
    "last_look",
    "days_since_look",
    "forage_index",
    "percent_of_best",
    "regrowth_per_day",
    "regrowth_points",
    "cattle_on_now",
    "last_moved_out",
    "days_rested",
    "min_rest_days",
    "harvest_efficiency",
    "grazing_system",
    "ndre_slope",
    "readiness",
    "readiness_reason",
    "round"(((((0.40 * LEAST(1.0, (("forage_index" * COALESCE("area_acres", (0)::numeric)) / 500.0))) + (0.30 *
        CASE "readiness"
            WHEN 'optimal'::"text" THEN 1.0
            WHEN 'ready'::"text" THEN 0.8
            WHEN 'overmature'::"text" THEN 0.5
            WHEN 'not_ready'::"text" THEN 0.1
            ELSE 0.0
        END)) + (0.15 * LEAST(1.0, ((COALESCE("days_rested", 0))::numeric / (NULLIF(("min_rest_days" * 2), 0))::numeric)))) + (0.15 *
        CASE
            WHEN (COALESCE("regrowth_per_day", (0)::numeric) > (0)::numeric) THEN 1.0
            ELSE 0.0
        END)), 4) AS "rotation_score",
        CASE
            WHEN ("days_since_look" > 14) THEN (('Ranked on a look '::"text" || "days_since_look") || ' days old — treat as provisional.'::"text")
            ELSE NULL::"text"
        END AS "caveat"
   FROM "public"."pasture_readiness_now" "r"
  WHERE (NOT COALESCE("cattle_on_now", false))
  ORDER BY ("round"(((((0.40 * LEAST(1.0, (("forage_index" * COALESCE("area_acres", (0)::numeric)) / 500.0))) + (0.30 *
        CASE "readiness"
            WHEN 'optimal'::"text" THEN 1.0
            WHEN 'ready'::"text" THEN 0.8
            WHEN 'overmature'::"text" THEN 0.5
            WHEN 'not_ready'::"text" THEN 0.1
            ELSE 0.0
        END)) + (0.15 * LEAST(1.0, ((COALESCE("days_rested", 0))::numeric / (NULLIF(("min_rest_days" * 2), 0))::numeric)))) + (0.15 *
        CASE
            WHEN (COALESCE("regrowth_per_day", (0)::numeric) > (0)::numeric) THEN 1.0
            ELSE 0.0
        END)), 4)) DESC;


ALTER VIEW "public"."pasture_rotation_order" OWNER TO "postgres";


