COMMENT ON COLUMN "public"."plc_readings"."last_good_at" IS 'When the value in this row was last actually measured. Null means it has never been read successfully. Compare with read_at, which moves on every attempt.';



CREATE OR REPLACE VIEW "public"."plc_line_integrity" WITH ("security_invoker"='true') AS
 WITH "watch" AS (
         SELECT "plc_line_watch"."plc_pump" AS "n",
            "plc_line_watch"."muted",
            "plc_line_watch"."muted_reason",
            "plc_line_watch"."decay_psi_per_hour"
           FROM "public"."plc_line_watch"
        ), "state" AS (
         SELECT "w"."n",
            "w"."muted",
            "w"."muted_reason",
            "w"."decay_psi_per_hour",
            ( SELECT "r"."value_bool"
                   FROM "public"."plc_readings" "r"
                  WHERE ("r"."tag" = (('pump'::"text" || "w"."n") || '.run_ind'::"text"))) AS "running_now",
            ( SELECT "r"."value_bool"
                   FROM "public"."plc_readings" "r"
                  WHERE ("r"."tag" = (('pump'::"text" || "w"."n") || '.line_full'::"text"))) AS "full_now",
            ( SELECT "r"."value_num"
                   FROM "public"."plc_readings" "r"
                  WHERE ("r"."tag" = (('pump'::"text" || "w"."n") || '.local_psi'::"text"))) AS "psi_now",
            ( SELECT "r"."read_at"
                   FROM "public"."plc_readings" "r"
                  WHERE ("r"."tag" = (('pump'::"text" || "w"."n") || '.local_psi'::"text"))) AS "psi_read_at",
            ( SELECT "max"("h"."read_at") AS "max"
                   FROM "public"."plc_reading_history" "h"
                  WHERE (("h"."tag" = (('pump'::"text" || "w"."n") || '.run_ind'::"text")) AND ("h"."value_bool" IS TRUE))) AS "last_running_at"
           FROM "watch" "w"
        ), "win" AS (
         SELECT "s"."n",
            "s"."muted",
            "s"."muted_reason",
            "s"."decay_psi_per_hour",
            "s"."running_now",
            "s"."full_now",
            "s"."psi_now",
            "s"."psi_read_at",
            "s"."last_running_at",
            (COALESCE("s"."last_running_at", ( SELECT "min"("h"."read_at") AS "min"
                   FROM "public"."plc_reading_history" "h"
                  WHERE ("h"."tag" = (('pump'::"text" || "s"."n") || '.local_psi'::"text")))) + '00:03:00'::interval) AS "from_at"
           FROM "state" "s"
        ), "baseline" AS (
         SELECT "w"."n",
            "w"."muted",
            "w"."muted_reason",
            "w"."decay_psi_per_hour",
            "w"."running_now",
            "w"."full_now",
            "w"."psi_now",
            "w"."psi_read_at",
            "w"."last_running_at",
            "w"."from_at",
            COALESCE(( SELECT "h"."value_num"
                   FROM "public"."plc_reading_history" "h"
                  WHERE (("h"."tag" = (('pump'::"text" || "w"."n") || '.local_psi'::"text")) AND ("h"."read_at" >= "w"."from_at"))
                  ORDER BY "h"."read_at"
                 LIMIT 1), ( SELECT "h"."value_num"
                   FROM "public"."plc_reading_history" "h"
                  WHERE (("h"."tag" = (('pump'::"text" || "w"."n") || '.local_psi'::"text")) AND ("h"."read_at" < "w"."from_at"))
                  ORDER BY "h"."read_at" DESC
                 LIMIT 1)) AS "psi_start",
            COALESCE(( SELECT "h"."read_at"
                   FROM "public"."plc_reading_history" "h"
                  WHERE (("h"."tag" = (('pump'::"text" || "w"."n") || '.local_psi'::"text")) AND ("h"."read_at" >= "w"."from_at"))
                  ORDER BY "h"."read_at"
                 LIMIT 1), "w"."from_at") AS "psi_start_at",
            (EXISTS ( SELECT 1
                   FROM "public"."plc_reading_history" "h"
                  WHERE (("h"."tag" = (('pump'::"text" || "w"."n") || '.line_full'::"text")) AND ("h"."value_bool" IS FALSE) AND ("h"."read_at" >= "w"."from_at")))) AS "lost_full_while_idle"
           FROM "win" "w"
        ), "calc" AS (
         SELECT "b"."n",
            "b"."muted",
            "b"."muted_reason",
            "b"."decay_psi_per_hour",
            "b"."running_now",
            "b"."full_now",
            "b"."psi_now",
            "b"."psi_read_at",
            "b"."last_running_at",
            "b"."from_at",
            "b"."psi_start",
            "b"."psi_start_at",
            "b"."lost_full_while_idle",
            GREATEST((EXTRACT("epoch" FROM (COALESCE("b"."psi_read_at", "now"()) - "b"."psi_start_at")) / 3600.0), (0)::numeric) AS "idle_hours",
            ("b"."psi_start" - "b"."psi_now") AS "psi_drop"
           FROM "baseline" "b"
        )
 SELECT "n" AS "plc_pump",
    "muted",
    "muted_reason",
    "decay_psi_per_hour" AS "decay_limit",
    "running_now",
    "full_now",
    "psi_now",
    "psi_read_at",
    "last_running_at",
    "psi_start",
    "psi_start_at",
    "lost_full_while_idle",
    "round"("idle_hours", 2) AS "idle_hours",
    "psi_drop",
        CASE
            WHEN ("idle_hours" >= 0.5) THEN "round"(("psi_drop" / "idle_hours"), 2)
            ELSE NULL::numeric
        END AS "decay_rate",
        CASE
            WHEN "muted" THEN 'muted'::"text"
            WHEN ("running_now" IS TRUE) THEN 'running'::"text"
            WHEN (("psi_now" IS NULL) OR ("psi_start" IS NULL)) THEN 'unknown'::"text"
            WHEN ("idle_hours" < 0.5) THEN 'settling'::"text"
            WHEN "lost_full_while_idle" THEN 'leak'::"text"
            WHEN (("psi_drop" / "idle_hours") >= "decay_psi_per_hour") THEN 'leak'::"text"
            WHEN (("psi_drop" / "idle_hours") >= ("decay_psi_per_hour" / (2)::numeric)) THEN 'watch'::"text"
            ELSE 'ok'::"text"
        END AS "status"
   FROM "calc";


ALTER VIEW "public"."plc_line_integrity" OWNER TO "postgres";


COMMENT ON VIEW "public"."plc_line_integrity" IS 'Per-turbine leak verdict from pressure decay while idle, plus the panel''s own line-full bit. Muting is per turbine and lives in plc_line_watch.';



