    "label" "text",
    "description" "text",
    "area" "text" NOT NULL,
    "address" integer NOT NULL,
    "data_type" "text" NOT NULL,
    "unit" "text",
    "writable" boolean DEFAULT false NOT NULL,
    "min_value" numeric,
    "max_value" numeric,
    "definition" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "plc_tags_area_check" CHECK (("area" = ANY (ARRAY['holding'::"text", 'input'::"text", 'coil'::"text", 'discrete'::"text"])))
);


