CREATE OR REPLACE VIEW "public"."plc_live" WITH ("security_invoker"='true') AS
 SELECT "d"."id" AS "device_id",
    "d"."key" AS "device_key",
    "d"."label" AS "device_label",
    "t"."name" AS "tag",
    COALESCE("t"."label", "t"."name") AS "tag_label",
    "t"."unit",
    "t"."data_type",
    "t"."writable",
    "t"."min_value",
    "t"."max_value",
    "t"."description",
    "r"."value_num",
    "r"."value_bool",
    "r"."value_text",
    "r"."quality",
    "r"."error",
    "r"."raw",
    "r"."read_at",
    "r"."last_good_at",
    (EXTRACT("epoch" FROM ("now"() - "r"."read_at")))::integer AS "age_seconds",
    (EXTRACT("epoch" FROM ("now"() - "r"."last_good_at")))::integer AS "value_age_seconds"
   FROM (("public"."plc_devices" "d"
     JOIN "public"."plc_tags" "t" ON (("t"."device_id" = "d"."id")))
     LEFT JOIN "public"."plc_readings" "r" ON ((("r"."device_id" = "d"."id") AND ("r"."tag" = "t"."name"))));


ALTER VIEW "public"."plc_live" OWNER TO "postgres";


