COMMENT ON COLUMN "public"."sat_scenes"."orbit_direction" IS 'ASCENDING or DESCENDING. Radar backscatter is not comparable across orbit directions: the incidence angle differs, and a mixed series has step changes in it that no ground event produced.';



CREATE OR REPLACE VIEW "public"."sat_field_series" WITH ("security_invoker"='true') AS
 SELECT "o"."subject_id" AS "field_id",
    "f"."name",
    "ch"."crop_id",
    "o"."sensed_on",
    "o"."ndvi_mean",
    "o"."ndre_mean",
    "o"."valid_fraction",
    "sc"."collection",
    "public"."st_y"("public"."st_centroid"("b"."boundary_analysis")) AS "centroid_lat",
    "public"."st_x"("public"."st_centroid"("b"."boundary_analysis")) AS "centroid_lon"
   FROM (((("public"."sat_observations" "o"
     JOIN "public"."sat_scenes" "sc" ON (("sc"."id" = "o"."scene_id")))
     JOIN "public"."fields" "f" ON (("f"."id" = "o"."subject_id")))
     LEFT JOIN "public"."field_boundaries" "b" ON ((("b"."field_id" = "f"."id") AND ("b"."valid_to" IS NULL))))
     LEFT JOIN "public"."crop_history" "ch" ON ((("ch"."field_id" = "f"."id") AND ("ch"."crop_year" = (EXTRACT("year" FROM "o"."sensed_on"))::integer))))
  WHERE (("o"."subject_type" = 'field'::"text") AND ("o"."zone_id" = '00000000-0000-0000-0000-000000000000'::"uuid") AND ("o"."quality" = 'full'::"text") AND "o"."harmonized" AND ("o"."ndvi_mean" IS NOT NULL));


ALTER VIEW "public"."sat_field_series" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sat_harmonization" (
    "collection" "text" NOT NULL,
    "slope" numeric NOT NULL,
    "intercept" numeric NOT NULL,
    "n_pairs" integer DEFAULT 0 NOT NULL,
    "r2" numeric,
    "source" "text" NOT NULL,
    "derived_on" "date",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sat_harmonization_source_check" CHECK (("source" = ANY (ARRAY['native'::"text", 'provisional'::"text", 'local'::"text"])))
);


ALTER TABLE "public"."sat_harmonization" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sat_harmonization_pairs" WITH ("security_invoker"='true') AS
 SELECT "s2"."subject_type",
    "s2"."subject_id",
    "f"."name",
    "s2"."sensed_on" AS "s2_day",
    "ls"."sensed_on" AS "landsat_day",
    "s2"."ndvi_mean" AS "s2_ndvi",
    "ls"."ndvi_mean" AS "landsat_ndvi",
    ("s2"."ndvi_mean" - "ls"."ndvi_mean") AS "difference",
    "s2"."valid_fraction" AS "s2_valid",
    "ls"."valid_fraction" AS "landsat_valid"
   FROM (((("public"."sat_observations" "s2"
     JOIN "public"."sat_scenes" "s2s" ON ((("s2s"."id" = "s2"."scene_id") AND ("s2s"."collection" = 'sentinel-2-l2a'::"text"))))
     JOIN "public"."sat_observations" "ls" ON ((("ls"."subject_type" = "s2"."subject_type") AND ("ls"."subject_id" = "s2"."subject_id") AND (NOT ("ls"."zone_id" IS DISTINCT FROM "s2"."zone_id")) AND ("abs"(("ls"."sensed_on" - "s2"."sensed_on")) <= 1))))
     JOIN "public"."sat_scenes" "lss" ON ((("lss"."id" = "ls"."scene_id") AND ("lss"."collection" = 'landsat-c2-l2'::"text"))))
     LEFT JOIN "public"."fields" "f" ON ((("f"."id" = "s2"."subject_id") AND ("s2"."subject_type" = 'field'::"text"))))
  WHERE (("s2"."valid_fraction" >= 0.90) AND ("ls"."valid_fraction" >= 0.90) AND ("s2"."ndvi_mean" IS NOT NULL) AND ("ls"."ndvi_mean" IS NOT NULL));


ALTER VIEW "public"."sat_harmonization_pairs" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sat_images" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
