    "scene_id" "uuid" NOT NULL,
    "sensed_on" "date" NOT NULL,
    "kind" "text" DEFAULT 'truecolour'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "width" integer NOT NULL,
    "height" integer NOT NULL,
    "west" numeric NOT NULL,
    "south" numeric NOT NULL,
    "east" numeric NOT NULL,
    "north" numeric NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "stretch_min" numeric,
    "stretch_max" numeric,
    CONSTRAINT "sat_images_kind_check" CHECK (("kind" = ANY (ARRAY['truecolour'::"text", 'ndvi'::"text", 'ndvi_field'::"text", 'ndre'::"text", 'ndre_field'::"text"])))
);


ALTER TABLE "public"."sat_images" OWNER TO "postgres";


COMMENT ON COLUMN "public"."sat_images"."kind" IS 'truecolour = the photograph. ndvi = per-pixel NDVI on the farm-wide scale, comparable between fields. ndvi_field = per-pixel NDVI stretched to this field''s own range, comparable only within itself.';



COMMENT ON COLUMN "public"."sat_images"."stretch_min" IS 'Low end of the NDVI range this raster''s colour ramp covers. Per field, per scene — the ramp is relative, so a colour is only comparable within one image.';



CREATE OR REPLACE VIEW "public"."sat_kc_comparison" WITH ("security_invoker"='true') AS
 SELECT "f"."id" AS "field_id",
    "f"."name",
    "f"."satellite_kc_enabled",
    "d"."day",
    "d"."ndvi",
    "d"."fcover",
    "d"."kc" AS "satellite_kc",
    "w"."kc" AS "table_kc",
    "round"(("d"."kc" - "w"."kc"), 3) AS "difference",
    "d"."confidence",
    "d"."days_since_observation",
    ("d"."confidence" = 'high'::"text") AS "would_have_been_used"
   FROM (("public"."fields" "f"
     JOIN "public"."sat_daily" "d" ON ((("d"."subject_type" = 'field'::"text") AND ("d"."subject_id" = "f"."id") AND ("d"."zone_id" IS NULL))))
     LEFT JOIN "public"."water_balance_daily" "w" ON ((("w"."field_id" = "f"."id") AND ("w"."date" = "d"."day") AND (NOT "w"."is_forecast"))))
  WHERE ("d"."kc" IS NOT NULL);


ALTER VIEW "public"."sat_kc_comparison" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sat_latest_image" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON ("i"."subject_type", "i"."subject_id", "i"."kind") "i"."subject_type",
    "i"."subject_id",
    "i"."kind",
    "i"."sensed_on",
    "i"."storage_path",
    "i"."west",
    "i"."south",
    "i"."east",
    "i"."north",
    "i"."stretch_min",
    "i"."stretch_max",
    "s"."collection",
    (CURRENT_DATE - "i"."sensed_on") AS "days_old"
   FROM ("public"."sat_images" "i"
     JOIN "public"."sat_scenes" "s" ON (("s"."id" = "i"."scene_id")))
  ORDER BY "i"."subject_type", "i"."subject_id", "i"."kind", "i"."sensed_on" DESC;


ALTER VIEW "public"."sat_latest_image" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sat_radar_change" WITH ("security_invoker"='true') AS
 SELECT "o"."subject_type",
    "o"."subject_id",
    "o"."sensed_on",
    "s"."orbit_direction",
    "o"."s1_vv_mean",
    "o"."s1_vh_mean",
    ("o"."s1_vv_mean" - "lag"("o"."s1_vv_mean") OVER "w") AS "vv_change_db",
    ("o"."s1_vh_mean" - "lag"("o"."s1_vh_mean") OVER "w") AS "vh_change_db",
    "lag"("o"."sensed_on") OVER "w" AS "previous_look"
   FROM ("public"."sat_observations" "o"
     JOIN "public"."sat_scenes" "s" ON (("s"."id" = "o"."scene_id")))
  WHERE (("s"."collection" = 'sentinel-1-grd'::"text") AND ("o"."s1_vv_mean" IS NOT NULL))
  WINDOW "w" AS (PARTITION BY "o"."subject_type", "o"."subject_id", "s"."orbit_direction" ORDER BY "o"."sensed_on");


ALTER VIEW "public"."sat_radar_change" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sat_moisture_disagreement" WITH ("security_invoker"='true') AS
 WITH "radar" AS (
         SELECT "r"."subject_id" AS "field_id",
            "r"."sensed_on",
            "r"."vv_change_db",
            "lag"("r"."sensed_on") OVER (PARTITION BY "r"."subject_id", "r"."orbit_direction" ORDER BY "r"."sensed_on") AS "previous_look"
           FROM "public"."sat_radar_change" "r"
          WHERE (("r"."subject_type" = 'field'::"text") AND ("r"."vv_change_db" IS NOT NULL))
        )
 SELECT "f"."id" AS "field_id",
    "f"."name",
    "ra"."sensed_on",
    "ra"."previous_look",
    "round"("ra"."vv_change_db", 2) AS "vv_change_db",
    "round"(("wb_now"."dr_mm" - "wb_prev"."dr_mm"), 1) AS "depletion_change_mm",
    ('Radar says the surface got wetter while the water balance says the field dried. '::"text" || 'Likely an unlogged irrigation, an unrecorded rain, or a weather station fault.'::"text") AS "note"
   FROM ((("radar" "ra"
     JOIN "public"."fields" "f" ON (("f"."id" = "ra"."field_id")))
     JOIN "public"."water_balance_daily" "wb_now" ON ((("wb_now"."field_id" = "ra"."field_id") AND ("wb_now"."date" = "ra"."sensed_on") AND (NOT "wb_now"."is_forecast"))))
     JOIN "public"."water_balance_daily" "wb_prev" ON ((("wb_prev"."field_id" = "ra"."field_id") AND ("wb_prev"."date" = "ra"."previous_look") AND (NOT "wb_prev"."is_forecast"))))
  WHERE (("ra"."vv_change_db" >= 1.5) AND (("wb_now"."dr_mm" - "wb_prev"."dr_mm") >= (10)::numeric));


ALTER VIEW "public"."sat_moisture_disagreement" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sat_ndvi_scale" WITH ("security_invoker"='true') AS
 WITH "bounds" AS (
         SELECT "min"("sat_observations"."ndvi_p10") AS "lo_raw",
            "max"("sat_observations"."ndvi_p90") AS "hi_raw",
            "count"(*) AS "observations"
           FROM "public"."sat_observations"
          WHERE (("sat_observations"."quality" = 'full'::"text") AND "sat_observations"."harmonized" AND ("sat_observations"."ndvi_p10" IS NOT NULL) AND ("sat_observations"."ndvi_p90" IS NOT NULL) AND ("sat_observations"."sensed_on" > (CURRENT_DATE - 60)))
        )
 SELECT COALESCE(("floor"(("lo_raw" / 0.05)) * 0.05), 0.15) AS "lo",
    COALESCE(("ceil"(("hi_raw" / 0.05)) * 0.05), 0.95) AS "hi",
    COALESCE("observations", (0)::bigint) AS "observations"
   FROM "bounds";


ALTER VIEW "public"."sat_ndvi_scale" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sat_season_coverage" WITH ("security_invoker"='true') AS
 SELECT "o"."subject_type",
    "o"."subject_id",
    COALESCE("f"."name", "p"."name") AS "name",
    (EXTRACT("year" FROM "o"."sensed_on"))::integer AS "season",
    "count"(*) FILTER (WHERE ("o"."quality" = 'full'::"text")) AS "full_looks",
    "count"(*) FILTER (WHERE ("o"."quality" = 'partial'::"text")) AS "partial_looks",
    "count"(*) FILTER (WHERE ("o"."quality" = 'rejected'::"text")) AS "rejected_looks",
    "count"(*) AS "scenes_examined",
    "round"("avg"("o"."valid_fraction") FILTER (WHERE ("o"."quality" <> 'rejected'::"text")), 3) AS "mean_valid_fraction",
    "min"("o"."sensed_on") AS "first_look",
    "max"("o"."sensed_on") FILTER (WHERE ("o"."quality" <> 'rejected'::"text")) AS "last_usable_look"
   FROM (("public"."sat_observations" "o"
     LEFT JOIN "public"."fields" "f" ON ((("f"."id" = "o"."subject_id") AND ("o"."subject_type" = 'field'::"text"))))
     LEFT JOIN "public"."pastures" "p" ON ((("p"."id" = "o"."subject_id") AND ("o"."subject_type" = 'pasture'::"text"))))
  GROUP BY "o"."subject_type", "o"."subject_id", COALESCE("f"."name", "p"."name"), ((EXTRACT("year" FROM "o"."sensed_on"))::integer);


ALTER VIEW "public"."sat_season_coverage" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sat_zone_readiness" WITH ("security_invoker"='true') AS
 WITH "by_season" AS (
         SELECT "o"."subject_type",
            "o"."subject_id",
            (EXTRACT("year" FROM "o"."sensed_on"))::integer AS "season",
            "count"(*) FILTER (WHERE (("o"."quality" = 'full'::"text") AND "o"."harmonized")) AS "full_looks"
           FROM "public"."sat_observations" "o"
          WHERE ("o"."ndvi_mean" IS NOT NULL)
          GROUP BY "o"."subject_type", "o"."subject_id", ((EXTRACT("year" FROM "o"."sensed_on"))::integer)
        )
 SELECT "f"."id" AS "field_id",
    "f"."name",
    "count"(*) FILTER (WHERE ("s"."full_looks" >= 8)) AS "qualifying_seasons",
    COALESCE("max"("s"."full_looks"), (0)::bigint) AS "best_season_looks",
    COALESCE("sum"("s"."full_looks"), (0)::numeric) AS "total_full_looks",
    ("count"(*) FILTER (WHERE ("s"."full_looks" >= 8)) >= 2) AS "zones_may_be_generated"
   FROM ("public"."fields" "f"
     LEFT JOIN "by_season" "s" ON ((("s"."subject_id" = "f"."id") AND ("s"."subject_type" = 'field'::"text"))))
  WHERE ("f"."active" AND "f"."satellite_enabled")
  GROUP BY "f"."id", "f"."name";


ALTER VIEW "public"."sat_zone_readiness" OWNER TO "postgres";


