CREATE OR REPLACE VIEW "public"."tasks_with_assignees" WITH ("security_invoker"='true') AS
 SELECT "id",
    "title",
    "description_md",
    "field_id",
    "created_by",
    "due_at",
    "reminder_at",
    "reminder_sent",
    "status",
    "completed_at",
    "completed_by",
    "parent_task_id",
    "source",
    "source_ref",
    "crop_year",
    "created_at",
    COALESCE(( SELECT "array_agg"("a"."user_id" ORDER BY "u"."full_name") AS "array_agg"
           FROM ("public"."task_assignees" "a"
             JOIN "public"."users" "u" ON (("u"."id" = "a"."user_id")))
