CREATE OR REPLACE VIEW "public"."water_quality_summary" WITH ("security_invoker"='true') AS
 WITH "w" AS (
         SELECT "s"."id",
            "s"."source",
            "s"."station_id",
            "s"."sampled_at",
            "s"."parameter",
            "s"."value",
            "s"."below_dl",
            "s"."unit",
            "s"."created_at",
            (EXTRACT("year" FROM ("s"."sampled_at" AT TIME ZONE 'America/Edmonton'::"text")))::integer AS "season",
            (((EXTRACT("month" FROM ("s"."sampled_at" AT TIME ZONE 'America/Edmonton'::"text")))::integer >= 4) AND ((EXTRACT("month" FROM ("s"."sampled_at" AT TIME ZONE 'America/Edmonton'::"text")))::integer <= 10)) AS "irrigating"
           FROM "public"."water_quality_samples" "s"
          WHERE ("s"."sampled_at" >= "make_date"(((EXTRACT("year" FROM "now"()))::integer - 5), 1, 1))
        ), "ranked" AS (
         SELECT "w"."id",
            "w"."source",
            "w"."station_id",
            "w"."sampled_at",
            "w"."parameter",
            "w"."value",
            "w"."below_dl",
            "w"."unit",
            "w"."created_at",
            "w"."season",
            "w"."irrigating",
            "row_number"() OVER (PARTITION BY "w"."station_id", "w"."parameter" ORDER BY "w"."sampled_at" DESC) AS "newest",
            "row_number"() OVER (PARTITION BY "w"."station_id", "w"."parameter" ORDER BY
                CASE
                    WHEN "w"."below_dl" THEN NULL::numeric
                    ELSE "w"."value"
                END DESC NULLS LAST, "w"."sampled_at" DESC) AS "highest",
            "row_number"() OVER (PARTITION BY "w"."station_id", "w"."parameter" ORDER BY
                CASE
                    WHEN ("w"."below_dl" OR (NOT "w"."irrigating")) THEN NULL::numeric
                    ELSE "w"."value"
                END DESC NULLS LAST, "w"."sampled_at" DESC) AS "highest_irr"
           FROM "w"
        ), "seasons" AS (
         SELECT "w"."station_id",
            "w"."parameter",
            "w"."season",
            "exp"("avg"("ln"(GREATEST("w"."value", (1)::numeric)))) AS "geomean",
            "count"(*) AS "n"
           FROM "w"
          WHERE ((NOT "w"."below_dl") AND ("w"."parameter" = ANY (ARRAY['ecoli'::"text", 'fecal_coliform'::"text"])))
          GROUP BY "w"."station_id", "w"."parameter", "w"."season"
        )
 SELECT "station_id",
    "parameter",
    "count"(*) AS "tested",
    "count"(*) FILTER (WHERE (NOT "below_dl")) AS "detected",
    "max"("value") FILTER (WHERE (("highest" = 1) AND (NOT "below_dl"))) AS "max_value",
    "max"("sampled_at") FILTER (WHERE (("highest" = 1) AND (NOT "below_dl"))) AS "max_at",
    "min"("value") FILTER (WHERE "below_dl") AS "min_dl",
    "max"("value") FILTER (WHERE "below_dl") AS "max_dl",
    "max"("value") FILTER (WHERE ("newest" = 1)) AS "latest_value",
    "bool_or"("below_dl") FILTER (WHERE ("newest" = 1)) AS "latest_below",
    "max"("sampled_at") AS "latest_at",
    "min"("sampled_at") AS "first_at",
    ( SELECT "max"("x"."geomean") AS "max"
           FROM "seasons" "x"
          WHERE (("x"."station_id" = "r"."station_id") AND ("x"."parameter" = "r"."parameter"))) AS "max_season_geomean",
    "max"("unit") AS "unit",
    "max"("value") FILTER (WHERE (("highest_irr" = 1) AND (NOT "below_dl") AND "irrigating")) AS "irr_max_value",
    "max"("sampled_at") FILTER (WHERE (("highest_irr" = 1) AND (NOT "below_dl") AND "irrigating")) AS "irr_max_at"
   FROM "ranked" "r"
  GROUP BY "station_id", "parameter";


ALTER VIEW "public"."water_quality_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."water_s_credit" WITH ("security_invoker"='true') AS
 WITH "season" AS (
         SELECT "st"."water_source",
            "s"."parameter",
            "s"."value",
            "s"."below_dl",
            "s"."sampled_at"
           FROM ("public"."water_quality_samples" "s"
             JOIN "public"."water_quality_stations" "st" ON (("st"."station_id" = "s"."station_id")))
          WHERE ("st"."for_credit" AND ("st"."water_source" IS NOT NULL) AND ((EXTRACT("month" FROM ("s"."sampled_at" AT TIME ZONE 'America/Edmonton'::"text")) >= (5)::numeric) AND (EXTRACT("month" FROM ("s"."sampled_at" AT TIME ZONE 'America/Edmonton'::"text")) <= (9)::numeric)) AND ("s"."sampled_at" >= "make_date"(((EXTRACT("year" FROM "now"()))::integer - 5), 1, 1)))
        )
 SELECT "water_source",
    "round"((("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("value")::double precision)) FILTER (WHERE ("parameter" = 'so4_mg_l'::"text")))::numeric * 0.0756), 2) AS "lb_s_per_inch",
    "round"(("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("value")::double precision)) FILTER (WHERE ("parameter" = 'so4_mg_l'::"text")))::numeric, 1) AS "so4_median_mg_l",
    "count"(*) FILTER (WHERE ("parameter" = 'so4_mg_l'::"text")) AS "so4_samples",
    "round"(("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("value")::double precision)) FILTER (WHERE ("parameter" = 'no3n_mg_l'::"text")))::numeric, 3) AS "no3n_median_mg_l",
    "bool_and"("below_dl") FILTER (WHERE ("parameter" = 'no3n_mg_l'::"text")) AS "no3n_all_below_dl",
    "round"(("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("value")::double precision)) FILTER (WHERE ("parameter" = 'ec_us_cm'::"text")))::numeric) AS "ec_median_us_cm",
    "round"(("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("value")::double precision)) FILTER (WHERE ("parameter" = 'sar'::"text")))::numeric, 2) AS "sar_median",
    "max"("sampled_at") AS "latest_sample"
   FROM "season"
  GROUP BY "water_source";


ALTER VIEW "public"."water_s_credit" OWNER TO "postgres";


